(function(root){
  'use strict';
  var bank=root.QUESTION_BANK=root.QUESTION_BANK||[];
  var EXPLANATIONS={
  "math_g4_hand_quad_026":"４つの角の和は 360度で、すべて等しければ、1つが 90度の直角です。向かい合う辺が２組とも平行で、４つの角が直角の四角形は、長方形です。\n\nほかの 選択肢\n・「ひし形」…4つの辺は等しいですが、角が直角とは限りません。\n・「台形」…向かい合う辺が１組しか平行ではありません。\n・「平行四辺形」…向かい合う辺は２組とも平行ですが、角が直角とは限りません。",
  "math_g4_hand_quad_027":"４つの角がすべて直角になる四角形は、長方形と、その仲間の正方形です。答えは「正方形と長方形」です。\n\nほかの 選択肢\n・「正方形とひし形」…ひし形は、角が直角でないこともあります。\n・「ひし形と平行四辺形」…どちらも、角が直角でないこともあります。\n・「長方形とひし形」…長方形の角は直角ですが、ひし形の角は直角とは限りません。",
  "math_g4_hand_quad_028":"１周のまわりの長さは（９＋６）×２＝30（cm）です。２周まくので、30×２＝60（cm）のテープがいります。\n\nほかの 選択肢\n・「30」…１周分の長さです。２周まくので、２倍します。\n・「54」…９×６ で、かけた数です。まわりの長さは、辺の長さを足します。\n・「90」…30×３ のように、３周分の長さです。まくのは２周です。",
  "math_g4_hand_quad_029":"ひし形も平行四辺形の仲間なので、となり合う角の和は 180度です。角Ａが 50度のとき、角Ｂは 180－50＝130（度）です。\n\nほかの 選択肢\n・「50」…向かい合う角（角Ｃ）の大きさです。となり合う角Ｂではありません。\n・「90」…直角の大きさです。ひし形の角は、直角とは限りません。\n・「230」…180＋50 と、足してしまった数です。となり合う角は、180 から引きます。",
  "math_g4_hand_quad_030":"正方形ＡＢＣＤで、辺ＡＢに平行なのは向かい合う辺ＤＣの１本、垂直なのはとなり合う辺ＡＤとＢＣの２本です。答えは「平行１本、垂直２本」です。\n\nほかの 選択肢\n・「平行２本、垂直１本」…平行と垂直の数が入れかわっています。向かい合う辺は１本、となり合う辺は２本です。\n・「平行１本、垂直１本」…垂直な辺は、ＡＤとＢＣの２本です。\n・「平行２本、垂直２本」…平行な辺は、向かい合うＤＣの１本だけです。",
  "math_g4_hand_ratio_001":"12 が３の何倍かは、12÷３＝４ で求めます。３×４＝12 なので、12 は３の４倍です。\n\nほかの 選択肢\n・「9」…12－３ の、ちがいです。何倍かは、わり算で求めます。\n・「15」…12＋３ と、足してしまった数です。何倍かは、わり算で求めます。\n・「8」…３×８＝24 で、12 になりません。12÷３ は４です。",
  "math_g4_hand_ratio_002":"５の６倍は、５に６をかけて求めます。５×６＝30 です。\n\nほかの 選択肢\n・「11」…５＋６ と、足してしまった数です。「６倍」は、かけ算です。\n・「25」…５×５ のように、かける数をまちがえた数です。かけるのは６です。\n・「36」…６×６ のように、もとの数をまちがえた数です。もとの数は５です。",
  "math_g4_hand_ratio_003":"40cm が 10cm の何倍かは、40÷10＝４ で求めます。10×４＝40 なので、40cm のひもは 10cm のひもの４倍です。\n\nほかの 選択肢\n・「30」…40－10 の、ちがいです。何倍かは、わり算で求めます。\n・「400」…40×10 と、かけてしまった数です。何倍かは、わり算で求めます。\n・「50」…40＋10 と、足してしまった数です。何倍かは、わり算で求めます。",
  "math_g4_hand_ratio_004":"2m のひもの3倍の長さは、2に3をかけて求めます。2×3＝6（m）です。\n\nほかの 選択肢\n・「5」…２＋３ と、足してしまった数です。「３倍」は、かけ算です。\n・「8」…２×４ のように、かける数をまちがえた数です。かけるのは３です。\n・「9」…３×３ のように、もとの数をまちがえた数です。もとの長さは２m です。",
  "math_g4_hand_ratio_005":"お兄さんのあめ 36 こは、弟のあめの4倍です。弟のあめは、36 を4でわって求めます。36÷4＝9（こ）です。9×4＝36 で確かめられます。\n\nほかの 選択肢\n・「32」…36－４ と、引いてしまった数です。「４倍」は、わり算で、もとの数を求めます。\n・「40」…36＋４ と、足してしまった数です。「４倍」は、わり算で、もとの数を求めます。\n・「12」…36÷３ のように、わる数をまちがえた数です。４倍なので、４でわります。",
  "math_g4_hand_ratio_006":"白いボールが赤いボールの何倍かは、白の数を赤の数でわって、45÷15＝３ です。15×３＝45 なので、白いボールは赤いボールの３倍です。\n\nほかの 選択肢\n・「2」…15×２＝30 で、45 になりません。45÷15 は３です。\n・「4」…15×４＝60 で、45 をこえてしまいます。\n・「30」…45－15 の、ちがいです。何倍かは、わり算で求めます。",
  "math_g4_hand_ratio_007":"ＡはＢの３倍で、Ｂが８なので、Ａ＝８×３＝24 です。倍の数は、かけて求めます。\n\nほかの 選択肢\n・「11」…８＋３ と、足してしまった数です。「３倍」は、かけ算です。\n・「27」…24＋３ のように、さらに足してしまった数です。８×３＝24 で終わりです。\n・「32」…８×４ のように、かける数をまちがえた数です。かけるのは３です。",
  "math_g4_hand_ratio_008":"ＡはＢの5倍で、Ａが 45 なので、Ｂ＝45÷5＝9 です。9×5＝45 で確かめられます。\n\nほかの 選択肢\n・「40」…45－５ と、引いてしまった数です。もとの数を求めるときは、わり算です。\n・「50」…45＋５ と、足してしまった数です。もとの数を求めるときは、わり算です。\n・「15」…45÷３ のように、わる数をまちがえた数です。５倍なので、５でわります。",
  "math_g4_hand_ratio_009":"バナナの値段がりんごの何倍かは、バナナの値段をりんごの値段でわって、120÷40＝3 です。40×3＝120 なので、バナナはりんごの3倍の値段です。\n\nほかの 選択肢\n・「2」…40×２＝80 で、120 になりません。120÷40 は３です。\n・「4」…40×４＝160 で、120 をこえてしまいます。\n・「80」…120－40 の、ねだんのちがいです。何倍かは、わり算で求めます。",
  "math_g4_hand_ratio_010":"30 分が５分の何倍かは、30÷５＝６ で求めます。５×６＝30 なので、30 分は５分の６倍です。\n\nほかの 選択肢\n・「5」…もとにする５分の数そのものです。何倍かは、わり算で求めます。\n・「7」…５×７＝35 で、30 になりません。30÷５ は６です。\n・「12」…５×12＝60 で、30 をこえてしまいます。",
  "math_g4_hand_ratio_011":"「何倍」のねだんは、かけ算で求めます。80円の５倍なので、80×5＝400で、400円です。\n\nほかの 選択肢\n・「320」…80×4の答えです。４倍にしてしまった数なので、５倍の問いではちがいます。\n・「480」…80×6の答えです。６倍にしてしまった数なので、ちがいます。\n・「4000」…0を１つ多くつけてしまった数です。80×5を正しく計算すると400になります。",
  "math_g4_hand_ratio_012":"250×4＝1000、100×10＝1000なので、どちらも1000で、ちょうど同じ大きさです。数が大きく見えても、かけ算の答えをくらべることが大切です。\n\nほかの 選択肢\n・「250の４倍」…こちらのほうが大きいという答えですが、100の10倍も1000なので、大きさはちがいません。\n・「100の10倍」…こちらのほうが大きいという答えですが、250の４倍も1000で同じです。\n・「くらべられない」…計算すれば、どちらも1000と答えが出るので、くらべられます。",
  "math_g4_hand_ratio_013":"ＣからＢ、ＢからＡと順に求めます。Ｂ（Ｃの２倍）は500×2＝1000円、Ａ（Ｂの３倍）は1000×3＝3000円です。\n\nほかの 選択肢\n・「1500」…500×3の答えです。ＡをＣの３倍と考えてしまった数ですが、ＡはＢの３倍です。\n・「2500」…２倍と３倍をたして５倍にして、500×5と計算した数です。倍は、たさずにかけます。\n・「1000」…Ｂさんのお金です。Ａさんのお金を求めるには、さらに３倍する必要があります。",
  "math_g4_hand_ratio_014":"今年は去年の４倍なので、今年÷４で去年の数が求められます。120÷4＝30で、去年は30こです。\n\nほかの 選択肢\n・「124」…120＋4の答えです。「４倍」はたし算ではなく、かけ算・わり算で考えます。\n・「116」…120－4の答えです。倍の関係なので、ひき算ではありません。\n・「40」…120÷3の答えです。わる数を３にしてしまった数で、「４倍」なので４でわります。",
  "math_g4_hand_ratio_015":"弟を１とすると、兄は３なので、２人合わせて４つ分です。40÷4＝10で、弟は10円です。兄は30円で、10＋30＝40と合うので正しいです。\n\nほかの 選択肢\n・「13」…40÷3＝13あまり１の数です。３でわってしまいましたが、合計は弟の３＋１＝４つ分です。\n・「20」…40÷2の答えです。２人だから２でわったものですが、兄のほうが３倍多いので同じ金額にはなりません。\n・「30」…兄のお金です。問いで求めるのは弟のお金なので、ちがいます。",
  "math_g4_hand_ratio_016":"順に求めます。Ｂは4×3＝12m。ＣはＢより５m短いので、12－5＝7mです。\n\nほかの 選択肢\n・「12」…Ｂのロープの長さです。Ｃは、Ｂより５m短いので、さらにひき算をします。\n・「9」…4＋5の答えです。Ａにたしてしまいましたが、Ｃの長さはＢをもとに考えます。\n・「17」…12＋5の答えです。「短い」のでたすのではなく、ひきます。",
  "math_g4_hand_ratio_017":"「何倍か」は、わり算で求めます。ＣはＡの150÷30＝５倍、Ｂの150÷6＝25倍で、答えは「５倍と25倍」です。\n\nほかの 選択肢\n・「５倍と５倍」…Ａに対しては５倍で合っていますが、Ｂに対しては150÷6＝25倍で、５倍ではありません。\n・「25倍と５倍」…答えの順がぎゃくです。Ａは30と大きいほうなので、倍は小さくなります。\n・「６倍と25倍」…Ａに対する倍は150÷30＝５倍です。",
  "math_g4_hand_ratio_018":"たて３cm、横４cmの面積は3×4＝12cm²。２倍にするとたて６cm、横８cmで6×8＝48cm²。48÷12＝4で、面積は４倍です。たても横も２倍になると、2×2＝4で４倍になります。\n\nほかの 選択肢\n・「2」…長さが２倍になったことだけを見た数です。面積は、たてと横の両方が２倍になるので、2×2＝4です。\n・「8」…2×2×2のように、３回かけてしまった数です。面積は２回だけかけます。\n・「6」…48÷12＝4なので、６倍にはなりません。",
  "math_g4_hand_round_001":"百の位までのがい数にするときは、すぐ下の十の位を見ます。3452の十の位は５で５以上なので切り上げて、3500です。\n\nほかの 選択肢\n・「3400」…切り捨てた数です。十の位の５は切り上げになる数です。\n・「3000」…千の位までのがい数にした数です。問いは百の位までです。\n・「3450」…十の位までのがい数にした数です。問いは百の位までです。",
  "math_g4_hand_round_002":"四捨五入では、すぐ下の位の数が５以上のとき切り上げ、４以下のとき切り捨てます。「四捨」は４以下を捨てる、「五入」は５以上を入れる、と覚えます。\n\nほかの 選択肢\n・「４以上」…４は切り捨てになる数です。切り上げは５からなので、ちがいます。\n・「６以上」…５も切り上げるので、６からではありません。たとえば15は、５を切り上げて20になります。\n・「９以上」…９だけでなく、５〜９の数はすべて切り上げます。",
  "math_g4_hand_round_003":"十の位までのがい数にするときは、すぐ下の一の位を見ます。78の一の位は８で５以上なので切り上げて、80です。\n\nほかの 選択肢\n・「70」…切り捨てた数です。一の位の８は切り上げになる数です。\n・「78」…そのままの数で、がい数になっていません。\n・「100」…百の位までのがい数にした数です。問いは十の位までです。",
  "math_g4_hand_round_004":"千の位までのがい数にするときは、すぐ下の百の位を見ます。6240の百の位は２で４以下なので切り捨てて、6000です。\n\nほかの 選択肢\n・「7000」…切り上げた数です。百の位の２は切り捨てになる数です。\n・「6200」…百の位までのがい数にした数です。問いは千の位までです。\n・「6300」…6240を6300にするのは、十の位の４を切り上げたことになります。４は切り捨てです。",
  "math_g4_hand_round_005":"「がい」は「おおよそ」という意味で、がい数はおおよその数のことです。きっちりした数でなくても、だいたいの大きさがわかればよいときに使います。\n\nほかの 選択肢\n・「正しい数」…正確にはかったままの数です。\n・「わり切れない数」…わり算で、あまりが出る数のことです。\n・「整数でない数」…小数や分数のことです。がい数は整数でもあらわせます。",
  "math_g4_hand_round_006":"千の位までのがい数にするときは、すぐ下の百の位を見ます。4500の百の位は５で５以上なので切り上げて、5000です。\n\nほかの 選択肢\n・「4000」…切り捨てた数です。百の位の５は切り上げます。\n・「4500」…そのままの数で、千の位までのがい数になっていません。\n・「6000」…千の位を２つ上げてしまった数です。切り上げても1つ上の5000までです。",
  "math_g4_hand_round_007":"十の位までのがい数にするときは、すぐ下の一の位を見ます。49の一の位は９で５以上なので切り上げて、50です。\n\nほかの 選択肢\n・「40」…切り捨てた数です。一の位の９は切り上げになる数です。\n・「49」…そのままの数で、がい数になっていません。\n・「60」…切り上げを２回してしまった数です。49は50に近いです。",
  "math_g4_hand_round_008":"上から１けたのがい数にするときは、上から２けた目を見ます。27648の上から２けた目は千の位の７で、５以上なので切り上げて、30000です。\n\nほかの 選択肢\n・「20000」…切り捨てた数です。千の位の７は切り上げになる数です。\n・「28000」…上から２けたのがい数です。問いは上から１けたです。\n・「27000」…百の位以下を切り捨てた数で、四捨五入にはなっていません。",
  "math_g4_hand_round_009":"上から２けたのがい数にするときは、上から３けた目を見ます。4562の上から３けた目は十の位の６で、５以上なので切り上げて、4600です。\n\nほかの 選択肢\n・「4500」…切り捨てた数です。十の位の６は切り上げになる数です。\n・「4560」…上から３けたのがい数です。問いは上から２けたです。\n・「5000」…上から１けたのがい数です。問いは上から２けたです。",
  "math_g4_hand_round_010":"235÷50＝４あまり35です。４台だとのれない人が35人のこるので、もう１台必要です。全員がのるには、5台です。このように、あまりの分も入れる考え方が「切り上げ」です。\n\nほかの 選択肢\n・「4」…あまりの35人がのれません。４台だと200人までです。\n・「6」…５台で250人までのれるので、６台は多すぎます。\n・「7」…多すぎます。５台で足りるので、７台はいりません。",
  "math_g4_hand_round_011":"1000÷120＝８あまり40です。９こ買うと120×9＝1080円で、1000円をこえて足りません。買えるのは８こで、これが「切り捨て」の考え方です。\n\nほかの 選択肢\n・「9」…切り上げた数です。９こだと1080円になり、お金が足りません。\n・「10」…1000÷100のように計算した数です。おにぎりは１こ120円です。\n・「7」…少なすぎます。７こなら840円で、まだ買えます。",
  "math_g4_hand_round_012":"千の位までのがい数にします。3980は百の位が９で切り上げて4000、5120は百の位が１で切り捨てて5000です。4000＋5000＝9000円です。\n\nほかの 選択肢\n・「8000」…3980を3000にしてしまった数です。百の位の９は切り上げます。\n・「10000」…5120を6000にしてしまった数です。百の位の１は切り捨てます。\n・「9100」…3980＋5120をそのまま足した正しい合計です。問いはがい数にしてから足します。",
  "math_g4_hand_round_013":"598を600と見て、600×6＝3600です。598×6＝3588なので、3600は実際の答えにとても近い、よい見積もりです。\n\nほかの 選択肢\n・「3000」…600×5のように計算した数です。６倍にするので、600×6です。\n・「3588」…598×6をそのまま計算した、くわしい答えです。問いは見積もりです。\n・「3500」…600×6は3600なので、3500にはなりません。",
  "math_g4_hand_round_014":"百の位までのがい数が5000になるのは、4950以上5049以下の数です。十の位が４までなら切り捨てて5000になるので、いちばん大きいのは5049です。\n\nほかの 選択肢\n・「5000」…5000も5000になりますが、5049のほうが大きいので、いちばん大きい数ではありません。\n・「5050」…十の位が５なので切り上げて5100になり、5000にはなりません。\n・「4999」…5000になりますが、5049より小さいので、いちばん大きい数ではありません。",
  "math_g4_hand_round_015":"「以上」はその数をふくみ、「未満」はふくみません。100以上200未満は、100も入り、200は入りません。100がいちばん小さい数です。\n\nほかの 選択肢\n・「99」…100より小さいので、100以上には入りません。\n・「101」…100のほうが小さく、100も入るので、いちばん小さい数ではありません。\n・「200」…200未満は200をふくまないし、いちばん大きいほうの数です。",
  "math_g4_hand_round_016":"千の位までのがい数は、百の位を見ます。3600は百の位が６で切り上げて4000になります。ほかは、3400が3000、4600が5000、4500が5000になります。\n\nほかの 選択肢\n・「3400」…百の位の４は切り捨てなので、3000になります。\n・「4600」…百の位の６は切り上げなので、5000になります。\n・「4500」…百の位の５は切り上げなので、5000になります。4000ではありません。",
  "math_g4_hand_round_017":"万の位までのがい数にするときは、すぐ下の千の位を見ます。23547の千の位は３で４以下なので切り捨てて、20000人です。\n\nほかの 選択肢\n・「24000」…千の位までのがい数です。問いは万の位までです。\n・「23000」…千の位までを切り捨てた数です。問いは万の位までなので、千の位を見て四捨五入します。\n・「30000」…切り上げた数です。千の位の３は切り捨てです。",
  "math_g4_hand_round_018":"上から１けたのがい数にするときは、上から２けた目を見ます。3470の上から２けた目は百の位の４で、切り捨てて、3000です。\n\nほかの 選択肢\n・「3500」…上から２けたのがい数です。問いは上から１けたです。\n・「3400」…十の位以下を切り捨てた数です。上から１けたにするには、百の位以下をまとめて考えます。\n・「4000」…切り上げた数です。百の位の４は切り捨てです。",
  "math_g4_hand_round_019":"百の位までのがい数が3500になる数は、3450以上3549以下です。3450は十の位の５を切り上げて3500、3550は3600になるので入りません。\n\nほかの 選択肢\n・「3500以上3599以下」…3550〜3599は切り上げて3600になるので、ちがいます。\n・「3400以上3499以下」…3400〜3449は3400になるので、はんいがずれています。\n・「3450以上3550以下」…3550は十の位が５で切り上げて3600になるので、ふくめません。",
  "math_g4_hand_round_020":"十の位までのがい数が60になる数は、55以上64以下です。55は一の位の５を切り上げて60、65は70になるので入りません。64－55＋1＝10で、10こです。\n\nほかの 選択肢\n・「9」…64－55だけで、はしの55をたしわすれた数です。55から64まで数えると10こです。\n・「11」…65まで入れた数です。65は切り上げて70になります。\n・「5」…55〜59の５こだけです。切り捨ててあわせる60〜64もあります。",
  "math_g4_hand_round_021":"それぞれ百の位までのがい数にします。498は500、302は300、1198は1200です。500＋300＋1200＝2000で、およそ2000円です。\n\nほかの 選択肢\n・「1900」…どれかを切り捨てすぎた数です。498は500、302は300、1198は1200と四捨五入します。\n・「2100」…どれかを切り上げすぎた数です。302は十の位が０なので、300です。\n・「1998」…498＋302＋1198をそのまま足した正しい合計です。問いはがい数にして見積もります。",
  "math_g4_hand_round_022":"183÷40＝４あまり23です。４台では23人がのれないので、もう１台必要です。全員がのるには5台です。あまりの分も入れる「切り上げ」の考え方です。\n\nほかの 選択肢\n・「4」…あまりの23人がのれません。４台だと160人までです。\n・「6」…５台で200人までのれるので、６台は多すぎます。\n・「3」…３台だと120人までで、183人はのれません。",
  "math_g4_hand_round_023":"47÷5＝９あまり２です。９はりだと45人までなので、あまりの２人のためにもう１はり必要で、10はりです。切り上げの考え方です。\n\nほかの 選択肢\n・「9」…あまりの２人が入れません。９はりだと45人までです。\n・「11」…10はりで50人まで入れるので、11はりは多すぎます。\n・「8」…少なすぎます。８はりだと40人までで、47人は入れません。",
  "math_g4_hand_round_024":"それぞれ百の位までのがい数にして、298は300、385は400、217は200です。300＋400＋200＝900円で、1000円より少ないので、代金は足りる、が答えです。\n\nほかの 選択肢\n・「足りない」…見積もりの合計が900円で、1000円より少ないので、足ります。\n・「ちょうどになる」…900円は1000円とちょうど同じではありません。\n・「200円足りない」…足りなくなるのではなく、1000－900＝100円あまります。",
  "math_g4_hand_round_025":"千の位までのがい数が12000になる数は、11500以上12499以下です。11500は百の位の５を切り上げて12000、12500は13000になるので入りません。\n\nほかの 選択肢\n・「12000以上12999以下」…12500〜12999は13000になるので、ちがいます。\n・「11000以上11999以下」…11000〜11499は11000になるので、はんいがずれています。\n・「11500以上12500以下」…12500は百の位が５で切り上げて13000になるので、ふくめません。",
  "math_g4_hand_round_026":"百の位までのがい数が400になる数は、350以上449以下です。３けたの数でいちばん小さいのは、十の位の５を切り上げて400になる350です。\n\nほかの 選択肢\n・「300」…四捨五入すると300のままで、400にはなりません。\n・「349」…十の位が４なので切り捨てて300になり、400にはなりません。\n・「399」…四捨五入すると400になりますが、350のほうが小さいので、いちばん小さい数ではありません。",
  "math_g4_hand_round_027":"十の位までのがい数が350になるのは、345以上354以下です。355は一の位の５を切り上げて360になるので入りません。いちばん大きいのは354です。\n\nほかの 選択肢\n・「349」…350になりますが、354のほうが大きいので、いちばん大きい数ではありません。\n・「355」…一の位が５なので切り上げて360になり、350にはなりません。\n・「359」…一の位が９なので切り上げて360になり、350にはなりません。",
  "math_g4_hand_round_028":"それぞれ上から１けたのがい数にして、4180は4000、39は40です。4000×40＝160000で、およそ160000です。\n\nほかの 選択肢\n・「120000」…39を30にしてしまった数です。39は一の位の９を切り上げて40です。\n・「156000」…4000×39の答えです。39もがい数にして40にしてから計算します。\n・「200000」…4180を5000にしてしまった数です。4180は百の位が１で切り捨てて4000です。",
  "math_g4_hand_round_029":"2500÷1000＝２あまり500です。２こだと500mlの水が入りきれないので、もう１こ必要で、３こです。切り上げの考え方です。\n\nほかの 選択肢\n・「2」…あまりの500mlが入りません。２こだと2000mlまでです。\n・「4」…３こで3000mlまで入るので、４こは多すぎます。\n・「6」…多すぎます。３こで足りるので、６こはいりません。",
  "math_g4_hand_solid_001":"直方体の向かい合う面は、「同じ形で、同じ大きさ」になっています。たとえば上の面と下の面は、どちらも同じ長方形です。\n\nほかの 選択肢\n・「同じ形だが大きさはちがう」…向かい合う面は、形も大きさも同じなので、ちがいます。\n・「同じ大きさだが形はちがう」…大きさが同じなら、形も同じです。\n・「形も大きさもちがう」…向かい合う面は、形も大きさも同じです。ちがうのは、となり合う面です。",
  "math_g4_hand_solid_002":"立方体の頂点には、たて・横・高さの３本の辺が集まります。どの頂点でも同じで、3本です。\n\nほかの 選択肢\n・「2」…平面の四角形のかどでは２本の辺が集まりますが、立方体には高さの辺もあり、３本です。\n・「4」…１つの面の辺の数です。頂点に集まる辺の数ではありません。\n・「6」…面の数です。頂点に集まる辺の数ではありません。",
  "math_g4_hand_solid_003":"立方体の１つの面と平行なのは向かい側の１面だけで、残りの４つの面が、まわりをかこんで垂直になっています。垂直な面は4つです。\n\nほかの 選択肢\n・「2」…向かい側の面と同じように、２つだと思ってしまった数です。まわりに４つあります。\n・「3」…３つの面は、１つの頂点に集まる面の数です。垂直な面は４つです。\n・「6」…立方体の面の全部の数です。自分自身と、平行な向かいの面は垂直ではありません。",
  "math_g4_hand_solid_004":"直方体は、向かい合う２つの面が同じ大きさです。上下、前後、左右の3組あります。\n\nほかの 選択肢\n・「2」…少なすぎます。上下、前後、左右で、３組あります。\n・「4」…多すぎます。向かい合う面で数えるので、３組です。\n・「6」…面の数です。２つ１組で数えるので、組の数は３です。",
  "math_g4_hand_solid_005":"直方体の12本の辺は、たて・横・高さの長さごとに４本ずつあります。たて４cmの辺は、4本あります。\n\nほかの 選択肢\n・「2」…少なすぎます。たての辺は、手前と奥の左右で４本です。\n・「3」…長さの種類の数です。長さが４cmの辺の本数ではありません。\n・「8」…多すぎます。同じ長さの辺は４本ずつです。",
  "math_g4_hand_solid_006":"立方体の面は６つで、展開図はその６つの面を切り開いた形です。正方形が6まいつながっています。\n\nほかの 選択肢\n・「4」…側面の数です。上と下の面も必要なので、６まいです。\n・「8」…頂点の数です。展開図の正方形の数ではありません。\n・「12」…辺の数です。展開図の正方形の数ではありません。",
  "math_g4_hand_solid_007":"立体で、面と面が交わっている線を「辺」といいます。立方体や直方体には12本あります。\n\nほかの 選択肢\n・「頂点」…辺と辺が集まる、かどの点です。\n・「面」…平らな部分のことです。\n・「角」…２本の直線が作るかどの大きさのことで、立体の線の名前ではありません。",
  "math_g4_hand_solid_008":"立方体の辺は12本で、どれも８cmです。8×12＝96cmです。\n\nほかの 選択肢\n・「64」…8×8の答えです。辺の数の12を使っていません。\n・「48」…8×6の答えです。６は面の数で、辺の数は12です。\n・「144」…辺の本数を多く数えまちがえた数です。辺は12本です。",
  "math_g4_hand_solid_009":"立方体の面は、すべて同じ正方形です。１つの面は5×5＝25cm²で、面は６つあるので、25×6＝150cm²です。\n\nほかの 選択肢\n・「100」…25×4の答えです。まわりの４つの面だけで、上と下の面を数えていません。\n・「125」…5×5×5の答えです。体積の計算で、面積の合計ではありません。\n・「75」…25×3の答えです。３つの面だけで、残りの３つを数えていません。",
  "math_g4_hand_solid_010":"上の面は、たて６cm、横４cmの長方形です。長方形の面積は「たて×横」なので、6×4＝24cm²です。高さは使いません。\n\nほかの 選択肢\n・「12」…4×3の答えです。横と高さの面（側面）の面積です。\n・「18」…6×3の答えです。たてと高さの面（側面）の面積です。\n・「48」…上の面と下の面を合わせた24×2の答えです。問いは上の面だけです。",
  "math_g4_hand_solid_011":"展開図を組み立てると、前と後ろの面が、横６cm・高さ３cmの長方形になります。向かい合う面は同じ大きさなので、答えは2まいです。\n\nほかの 選択肢\n・「1」…向かい合う面は同じ大きさのペアなので、１まいだけということはありません。\n・「3」…直方体の面は、大きさのちがう３組（２まいずつ）です。同じ大きさの面は２まいです。\n・「4」…まわりの側面の数です。たて４cm・横６cmの面などもまざっているので、ちがいます。",
  "math_g4_hand_solid_012":"見えない辺を点線でかいて、立体の全体がわかるようにかいた図が「見取り図」です。立体のようすを一目で見られます。\n\nほかの 選択肢\n・「展開図」…立体を辺で切り開いて、平面に広げた図です。\n・「平面図」…真上から見た形をかいた図で、立体全体はあらわせません。\n・「切り口の図」…立体を切ったときの切り口の形をかいた図です。",
  "math_g4_hand_solid_013":"直方体では、同じ向きの辺は４本ずつあります。ある１本に平行なのは、その辺をのぞいた残りの3本です。\n\nほかの 選択肢\n・「1」…少なすぎます。同じ向きの辺は４本あるので、のぞいた３本が平行です。\n・「2」…少なすぎます。たとえば、たての辺は、ほかに３本あります。\n・「4」…その辺自身も入れた数です。問いは「その辺のほかに」なので、のぞきます。",
  "math_g4_hand_solid_014":"直方体の１つの面の４つの頂点から、それぞれ面に垂直な辺が１本ずつ出ています。全部で4本です。\n\nほかの 選択肢\n・「2」…少なすぎます。面の頂点は４つなので、４本です。\n・「6」…面の数です。辺の本数ではありません。\n・「8」…頂点の数です。垂直な辺は、そのうち面の４つの頂点から出ている４本です。",
  "math_g4_hand_solid_015":"ひごは辺、ねん土玉は頂点の代わりです。直方体の辺は12本、頂点は８つなので、ひご12本、ねん土玉８こが必要です。\n\nほかの 選択肢\n・「ひご８本、ねん土玉12こ」…辺と頂点の数がぎゃくです。辺は12本、頂点は８つです。\n・「ひご６本、ねん土玉８こ」…ひごが６本だと、面の数と同じになってしまいます。辺は12本です。\n・「ひご12本、ねん土玉６こ」…ねん土玉が６こだと、面の数と同じです。",
  "math_g4_hand_solid_016":"上の面は、たて30cm、横20cmです。30÷10＝3まい、20÷10＝2まいならぶので、3×2＝6まいです。\n\nほかの 選択肢\n・「3」…たての３まいだけの数です。横にも２列ならびます。\n・「5」…3＋2のように、たし算にしてしまった数です。ならべるまい数は、かけ算で求めます。\n・「12」…3×2×2のように、さらにかけた数です。上の面にならべるのは、１だんだけです。",
  "math_g4_hand_solid_017":"たて・横・高さのひごが４本ずつなので、まず４＋３＋２＝９cm。その４本分で、9×4＝36cmです。\n\nほかの 選択肢\n・「18」…9×2の答えです。ひごは４本ずつ使うので、９cmを４倍します。\n・「24」…4×3×2の答えで、体積のような計算です。ひごの長さの合計は、たし算とかけ算で求めます。\n・「27」…9×3の答えです。３倍ではなく、４本ずつなので４倍です。",
  "math_g4_hand_solid_018":"向かい合う面の目の数を合わせると７になります。１と合わせて７になるのは、7－1＝6です。１の向かい側は、6の目です。\n\nほかの 選択肢\n・「5」…2と合わせて７になる数です。１と合わせて７にはなりません。\n・「2」…5と合わせて７になる数です。１との合計は３にしかなりません。\n・「7」…向かい合う面の目の合計です。さいころには７の目はありません。",
  "math_g4_hand_solid_019":"部屋の直方体で、ゆかの向かい側にあるのが、てんじょうです。向かい合う面は平行です。\n\nほかの 選択肢\n・「前のかべ」…ゆかとは直角に交わっています。平行ではなく、垂直です。\n・「右のかべ」…ゆかとは直角に交わっているので、垂直で、平行ではありません。\n・「左のかべ」…右のかべと同じで、ゆかとは垂直です。",
  "math_g4_hand_solid_020":"立方体の展開図には、回したりひっくり返したりして重なるものを同じと数えると、11種類あります。覚えておきましょう。\n\nほかの 選択肢\n・「6」…立方体の面の数です。展開図の種類の数ではありません。\n・「8」…頂点の数です。展開図の種類の数ではありません。\n・「12」…辺の数です。展開図の種類の数は11種類で、12ではありません。",
  "math_g4_hand_solid_021":"正方形６まいの辺は全部で24本です。つながっている５か所では、辺が２本ずつ合わせて10本なので、のこりの外側の辺は24－10＝14本です。２本が１組で合わさるので、14÷2＝7組です。\n\nほかの 選択肢\n・「5」…展開図でつながっている辺の数です。組み立てて合わさるふちの辺とはちがいます。\n・「6」…面の数です。合わさる辺の組の数ではありません。\n・「12」…立方体の辺の数です。このうち５本は、展開図でつながっているので、残りの7組が合わさります。",
  "math_g4_hand_solid_022":"立方体の辺は12本で、どれも同じ長さです。60÷12＝5で、１辺は5cmです。\n\nほかの 選択肢\n・「4」…4×12＝48cmなので、60cmにはなりません。\n・「6」…6×12＝72cmなので、60cmにはなりません。\n・「10」…60÷6の答えです。６は面の数で、辺の数は12です。",
  "math_g4_hand_solid_023":"直方体の辺は、たて・横・高さが４本ずつです。52÷4＝13が、たて＋横＋高さです。13－5－4＝4で、高さは4cmです。\n\nほかの 選択肢\n・「3」…5＋4＋3＝12cmで、13にならないのでちがいます。\n・「5」…たてと同じ長さですが、5＋4＋5＝14cmで13になりません。\n・「8」…13－5の答えです。横の４cmもひく必要があります。",
  "math_g4_hand_solid_024":"横に３つならべるので、横は2×3＝6cm、たては２cm、高さも２cmです。辺はそれぞれ４本ずつなので、4×(6＋2＋2)＝40cmです。\n\nほかの 選択肢\n・「36」…4×9のような計算の数です。３つの長さの和は、6＋2＋2＝10cmです。\n・「32」…4×(6＋2)で、高さの２cmを足しわすれた数です。\n・「24」…4×(2＋2＋2)で、横を２cmのままにした数です。横は３つ分の６cmです。",
  "math_g4_hand_solid_025":"面は、たて×横、たて×高さ、横×高さが２まいずつです。12＋8＋6＝26、それが２まいずつなので、26×2＝52cm²です。\n\nほかの 選択肢\n・「24」…4×3×2の答えで、体積の計算です。面積の合計とはちがいます。\n・「26」…12＋8＋6で、３種類の面を１まいずつ足した数です。それぞれ２まいあるので２倍します。\n・「48」…12×4のように、すべての面をたて×横と同じ大きさと考えた数です。面の大きさは３種類あります。",
  "math_g4_hand_solid_026":"いちばん遠い頂点へは、横・たて・高さの順に１本ずつ進めば行けます。全部で3本です。\n\nほかの 選択肢\n・「2」…辺２本では、となりの面の頂点までしか行けません。Ｇはもっと遠いです。\n・「4」…遠回りの数です。最短なら３本で行けます。\n・「6」…遠回りの数です。最短なら３本です。",
  "math_g4_hand_solid_027":"たてに6÷2＝3こ、横に4÷2＝2こ、高さに4÷2＝2だんならびます。3×2×2＝12こ入ります。\n\nほかの 選択肢\n・「24」…6×4の答えで、箱の底の面積です。積み木の数ではありません。\n・「16」…4×4の答えです。横と高さの辺の長さをかけ、積み木の大きさを使っていません。\n・「8」…積み木１この体積（2×2×2）です。入る数ではありません。",
  "math_g4_hand_solid_028":"１だんは、たて３こ×横４こで、3×4＝12こ。それが２だんあるので、12×2＝24こです。\n\nほかの 選択肢\n・「12」…１だんだけの数です。２だんに積むので、2倍します。\n・「14」…3×4＋2のような計算の数です。２だんは、12×2です。\n・「18」…(4＋2)×3のような計算の数です。たて×横の12こを2だんにします。",
  "math_g4_hand_solid_029":"高さが４の頂点は、上の面の頂点です。上の面には頂点が４つあるので、同じ高さの頂点は4こです。\n\nほかの 選択肢\n・「1」…（３、２、４）の頂点だけです。同じ高さの頂点はほかにもあります。\n・「2」…上の面の辺の両はしの頂点だけです。上の面には頂点が４つあります。\n・「8」…直方体の頂点の全部の数です。同じ高さの頂点は、上の面の４つです。",
  "math_g4_hand_solid_030":"面積は、5×3＝15、5×2＝10、3×2＝6の3種類です。いちばん大きいのは15cm²です。\n\nほかの 選択肢\n・「6」…3×2の面積で、いちばん小さい面です。\n・「10」…5×2の面積です。5×3の15cm²のほうが大きいです。\n・「30」…15cm²の面が２まいあるので、合わせたら30cm²になります。１つの面の面積ではありません。",
  "math_g4_hand_table_001":"表で、女の子の行と、雪あそびが好きの列が交わるますを読みます。そのますの数が、女の子で好きな人の数で、9人です。\n\nほかの 選択肢\n・「6」…女の子で、雪あそびがきらいな人の数です。\n・「10」…男の子で、雪あそびが好きな人の数です。\n・「5」…男の子で、雪あそびがきらいな人の数です。",
  "math_g4_hand_table_002":"男の子は、雪あそびが好きな10人と、きらいな5人です。10＋5＝15で、男の子は15人です。\n\nほかの 選択肢\n・「10」…男の子で好きな人だけの数です。きらいな5人が入っていません。\n・「5」…男の子できらいな人だけの数です。好きな10人が入っていません。\n・「19」…男の子と女の子を合わせた、雪あそびが好きな人の数です。",
  "math_g4_hand_table_003":"表では、たてのならびを「列」、横のならびを「行」といいます。答えは、たては「列」、横は「行」です。「列」の字は、たてに並ぶ、と覚えるとよいです。\n\nほかの 選択肢\n・「たては「行」、横は「列」」…ぎゃくになっています。たてが列、横が行です。\n・「たても横も「列」」…横のならびは「行」と言います。\n・「たても横も「行」」…たてのならびは「列」と言います。",
  "math_g4_hand_table_004":"雪あそびが好きな人は、男の子の10人と女の子の9人です。10＋9＝19で、19人です。\n\nほかの 選択肢\n・「15」…男の子の全部の人数です。好きな人の数ではありません。\n・「9」…女の子で好きな人だけの数です。男の子の10人が入っていません。\n・「10」…男の子で好きな人だけの数です。女の子の9人が入っていません。",
  "math_g4_hand_table_005":"男の子は15人、女の子は9＋6＝15人です。15＋15＝30で、町の子どもは30人です。表の題にも30人とあります。\n\nほかの 選択肢\n・「15」…男の子だけ（または女の子だけ）の人数です。\n・「19」…雪あそびが好きな人の数です。きらいな人が入っていません。\n・「25」…計算をまちがえた数です。15＋15＝30です。",
  "math_g4_hand_table_006":"きらいな男の子は5人、きらいな女の子は6人です。6－5＝1で、男の子のほうが1人少ないです。\n\nほかの 選択肢\n・「5」…きらいな男の子の人数そのものです。ちがいを聞かれています。\n・「6」…きらいな女の子の人数そのものです。ちがいを聞かれています。\n・「2」…数のちがいを求めるときの計算まちがいです。6－5＝1です。",
  "math_g4_hand_table_007":"１組の人数は22人で、読んだ人が14人です。読まなかった人は、22－14＝8人です。\n\nほかの 選択肢\n・「14」…１組で本を読んだ人の数です。読まなかった人の数ではありません。\n・「22」…１組の全員の数です。読んだ人も入っています。\n・「6」…計算まちがいです。22－14＝8です。",
  "math_g4_hand_table_008":"１組で読まなかった人は22－14＝8人、２組は9人です。8＋9＝17人です。\n\nほかの 選択肢\n・「8」…１組だけの数です。２組の9人が入っていません。\n・「9」…２組だけの数です。１組の8人が入っていません。\n・「25」…計算まちがいです。8＋9＝17です。",
  "math_g4_hand_table_009":"２つの組の人数は、１組が22人、２組が20人です。22＋20＝42で、全部で42人です。\n\nほかの 選択肢\n・「25」…ちがう数の足し算で出る数です。２つの組の人数の合計は、22＋20です。\n・「17」…本を読まなかった人の、２つの組の合計です。全員の人数ではありません。\n・「40」…20＋20のように、1組を20人として足した数です。1組は22人です。",
  "math_g4_hand_table_010":"サッカーとバスケットボールの両方に入っている3人は、10人にも7人にも数えられています。10＋7－3＝14で、どちらかに入っているのは14人です。\n\nほかの 選択肢\n・「17」…10＋7の答えです。両方の3人を二重に数えています。\n・「13」…14より１人少ない数です。両方の3人をひくのは1回だけで、10＋7－3＝14です。\n・「20」…10＋7＋3のように、3人をもう一度足した数です。",
  "math_g4_hand_table_011":"どちらかに入っているのは、10＋7－3＝14人です。クラス全体の19人から14人をひいて、19－14＝5で、どちらにも入っていない人は5人です。\n\nほかの 選択肢\n・「2」…19－(10＋7)の答えで、両方の3人を二重に数えた数です。\n・「9」…19－10の答えです。バスケットボールに入っている人を考えていません。\n・「12」…19－7の答えです。サッカーに入っている人を考えていません。",
  "math_g4_hand_table_012":"男の子が12人、女の子が9人なので、12＋9＝21です。合計のらんの21は、男の子と女の子の人数を合わせたときの数です。\n\nほかの 選択肢\n・「男の子の人数だけのとき」…男の子だけなら12人です。\n・「女の子の人数だけのとき」…女の子だけなら9人です。\n・「男の子の人数から女の子の人数を引いたとき」…12－9＝3で、ちがいの人数です。",
  "math_g4_hand_table_013":"犬を18人、ねこを15人と数えると、両方の6人が二重になります。18＋15－6＝27人がどちらかをかっています。40－27＝13で、どちらもかっていない人は13人です。\n\nほかの 選択肢\n・「7」…40－18－15の答えで、二重の6人をひいていません。\n・「10」…27人をひかずに出した数で、40－27＝13と合いません。\n・「19」…13＋6の答えです。どちらもかっていない人に、両方の6人が入っています。",
  "math_g4_hand_table_014":"男の人数20人から、ほかの通学方法の8人と5人をひくと、20－8－5＝7で、男で歩いて来る人は7人です。\n\nほかの 選択肢\n・「8」…男で歩き以外の通学方法の人数のひとつです。歩いて来る人ではありません。\n・「5」…男で歩き以外の通学方法の人数のひとつです。歩いて来る人ではありません。\n・「12」…ひく数を使いまちがえた数です。20－8－5＝7です。",
  "math_g4_hand_table_015":"女の人数18人から、ほかの通学方法の6人と7人をひくと、18－6－7＝5で、女でバスで来る人は5人です。\n\nほかの 選択肢\n・「8」…表のべつのますの数で、女でバスで来る人ではありません。\n・「6」…女でバス以外の通学方法の人数のひとつです。\n・「7」…女で歩いて来る人など、バス以外の人数です。",
  "math_g4_hand_table_016":"男の歩きは20－8－5＝7人、女の歩きは7人です。7＋7＝14で、歩いて来る人は男女合わせて14人です。\n\nほかの 選択肢\n・「7」…男だけ（または女だけ）の歩いて来る人数です。\n・「12」…計算まちがいの数です。7＋7＝14です。\n・「20」…男の人数の全部です。歩いて来る人の数ではありません。",
  "math_g4_hand_table_017":"算数が好きな20人と国語が好きな17人を足すと、両方好きな9人が二重になります。20＋17－9＝28人がどちらかが好きです。32－28＝4で、どちらも好きでない人は4人です。\n\nほかの 選択肢\n・「3」…32－(20＋9)の答えです。９人は二重に数えた分なので、ひくのは28人です。\n・「6」…32－(17＋9)の答えです。９人は二重に数えた分なので、ひくのは28人です。\n・「9」…両方が好きな人数です。どちらも好きでない人ではありません。",
  "math_g4_hand_table_018":"20＋18＝38で、35人より3人多いです。この3人は両方に○をつけたので二重に数えられた人です。\n\nほかの 選択肢\n・「2」…35と38のちがいは3人なので、2人ではありません。\n・「4」…数えまちがいの数です。38－35＝3です。\n・「5」…数えまちがいの数です。38－35＝3です。",
  "math_g4_largenum_001":"チケット1まいが 1000{円|えん}で、250まい{売|う}れたので、{全部|ぜんぶ}の{売|う}り{上|あ}げは 1000×250 です。1000 をかけるときは、250 の{後|うし}ろに 0 を3つ{付|つ}けて、250000{円|えん}です。0 の{数|かず}をまちがえて、25000 や 2500000 としないように{気|き}をつけましょう。",
  "math_g4_rounding_001":"百の位までのがい数にするので、すぐ下の十の位の数字を見ます。4827の十の位は２で、４以下なので切り捨てます。百の位から下を0にして、4800人です。十の位が５以上だと切り上げになるので、まちがえないようにしましょう。",
  "math_g5_area_001":"三角形の面積は、底辺×高さ÷２です。8×5÷2＝20なので、旗の面積は20cm²です。\n\nほかの 選択肢\n・「40cm²」…8×5の答えで、÷２をわすれた数です。この数は、平行四辺形の面積です。\n・「13cm²」…8＋5の答えです。面積はたし算ではなく、かけ算で求めます。\n・「26cm²」…(8＋5)×2の答えで、まわりの長さの計算です。面積ではありません。",
  "math_g5_average_001":"平均は、合計を日数でわって求めます。合計は12＋15＋9＝36匹。36÷3＝12なので、１日あたりの平均は12匹です。\n\nほかの 選択肢\n・「11匹」…数えまちがいの数です。36÷3＝12で、11匹にはなりません。\n・「13匹」…数えまちがいの数です。36÷3＝12で、13匹にはなりません。\n・「36匹」…3日間の合計です。3でわって1日分にします。",
  "math_g5_average_002":"４回の合計は80×4＝320点です。５回で平均82点にするには、合計が82×5＝410点必要です。410－320＝90で、５回目は90点です。4回分が80点より足りない分は、82点と80点の差2点を4回で8点になるので、82点にその8点を足した90点とも考えられます。",
  "math_g5_fraction_001":"ちがう分母の分数をたすときは、通分してからたします。1/2＝3/6、1/3＝2/6なので、3/6＋2/6＝5/6です。\n\nほかの 選択肢\n・「2/5」…分母どうし、分子どうしをたした分数です。通分してから分子だけをたします。\n・「1/6」…1/2－1/3の差の1/6です。この問題は合わせた量なので、たし算をします。\n・「2/6」…2/6は1/3と同じ大きさです。弟の分だけを答えています。",
  "math_g5_hand_angle_001":"三角形の３つの角の大きさの和は、いつも180°です。どんな三角形でも変わりません。\n\nほかの 選択肢\n・「90」…直角の大きさです。三角形の角の和ではありません。\n・「270」…三角形の角の和としては大きすぎます。180°です。\n・「360」…四角形の角の和です。三角形は180°です。",
  "math_g5_hand_angle_002":"四角形は、対角線で２つの三角形に分けられます。三角形の角の和は180°なので、180°×2＝360°です。\n\nほかの 選択肢\n・「180」…三角形の角の和です。四角形は三角形２つ分なので360°です。\n・「270」…どの図形の角の和でもない数です。180の倍数になります。\n・「720」…六角形の角の和です。四角形は360°です。",
  "math_g5_hand_angle_003":"三角形の角の和は180°です。50＋60＝110、180－110＝70で、のこりの角は70°です。\n\nほかの 選択肢\n・「110」…50＋60の答えです。180°からひいていません。\n・「130」…180－50の答えです。60°もひく必要があります。\n・「120」…180－60の答えです。50°もひく必要があります。",
  "math_g5_hand_angle_004":"三角形の角の和は180°です。90＋35＝125、180－125＝55で、のこりの角は55°です。\n\nほかの 選択肢\n・「45」…90＋35＋45＝170で、180°になりません。\n・「125」…90＋35の答えです。180°からひいていません。\n・「65」…90＋35＋65＝190で、180°をこえるのでちがいます。",
  "math_g5_hand_angle_005":"正三角形は、３つの角が同じ大きさです。180÷3＝60で、１つの角は60°です。\n\nほかの 選択肢\n・「30」…60°の半分です。30×3＝90で、180°になりません。\n・「45」…45×3＝135で、180°になりません。\n・「90」…90×3＝270で、180°をこえます。",
  "math_g5_hand_angle_006":"四角形の角の和は360°です。90＋80＋100＝270、360－270＝90で、のこりの角は90°です。\n\nほかの 選択肢\n・「70」…90＋80＋100＋70＝340で、360°になりません。\n・「80」…90＋80＋100＋80＝350で、360°になりません。\n・「100」…90＋80＋100＋100＝370で、360°をこえます。",
  "math_g5_hand_angle_007":"五角形は、１つの頂点から対角線をひくと、３つの三角形に分けられます。180°×3＝540°です。\n\nほかの 選択肢\n・「360」…四角形の角の和です。五角形は三角形が３つ分です。\n・「450」…180の倍数ではなく、三角形に分けても出ない数です。\n・「720」…六角形の角の和です。五角形は540°です。",
  "math_g5_hand_angle_008":"三角形の角の和は180°です。45＋45＝90、180－90＝90で、のこりの角は90°です。直角二等辺三角形の形です。\n\nほかの 選択肢\n・「45」…45＋45＋45＝135で、180°になりません。\n・「60」…45＋45＋60＝150で、180°になりません。\n・「180」…三角形の角の和です。のこりの1つの角の大きさではありません。",
  "math_g5_hand_angle_009":"三角形の角の和は180°です。70＋40＝110、180－110＝70で、のこりの角は70°です。\n\nほかの 選択肢\n・「110」…70＋40の答えです。180°からひいていません。\n・「30」…70－40の答えです。角の和は、ひき算ではなく、足し算で考えます。\n・「140」…180－40の答えです。70°もひく必要があります。",
  "math_g5_hand_angle_010":"二等辺三角形の底角は同じ大きさです。頂角が80°なので、180－80＝100が底角２つ分で、100÷2＝50から、底角は50°です。\n\nほかの 選択肢\n・「100」…底角２つ分の合計です。1つぶんは、2でわって50°です。\n・「80」…頂角の大きさです。底角ではありません。\n・「40」…80°の半分です。80＋40＋40＝160で、180°になりません。",
  "math_g5_hand_angle_011":"二等辺三角形の底角は同じ大きさです。65×2＝130、180－130＝50で、頂角は50°です。\n\nほかの 選択肢\n・「65」…底角の大きさです。頂角を聞かれています。\n・「115」…180－65の答えです。底角は２つあるので、65を2回ひく必要があります。\n・「130」…底角２つ分の合計です。180°からひいていません。",
  "math_g5_hand_angle_012":"六角形は、１つの頂点から対角線をひくと、４つの三角形に分けられます。180°×4＝720°です。\n\nほかの 選択肢\n・「540」…五角形の角の和です。六角形は三角形が４つ分です。\n・「360」…四角形の角の和です。六角形は720°です。\n・「1080」…八角形の角の和です。六角形は720°です。",
  "math_g5_hand_angle_013":"正五角形は、５つの角がすべて同じ大きさです。五角形の角の和は540°なので、540÷5＝108で、１つの角は108°です。\n\nほかの 選択肢\n・「72」…360÷5の答えです。これは外側の角で、中の角ではありません。\n・「120」…正六角形の１つの角です。正五角形は108°です。\n・「90」…正方形の１つの角です。正五角形は108°です。",
  "math_g5_hand_angle_014":"四角形の角の和は360°です。75＋110＋95＝280、360－280＝80で、のこりの角は80°です。\n\nほかの 選択肢\n・「70」…75＋110＋95＋70＝350で、360°になりません。\n・「90」…75＋110＋95＋90＝370で、360°をこえます。\n・「100」…75＋110＋95＋100＝380で、360°をこえます。",
  "math_g5_hand_angle_015":"正六角形は、６つの角がすべて同じ大きさです。六角形の角の和は720°なので、720÷6＝120で、１つの角は120°です。\n\nほかの 選択肢\n・「60」…正三角形の１つの角です。正六角形は120°です。\n・「108」…正五角形の１つの角です。正六角形は120°です。\n・「135」…正八角形の１つの角です。正六角形は120°です。",
  "math_g5_hand_angle_016":"十角形は、１つの頂点から対角線をひくと、10－2＝8つの三角形に分けられます。180°×8＝1440°です。\n\nほかの 選択肢\n・「1080」…八角形の角の和です。十角形は三角形が８つ分です。\n・「1260」…九角形の角の和です。十角形は三角形が８つ分です。\n・「1800」…180×10の答えです。三角形の数は角の数ではなく、角の数－2の8つです。",
  "math_g5_hand_angle_017":"平行四辺形では、となり合う角の和が180°です。180－65＝115で、角Ｂは115°です。\n\nほかの 選択肢\n・「65」…向かい合う角Ｃと同じ大きさです。となりのＢは、ちがう大きさです。\n・「125」…65＋125＝190で、180°をこえます。\n・「105」…65＋105＝170で、180°になりません。",
  "math_g5_hand_angle_018":"八角形は、１つの頂点から対角線をひくと、６つの三角形に分けられます。180°×6＝1080°です。\n\nほかの 選択肢\n・「720」…六角形の角の和です。八角形は三角形が６つ分です。\n・「960」…180°の倍数ではないので、三角形に分けても出ない数です。\n・「1260」…九角形の角の和です。八角形は1080°です。",
  "math_g5_hand_angle_019":"直角三角形には90°の角があります。のこりの角の和は、180－90＝90です。30°をひいて、90－30＝60で、もう１つの角は60°です。\n\nほかの 選択肢\n・「30」…問題で与えられた角と同じ大きさです。90＋30＋30＝150で、180°になりません。\n・「45」…90＋30＋45＝165で、180°になりません。\n・「150」…180－30の答えです。90°もひく必要があります。",
  "math_g5_hand_angle_020":"ひし形では、となり合う角の和が180°です。180－50＝130で、となりの角は130°です。\n\nほかの 選択肢\n・「50」…向かい合う角と同じ大きさです。となりの角は、ちがいます。\n・「40」…90－50の答えです。となり合う角の和は90°ではなく、180°です。\n・「310」…360－50の答えです。四角形の角の和と混ぜた数で、となりの角ではありません。",
  "math_g5_hand_angle_021":"平行な辺ＡＤとＢＣでは、角Ａ＋角Ｂ＝180°です。180－100＝80で、角Ｂは80°です。\n\nほかの 選択肢\n・「100」…角Ａと同じ大きさです。角Ａ＋角Ｂ＝180°になりません。\n・「90」…100＋90＝190で、180°をこえます。\n・「120」…100＋120＝220で、180°をこえます。",
  "math_g5_hand_angle_022":"五角形の角の和は540°です。100＋110＋120＋90＝420、540－420＝120で、のこりの角は120°です。\n\nほかの 選択肢\n・「100」…四つの角と合わせて520°になり、540°にならないのでちがいます。\n・「110」…四つの角と合わせて530°になり、540°にならないのでちがいます。\n・「130」…四つの角と合わせて550°になり、540°をこえます。",
  "math_g5_hand_angle_023":"底角を１つ分とすると、頂角は２つ分です。底角が２つあるので、全部で４つ分になり、これが180°です。180÷4＝45で、底角は45°です。\n\nほかの 選択肢\n・「60」…頂角が120°になり、60＋60＋120＝240で、180°をこえます。\n・「90」…頂角が180°になり、三角形ができません。\n・「30」…頂角が60°になり、30＋30＋60＝120で、180°になりません。",
  "math_g5_hand_angle_024":"正方形の角は90°です。対角線は、その角をちょうど半分に分けるので、90÷2＝45で、45°です。\n\nほかの 選択肢\n・「30」…90°を3つに分けたときの角です。対角線は2つに分けます。\n・「60」…正三角形の角です。正方形の対角線は、角を等しく2つに分けるので45°です。\n・「90」…正方形の1つの角そのものです。対角線で半分に分けた角ではありません。",
  "math_g5_hand_angle_025":"正八角形は、８つの角がすべて同じ大きさです。八角形の角の和は1080°なので、1080÷8＝135で、１つの角は135°です。\n\nほかの 選択肢\n・「120」…正六角形の１つの角です。正八角形は135°です。\n・「108」…正五角形の１つの角です。正八角形は135°です。\n・「150」…正十二角形の１つの角です。正八角形は135°です。",
  "math_g5_hand_angle_026":"十二角形は、12－2＝10この三角形に分けられるので、角の和は180×10＝1800°です。正十二角形は12の角がすべて同じなので、1800÷12＝150で、１つの角は150°です。\n\nほかの 選択肢\n・「120」…正六角形の１つの角です。正十二角形はもっと大きい150°です。\n・「135」…正八角形の１つの角です。正十二角形は150°です。\n・「144」…正十角形の１つの角です。1440÷10＝144で、正十二角形ではありません。",
  "math_g5_hand_angle_027":"1980÷180＝11が、三角形の数です。多角形の辺の数は、三角形の数より2多いので、11＋2＝13で、十三角形です。辺は13本です。\n\nほかの 選択肢\n・「11」…三角形の数です。辺の数は、これに2を足した13です。\n・「12」…11＋1と考えた数です。三角形の数に足すのは2です。\n・「15」…十五角形の角の和は、180×13＝2340°で、1980°にはなりません。",
  "math_g5_hand_angle_028":"1260÷180＝7が、三角形の数です。辺の数は、三角形の数より2多いので、7＋2＝9で、九角形です。\n\nほかの 選択肢\n・「7」…三角形の数です。辺の数は、これに2を足した9です。\n・「8」…7＋1と考えた数です。三角形の数に足すのは2です。八角形の角の和は1080°です。\n・「10」…十角形の角の和は1440°です。1260°にはなりません。",
  "math_g5_hand_angle_029":"角Ａが60°なので、角Ｂ＋角Ｃ＝180－60＝120°です。角Ｂは角Ｃの２倍なので、角Ｃの３つ分が120°で、角Ｃは40°、角Ｂは80°です。\n\nほかの 選択肢\n・「40」…角Ｃの大きさです。問いは角Ｂです。\n・「60」…角Ａの大きさです。角Ｂではありません。\n・「120」…角Ｂ＋角Ｃの和です。角Ｂだけの大きさではありません。",
  "math_g5_hand_angle_030":"五角形の１つの頂点からは、対角線が２本ひけます。それで、三角形は2＋1＝3こに分かれます。\n\nほかの 選択肢\n・「2」…ひける対角線の本数です。三角形の数は、それより1つ多くなります。\n・「4」…対角線の2本に、2を足した数です。足すのは1なので、2＋1＝3こです。\n・「5」…辺の数、または頂点の数です。三角形の数ではありません。",
  "math_g5_hand_angle_031":"１つの頂点からは、自分とそのとなりの２つの頂点に対角線はひけません。六角形は6－3＝3本です。\n\nほかの 選択肢\n・「2」…五角形の１つの頂点からひける対角線の数です。六角形は3本です。\n・「4」…七角形の１つの頂点からひける対角線の数です。六角形は3本です。\n・「6」…頂点の数です。自分とそのとなりの頂点にはひけないので、ひけるのは3本です。",
  "math_g5_hand_angle_032":"七角形の１つの頂点からは、7－3＝4本の対角線がひけます。7つの頂点で7×4＝28ですが、同じ対角線を２回ずつ数えているので、28÷2＝14本です。\n\nほかの 選択肢\n・「7」…頂点の数です。対角線の数ではありません。\n・「21」…7×6÷2の答えです。辺も入れた、すべての頂点を結ぶ線の数になります。\n・「28」…2回数えた数です。2でわって14本にします。",
  "math_g5_hand_angle_033":"正五角形の１つの角は108°です。２本の対角線で、その角が3つの同じ大きさに分かれるので、108÷3＝36で、まん中の角は36°です。\n\nほかの 選択肢\n・「18」…36°の半分です。3つに分かれた角の1つは、36°です。\n・「54」…108÷2の答えです。角は2つではなく、3つに分かれています。\n・「72」…36°が2つ分です。まん中の角は、1つ分の36°です。",
  "math_g5_hand_angle_034":"1つの角をアとすると、ほかの2つの角の和もアです。アと、ほかの2つの角の和を足すと180°なので、アが2つ分で180°になり、アは90°です。\n\nほかの 選択肢\n・「60」…正三角形の角です。ほかの2つの角の和は120°になり、60°と同じにならないのでちがいます。\n・「120」…ほかの2つの角の和が60°になり、120°と同じにならないのでちがいます。\n・「180」…三角形の3つの角の和です。1つの角が180°だと、三角形になりません。",
  "math_g5_hand_angle_035":"平行四辺形では、となり合う角の和が180°です。角Ｂは180－70＝110°。向かい合う角Ｄも110°です。110＋110＝220で、和は220°です。\n\nほかの 選択肢\n・「110」…角Ｂ（または角Ｄ）の1つ分です。問いは、2つの和です。\n・「140」…角Ａ＋角Ｃ（70＋70）の答えです。問いは角Ｂと角Ｄの和です。\n・「180」…となり合う角の和です。角Ｂと角Ｄは向かい合う角で、2つ合わせると220°になります。",
  "math_g5_hand_angle_036":"星の形の5つのとがった先の角の和は、いつも180°です。正五角形の星では、1つが36°で、36×5＝180°とたしかめられます。\n\nほかの 選択肢\n・「360」…四角形の角の和です。星の先の角の和ではありません。\n・「540」…五角形の角の和です。星の先の角は、それとはちがい、180°です。\n・「90」…直角の大きさです。5つの先の角の和は、もっと大きい180°です。",
  "math_g5_hand_area_001":"平行四辺形の面積は、底辺×高さです。6×4＝24で、面積は24cm²です。\n\nほかの 選択肢\n・「10」…6＋4の答えです。面積はたし算ではなく、かけ算で求めます。\n・「12」…6×4÷2の答えで、三角形の面積です。平行四辺形は÷2しません。\n・「48」…6×4×2の答えです。かけすぎです。底辺×高さの24です。",
  "math_g5_hand_area_002":"三角形の面積は、底辺×高さ÷２です。10×6÷2＝30で、面積は30cm²です。\n\nほかの 選択肢\n・「60」…10×6の答えで、÷２をわすれた数です。この数は平行四辺形の面積です。\n・「16」…10＋6の答えです。面積はたし算ではなく、かけ算で求めます。\n・「36」…6×6のように、辺の長さをまちがえてかけた数です。底辺は10cmです。",
  "math_g5_hand_area_003":"台形の面積は、(上底＋下底)×高さ÷２です。(3＋7)×4÷2＝20で、面積は20cm²です。\n\nほかの 選択肢\n・「40」…(3＋7)×4の答えで、÷２をわすれた数です。\n・「28」…7×4の答えで、下底だけを使った数です。上底の3cmも使います。\n・「12」…3×4の答えで、上底だけを使った数です。下底の7cmも使います。",
  "math_g5_hand_area_004":"ひし形の面積は、対角線×対角線÷２です。8×6÷2＝24で、面積は24cm²です。\n\nほかの 選択肢\n・「48」…8×6の答えで、÷２をわすれた数です。この数は、まわりの長方形の面積です。\n・「14」…8＋6の答えです。面積はたし算ではなく、かけ算で求めます。\n・「28」…(8＋6)×2の答えで、まわりの長さの計算のような数です。ひし形の面積ではありません。",
  "math_g5_hand_area_005":"三角形２つで平行四辺形ができます。平行四辺形の面積は底辺×高さなので、その半分で、三角形の面積は底辺×高さ÷２です。\n\nほかの 選択肢\n・「底辺×高さ」…平行四辺形の面積の式です。三角形は÷２が必要です。\n・「（底辺＋高さ）÷２」…２つの長さの平均を出す式で、面積の式ではありません。\n・「底辺＋高さ×２」…長さをたすだけの式で、面積を求める式ではありません。",
  "math_g5_hand_area_006":"平行四辺形は、長方形に直せるので、面積は底辺×高さです。ななめの辺の長さは使いません。\n\nほかの 選択肢\n・「底辺×ななめの辺」…ななめの辺は、高さより長いので、面積がもとより大きくなってしまいます。高さを使います。\n・「底辺×高さ÷２」…三角形の面積の式です。\n・「（底辺＋高さ）×２」…長方形のまわりの長さの式です。",
  "math_g5_hand_area_007":"平行四辺形の面積は、底辺×高さです。9×5＝45で、面積は45cm²です。\n\nほかの 選択肢\n・「90」…9×5×2の答えで、かけすぎです。底辺×高さの45です。\n・「54」…9×6の答えのように、高さの5cmをまちがえてかけた数です。\n・「14」…9＋5の答えです。面積はたし算ではなく、かけ算で求めます。",
  "math_g5_hand_area_008":"三角形の面積は、底辺×高さ÷２です。12×7÷2＝42で、面積は42cm²です。\n\nほかの 選択肢\n・「84」…12×7の答えで、÷２をわすれた数です。\n・「19」…12＋7の答えです。面積はたし算ではなく、かけ算で求めます。\n・「24」…12×4のような、まちがった数のかけ算です。高さは7cmです。",
  "math_g5_hand_area_009":"台形の面積は、(上底＋下底)×高さ÷２です。(4＋8)×5÷2＝30で、面積は30cm²です。\n\nほかの 選択肢\n・「60」…(4＋8)×5の答えで、÷２をわすれた数です。\n・「40」…8×5の答えで、下底だけを使った数です。上底の4cmも使います。\n・「17」…4＋8＋5の答えです。面積はたし算ではなく、かけ算も使って求めます。",
  "math_g5_hand_area_010":"三角形の面積×２＝底辺×高さです。24×2＝48で、48÷8＝6。高さは6cmです。\n\nほかの 選択肢\n・「3」…24÷8の答えで、×２をわすれた数です。三角形は÷２しているので、もとにもどすには２倍します。\n・「12」…24÷2の答えです。底辺の8cmでわる必要があります。\n・「4」…24÷6のような、底辺の8cmを使っていない計算です。24×2÷8＝6です。",
  "math_g5_hand_area_011":"平行四辺形の面積は底辺×高さなので、高さは面積÷底辺です。48÷12＝4で、高さは4cmです。\n\nほかの 選択肢\n・「2」…48÷12÷2の答えです。三角形のときのように÷２をしていますが、平行四辺形では不要です。\n・「6」…48÷8の答えのような、わる数をまちがえた数です。底辺の12cmでわります。\n・「8」…48÷6の答えのような、わる数をまちがえた数です。底辺の12cmでわります。",
  "math_g5_hand_area_012":"ひし形の面積は、対角線×対角線÷２です。10×12÷2＝60で、面積は60cm²です。\n\nほかの 選択肢\n・「120」…10×12の答えで、÷２をわすれた数です。\n・「22」…10＋12の答えです。面積はたし算ではなく、かけ算で求めます。\n・「30」…10×12÷4のように、わりすぎた数です。÷２です。",
  "math_g5_hand_area_013":"アは6×4÷2＝12cm²、イは12×2÷2＝12cm²で、どちらも12cm²です。底辺と高さはちがっても、かけた数が同じなら面積は同じです。答えは、アとイの面積は同じです。\n\nほかの 選択肢\n・「アのほうが大きい」…アもイも12cm²なので、アのほうが大きいわけではありません。\n・「イのほうが大きい」…底辺はイのほうが長いですが、高さが低いので、面積は同じです。\n・「この条件だけではわからない」…底辺と高さがわかっているので、計算で求められます。",
  "math_g5_hand_area_014":"平行四辺形の面積は、底辺×高さです。8×4＝32で、面積は32cm²です。ななめの辺の5cmは使いません。\n\nほかの 選択肢\n・「40」…8×5の答えで、ななめの辺を高さとして使った数です。高さは4cmです。\n・「20」…5×4の答えで、ななめの辺と高さをかけた数です。底辺は8cmです。\n・「16」…8×4÷2の答えで、三角形の面積の計算です。平行四辺形は÷２しません。",
  "math_g5_hand_area_015":"台形の面積×２＝(上底＋下底)×高さです。36×2＝72、5＋7＝12、72÷12＝6。高さは6cmです。\n\nほかの 選択肢\n・「3」…36÷12の答えで、×２をわすれた数です。\n・「12」…5＋7の答えです。上底と下底の和で、高さではありません。\n・「5」…上底と同じ数です。(5＋7)×5÷2＝30で、36cm²にならないのでちがいます。",
  "math_g5_hand_area_016":"三角形の面積は、底辺×高さ÷２です。30×20÷2＝300で、面積は300cm²です。\n\nほかの 選択肢\n・「600」…30×20の答えで、÷２をわすれた数です。\n・「150」…30×20÷4の答えのように、わりすぎた数です。÷２です。\n・「500」…30×20÷2＝300なので、500にはなりません。",
  "math_g5_hand_area_017":"台形の面積は、(上底＋下底)×高さ÷２です。(10＋14)×8÷2＝96で、面積は96m²です。\n\nほかの 選択肢\n・「192」…(10＋14)×8の答えで、÷２をわすれた数です。\n・「112」…14×8の答えで、下底だけを使った数です。上底の10mも使います。\n・「80」…10×8の答えで、上底だけを使った数です。下底の14mも使います。",
  "math_g5_hand_area_018":"ひし形の面積×２＝対角線×対角線です。48×2＝96、96÷12＝8で、もう一方の対角線は8cmです。\n\nほかの 選択肢\n・「4」…48÷12の答えで、×２をわすれた数です。ひし形は÷２しているので、もどすために２倍します。\n・「6」…12÷2の答えのような数で、面積を使っていません。\n・「16」…48÷3のような計算のまちがいです。8×12÷2＝48と合うのは、8cmです。",
  "math_g5_hand_area_019":"平行四辺形の面積は底辺×高さなので、底辺が２倍になれば、面積も２倍になります。答えは「２倍になる」です。高さはそのままです。\n\nほかの 選択肢\n・「変わらない」…底辺がのびるので、面積は変わります。底辺×高さの答えが２倍になります。\n・「半分になる」…底辺が長くなるので、面積は小さくなりません。\n・「４倍になる」…底辺と高さの両方を2倍にしたときの答えです。高さはそのままなので、2倍です。",
  "math_g5_hand_area_020":"三角形の面積は底辺×高さ÷２です。底辺が２倍、高さが半分（１/２）なら、２×１/２＝１で、かけた数は変わりません。面積は変わらないのです。\n\nほかの 選択肢\n・「２倍になる」…底辺は２倍ですが、高さが半分になるので、打ち消しあいます。\n・「半分になる」…高さが半分になっていますが、底辺が２倍になるので、全体は半分になりません。\n・「４倍になる」…底辺を２倍にしたうえに、さらに高さも２倍にしたときの数です。高さは半分です。",
  "math_g5_hand_area_021":"上底の三角形は3×6÷2＝9cm²、下底の三角形は9×6÷2＝27cm²です。9＋27＝36cm²で、台形の面積(3＋9)×6÷2＝36cm²と同じです。\n\nほかの 選択肢\n・「18」…台形の面積36cm²の半分です。2つの三角形を合わせると、台形全部になります。\n・「72」…(3＋9)×6の答えで、÷２をわすれた数です。\n・「54」…9×6の答えのような数で、三角形の÷２をしていません。",
  "math_g5_hand_area_022":"もとの面積は7×6＝42cm²です。同じ面積で底辺が14cmなので、高さは42÷14＝3cmです。底辺が２倍なら、高さは半分になります。\n\nほかの 選択肢\n・「6」…もとの高さです。底辺が２倍になると、面積が2倍になってしまいます。\n・「2」…42÷14＝3なので、2にはなりません。高さが2cmだと面積は28cm²です。\n・「4」…42÷14＝3なので、4にはなりません。高さが4cmだと面積は56cm²です。",
  "math_g5_hand_area_023":"三角形の面積は、底辺×高さ÷２です。16×9÷2＝72で、面積は72cm²です。\n\nほかの 選択肢\n・「144」…16×9の答えで、÷２をわすれた数です。\n・「25」…16＋9の答えです。面積はたし算ではなく、かけ算で求めます。\n・「48」…16×6÷2のような、高さをまちがえた計算です。高さは9cmです。",
  "math_g5_hand_area_024":"長方形の面積は8×12＝96cm²です。対角線で分けると、同じ形の三角形が２つできるので、96÷2＝48cm²です。\n\nほかの 選択肢\n・「96」…長方形全体の面積です。三角形は、その半分です。\n・「20」…8＋12の答えです。面積はたし算ではなく、かけ算で求めます。\n・「40」…8×12の計算のミスで出る数です。正しくは96÷2＝48です。",
  "math_g5_hand_area_025":"台形の面積×２＝(上底＋下底)×高さです。64×2＝128、6＋10＝16、128÷16＝8。高さは8cmです。\n\nほかの 選択肢\n・「4」…64÷16の答えで、×２をわすれた数です。\n・「16」…6＋10の答えです。上底と下底の和で、高さではありません。\n・「6」…上底と同じ数です。(6＋10)×6÷2＝48で、64cm²にならないのでちがいます。",
  "math_g5_hand_area_026":"正方形の面積は10×10＝100cm²です。四すみの三角形は、底辺5cm、高さ5cmで、5×5÷2＝12.5cm²。4つで50cm²なので、100－50＝50cm²です。\n\nほかの 選択肢\n・「25」…5×5の答えで、小さい正方形の面積です。四角形の面積ではありません。\n・「75」…100－25の答えです。四すみの三角形は4つ合わせて50cm²なので、25cm²ではありません。\n・「100」…もとの正方形の面積です。四すみをのぞいた四角形は、それより小さくなります。",
  "math_g5_hand_area_027":"平行四辺形は、対角線で、合同な（同じ形・同じ大きさの）三角形２つに分かれます。60÷2＝30で、１つの面積は30cm²です。\n\nほかの 選択肢\n・「60」…平行四辺形全体の面積です。三角形はその半分です。\n・「15」…三角形の半分、つまり4つに分けたときの数です。2つに分けるので30です。\n・「20」…60を3つに分けた数です。2つに分けるので30です。",
  "math_g5_hand_area_028":"横の辺の両はしと向かい側の辺の上の１点を結んだ三角形は、底辺が10cm、高さが6cmです。10×6÷2＝30で、面積は30cm²です。長方形の半分です。\n\nほかの 選択肢\n・「60」…10×6の答えで、長方形の面積です。三角形は÷２です。\n・「16」…10＋6の答えです。面積はたし算ではなく、かけ算で求めます。\n・「45」…10×6÷2より大きい数です。三角形は長方形の半分の30cm²です。",
  "math_g5_hand_area_029":"台形の面積×２÷高さ＝上底＋下底です。42×2÷6＝14で、上底＋9＝14なので、14－9＝5。上底は5cmです。\n\nほかの 選択肢\n・「3」…42÷6÷2のような、まちがいの数です。(3＋9)×6÷2＝36で、42cm²にならないのでちがいます。\n・「7」…(7＋9)×6÷2＝48で、42cm²にならないのでちがいます。\n・「9」…下底と同じ数です。(9＋9)×6÷2＝54で、42cm²にならないのでちがいます。",
  "math_g5_hand_area_030":"ひし形の面積は、対角線×対角線÷２です。6×8÷2＝24で、面積は24cm²です。辺の5cmは使いません。\n\nほかの 選択肢\n・「40」…5×8の答えで、辺と対角線をかけた数です。面積には対角線の2つを使います。\n・「30」…5×6の答えで、辺と対角線をかけた数です。面積には対角線の2つを使います。\n・「20」…5×4のような、辺の長さを使った計算です。面積には対角線を使います。",
  "math_g5_hand_area_031":"三角形の面積×２＝底辺×高さです。36×2＝72、72÷9＝8で、高さは8cmです。\n\nほかの 選択肢\n・「4」…36÷9の答えで、×２をわすれた数です。\n・「6」…36÷6のような、わる数をまちがえた計算です。底辺の9cmでわります。\n・「18」…36÷2の答えです。底辺の9cmでわる必要があります。",
  "math_g5_hand_area_032":"長方形の面積は8×12＝96cm²、三角形は12×8÷2＝48cm²です。のこった部分は、96－48＝48cm²です。\n\nほかの 選択肢\n・「96」…長方形全体の面積です。三角形の分をひく必要があります。\n・「24」…三角形の面積の半分です。三角形は48cm²なので、のこりも48cm²です。\n・「72」…三角形を切り取った数をまちがえた数です。三角形は長方形の半分です。",
  "math_g5_hand_area_033":"平行四辺形の面積は6×5＝30cm²です。三角形の面積が30cm²で、底辺が12cmなので、12×□÷2＝30。□＝30×2÷12＝5で、高さは5cmです。\n\nほかの 選択肢\n・「2.5」…30÷12の答えで、×２をわすれた数です。三角形は÷２しているので、もとにもどすには２倍します。\n・「10」…30×2÷6のような、わる数をまちがえた計算です。底辺の12cmでわります。\n・「6」…平行四辺形の底辺と同じ数です。12×6÷2＝36で、30cm²にならないのでちがいます。",
  "math_g5_hand_area_034":"台形の面積は(4＋10)×6÷2＝42cm²です。底辺が7cmの平行四辺形の面積が42cm²なので、高さは42÷7＝6cmです。\n\nほかの 選択肢\n・「3」…42÷14の答えで、底辺を台形の上底と下底の和でわった数です。平行四辺形の底辺は7cmです。\n・「12」…42÷3.5のような計算まちがいの数です。7でわります。\n・「7」…平行四辺形の底辺と同じ数です。7×7＝49で、42cm²にならないのでちがいます。",
  "math_g5_hand_area_035":"台形の面積は(20＋30)×16÷2＝400m²です。１m²あたり３本のまきを使うので、400×3＝1200で、1200本必要です。\n\nほかの 選択肢\n・「400」…雪原の面積です。１m²あたり３本のまきをかける必要があります。\n・「800」…400×2の答えのような数です。1m²あたりは3本です。\n・「2400」…(20＋30)×16×3の答えで、÷２をわすれた数です。",
  "math_g5_hand_average_001":"平均は、合計を個数でわって求めます。(4＋6＋8)÷3＝18÷3＝6です。\n\nほかの 選択肢\n・「18」…４、６、８の合計です。個数の3でわります。\n・「4」…３つの数のうちの、いちばん小さい数です。平均は、真ん中あたりの数になります。\n・「8」…３つの数のうちの、いちばん大きい数です。平均は、真ん中あたりの数になります。",
  "math_g5_hand_average_002":"(5＋7＋9＋11)÷4＝32÷4＝8です。合計の32を、個数の4でわります。\n\nほかの 選択肢\n・「32」…５、７、９、11の合計です。個数の4でわります。\n・「7」…2番目の数です。平均は、4つの数の合計を4でわった数です。\n・「9」…3番目の数です。平均は、4つの数の合計を4でわった数です。",
  "math_g5_hand_average_003":"(70＋80＋90)÷3＝240÷3＝80です。平均は80点です。\n\nほかの 選択肢\n・「240」…３回の点数の合計です。回数の3でわります。\n・「70」…３回のうちの、いちばん低い点数です。平均は、3回の合計を3でわります。\n・「90」…３回のうちの、いちばん高い点数です。平均は、3回の合計を3でわります。",
  "math_g5_hand_average_004":"平均は、合計÷個数で求めます。「ならす」と考えて、全部を同じ数にしたときの１つ分の数です。\n\nほかの 選択肢\n・「合計×個数」…かけ算では、とても大きな数になります。平均は、わり算で求めます。\n・「個数÷合計」…わる数とわられる数がぎゃくです。合計を個数でわります。\n・「合計－個数」…ひき算では、平均になりません。",
  "math_g5_hand_average_005":"合計＝平均×個数です。10×4＝40で、合計は40です。\n\nほかの 選択肢\n・「14」…10＋4の答えです。合計は、たし算ではなく、かけ算で求めます。\n・「30」…10×3のような、個数をまちがえた数です。個数は4です。\n・「50」…10×5のような、個数をまちがえた数です。個数は4です。",
  "math_g5_hand_average_006":"合計は12＋15＋9＋14＋10＝60本です。60÷5＝12で、平均は12本です。\n\nほかの 選択肢\n・「60」…５日間の合計です。日数の5でわります。\n・「10」…５日のうちでいちばん少ない日の本数です。平均ではありません。\n・「15」…５日のうちでいちばん多い日の本数です。平均ではありません。",
  "math_g5_hand_average_007":"合計＝平均×回数です。8×6＝48で、合計は48点です。\n\nほかの 選択肢\n・「14」…8＋6の答えです。合計は、たし算ではなく、かけ算で求めます。\n・「42」…7×6の答えで、平均を7点と考えてしまった数です。平均は8点です。\n・「54」…9×6の答えで、平均を9点と考えてしまった数です。平均は8点です。",
  "math_g5_hand_average_008":"５回の平均が80点になるには、合計が80×5＝400点必要です。４回の合計は75×4＝300点なので、５回目は400－300＝100点です。\n\nほかの 選択肢\n・「80」…めざす平均の点数です。５回目が80点だと、合計380点で平均は76点になり、80点になりません。\n・「95」…５回目が95点だと、合計395点で平均は79点になり、80点に足りません。\n・「75」…いままでの平均の点数です。５回目が75点だと、平均は75点のままです。",
  "math_g5_hand_average_009":"４人の合計は42×4＝168kg、３人の合計は40×3＝120kgです。168－120＝48で、４人目は48kgです。\n\nほかの 選択肢\n・「42」…４人の平均の体重です。４人目の体重とはかぎりません。\n・「44」…4人の合計が164kgになり、168kgに足りません。\n・「40」…３人の平均の体重です。４人目が40kgだと、平均は40kgのままです。",
  "math_g5_hand_average_010":"合計＝平均×日数です。6000×5＝30000で、合計は30000歩です。\n\nほかの 選択肢\n・「6005」…6000＋5の答えです。合計は、たし算ではなく、かけ算で求めます。\n・「24000」…6000×4の答えです。日数は5日です。\n・「3000」…6000÷2のような答えです。日数の5をかけます。",
  "math_g5_hand_average_011":"(1＋2＋3＋4＋5＋6)÷6＝21÷6＝3.5です。平均は、必ずしも整数になるとはかぎりません。\n\nほかの 選択肢\n・「21」…目の数の合計です。個数の6でわります。\n・「3」…真ん中の数のひとつですが、平均は21÷6＝3.5です。\n・「4」…真ん中の数のひとつですが、平均は21÷6＝3.5です。",
  "math_g5_hand_average_012":"水をならすとは、合計を入れ物の数でわることです。(3＋5＋4)÷3＝12÷3＝4で、４Lになります。\n\nほかの 選択肢\n・「12」…水の合計です。入れ物の数の3でわります。\n・「3」…3つのうちの、いちばん少ない量です。ならした量ではありません。\n・「5」…3つのうちの、いちばん多い量です。ならした量ではありません。",
  "math_g5_hand_average_013":"合計＝１こ平均×こ数です。60×8＝480で、全部で480gです。\n\nほかの 選択肢\n・「240」…60×4の答えです。こ数は8こです。\n・「420」…60×7の答えです。こ数は8こです。\n・「540」…60×9の答えです。こ数は8こです。",
  "math_g5_hand_average_014":"合計＝平均×個数です。7.5×6＝45で、合計は45です。\n\nほかの 選択肢\n・「37.5」…7.5×5の答えです。個数は6こです。\n・「52.5」…7.5×7の答えです。個数は6こです。\n・「13.5」…7.5＋6の答えです。合計は、たし算ではなく、かけ算で求めます。",
  "math_g5_hand_average_015":"５回の合計は82×5＝410点です。４回目までの合計は80＋85＋78＋83＝326点なので、５回目は410－326＝84点です。\n\nほかの 選択肢\n・「82」…５回の平均の点数です。５回目が82点だと、合計が408点になり、平均は81.6点になります。\n・「80」…５回目が80点だと、合計が406点になり、平均は82点になりません。\n・「86」…５回目が86点だと、合計が412点になり、平均が82点をこえます。",
  "math_g5_hand_average_016":"男子の合計は150×10＝1500cm、女子の合計は144×20＝2880cmです。全員の平均は、(1500＋2880)÷30＝146cmです。\n\nほかの 選択肢\n・「147」…150と144を足して2でわった数です。人数がちがうので、人数の多い女子の平均に近くなります。\n・「148」…人数のちがいを考えると、144に近い146になり、148にはなりません。\n・「144」…女子の平均だけです。男子の平均150cmの分が入っていません。",
  "math_g5_hand_average_017":"合計は12×3＝36です。10と14の和は24なので、のこりは36－24＝12です。\n\nほかの 選択肢\n・「10」…10＋14＋10＝34で、36にならないのでちがいます。\n・「14」…10＋14＋14＝38で、36にならないのでちがいます。\n・「36」…３つの数の合計です。のこりの１つの数は、そこから24をひいた数です。",
  "math_g5_hand_average_018":"とれなかった日の０ひきも、日数に数えます。12＋0＋8＋10＋0＝30ひきを、5日でわって、30÷5＝6ひきです。\n\nほかの 選択肢\n・「7.5」…30÷4の答えで、とれなかった日を１日だけ数えなかった数です。０の日も日数に入れます。\n・「10」…30÷3の答えで、とれなかった２日を数えなかった数です。０の日も日数に入れます。\n・「30」…５日間の合計です。日数の5でわります。",
  "math_g5_hand_average_019":"全部のページ数＝1日の平均×日数です。4.5×30＝135で、135ページです。\n\nほかの 選択肢\n・「13.5」…4.5×3の答えです。小数点の位置がずれています。30日なので135です。\n・「120」…4×30の答えで、4.5を4として計算した数です。\n・「150」…5×30の答えで、4.5を5として計算した数です。",
  "math_g5_hand_average_020":"５人の合計は7×5＝35点、４人の合計は8×4＝32点です。加わった人は、35－32＝3点です。\n\nほかの 選択肢\n・「7」…５人の平均の点数です。加わった人の点数とはかぎりません。\n・「8」…もとの４人の平均の点数です。加わった人が8点だと、平均は8点のままです。\n・「5」…５人の合計が37点になり、35点にならないのでちがいます。",
  "math_g5_hand_circle_001":"円のまわりの長さを「円周」といいます。円のふちを１しゅうする長さです。\n\nほかの 選択肢\n・「直径」…円の中心を通って、円のはしからはしまでひいた線の長さです。\n・「半径」…円の中心から、円のふちまでの長さです。\n・「円周率」…円周が直径の何倍かを表す数（約3.14）です。",
  "math_g5_hand_circle_002":"円周÷直径は、どんな大きさの円でも同じ数になります。この数を「円周率」といい、約3.14です。\n\nほかの 選択肢\n・「半径」…円の中心から、円のふちまでの長さです。\n・「円周」…円のまわりの長さのことです。\n・「直径」…円の中心を通る線の長さです。",
  "math_g5_hand_circle_003":"円周率は、わり切れずにずっと続く数で、約3.14です。ふつうは3.14を使って計算します。\n\nほかの 選択肢\n・「3」…約3として、おおまかに考えることもありますが、ふつうは3.14を使います。\n・「3.41」…3.14の数字をいれかえた、まちがいの数です。\n・「4.13」…3.14の数字をいれかえた、まちがいの数です。",
  "math_g5_hand_circle_004":"円周＝直径×円周率です。10×3.14＝31.4で、円周は31.4cmです。\n\nほかの 選択肢\n・「13.14」…10＋3.14の答えです。円周は、たし算ではなく、かけ算で求めます。\n・「314」…10×3.14の小数点の位置をずらした数です。31.4です。\n・「62.8」…10×2×3.14の答えで、直径を半径と考えて２倍した数です。直径にそのまま3.14をかけます。",
  "math_g5_hand_circle_005":"辺の長さがすべて等しく、角の大きさもすべて等しい多角形を「正多角形」といいます。正三角形や正方形、正六角形などがそうです。\n\nほかの 選択肢\n・「合同な多角形」…ぴったり重なる２つの多角形のことです。\n・「対称な多角形」…線対称や点対称の多角形のことです。\n・「相似な多角形」…形が同じで、大きさがちがう多角形のことです。",
  "math_g5_hand_circle_006":"直径は半径の２倍です。5×2＝10で、直径は10cmです。\n\nほかの 選択肢\n・「2.5」…5÷2の答えで、直径を半分にした数です。直径は半径の２倍で、10cmです。\n・「5」…半径と同じ数です。直径は半径の２倍です。\n・「15」…5＋10のような数です。5×2＝10です。",
  "math_g5_hand_circle_007":"円周＝直径×円周率です。20×3.14＝62.8で、円周は62.8cmです。\n\nほかの 選択肢\n・「23.14」…20＋3.14の答えです。円周は、たし算ではなく、かけ算で求めます。\n・「31.4」…10×3.14の答えで、半径の10cmの円の円周です。直径は20cmです。\n・「125.6」…20×2×3.14の答えで、直径をさらに2倍した数です。直径にそのまま3.14をかけます。",
  "math_g5_hand_circle_008":"半径が５cmなので、直径は5×2＝10cmです。円周は10×3.14＝31.4で、31.4cmです。\n\nほかの 選択肢\n・「15.7」…5×3.14の答えで、半径にそのまま3.14をかけた数です。直径にかけます。\n・「78.5」…5×5×3.14の答えで、円の面積の計算です。円周ではありません。\n・「314」…10×3.14の小数点の位置をずらした数です。31.4です。",
  "math_g5_hand_circle_009":"円周＝直径×円周率なので、直径＝円周÷円周率です。12.56÷3.14＝4で、直径は4cmです。\n\nほかの 選択肢\n・「2」…半径の長さです。問いは直径です。\n・「8」…4×2の答えで、直径をさらに2倍した数です。\n・「6.28」…12.56÷2の答えです。3.14でわります。",
  "math_g5_hand_circle_010":"円周＝直径×円周率です。8×3.14＝25.12で、円周は25.12cmです。\n\nほかの 選択肢\n・「11.14」…8＋3.14の答えです。円周は、たし算ではなく、かけ算で求めます。\n・「50.24」…8×2×3.14の答えで、直径をさらに2倍した数です。\n・「251.2」…8×3.14の小数点の位置をずらした数です。25.12です。",
  "math_g5_hand_circle_011":"正六角形は、６つの辺の長さがすべて等しいので、まわりの長さは5×6＝30cmです。\n\nほかの 選択肢\n・「25」…5×5の答えです。辺は６本あります。\n・「35」…5×7の答えです。辺は７本ではなく、６本です。\n・「15」…5×3の答えです。辺は６本あります。",
  "math_g5_hand_circle_012":"円周＝直径×円周率なので、直径は62.8÷3.14＝20cmです。半径は直径の半分なので、20÷2＝10cmです。\n\nほかの 選択肢\n・「20」…直径の長さです。半径は、その半分です。\n・「5」…直径の半分のさらに半分です。半径は10cmです。\n・「6.28」…62.8÷10の答えです。3.14でわって直径を求めます。",
  "math_g5_hand_circle_013":"円の中心のまわりの角は360°です。正八角形は８つに分けるので、360÷8＝45で、中心の角は45°です。\n\nほかの 選択肢\n・「60」…正六角形の中心の角（360÷6）です。正八角形は45°です。\n・「30」…正十二角形の中心の角（360÷12）です。正八角形は45°です。\n・「135」…正八角形の１つの角の大きさです。中心の角ではありません。",
  "math_g5_hand_circle_014":"円の中心のまわりの角は360°です。正五角形は５つに分けるので、360÷5＝72で、中心の角は72°です。\n\nほかの 選択肢\n・「60」…正六角形の中心の角（360÷6）です。正五角形は72°です。\n・「108」…正五角形の１つの角の大きさです。中心の角ではありません。\n・「36」…72°の半分です。中心の角は72°です。",
  "math_g5_hand_circle_015":"車輪が１回転すると、円周と同じ長さだけ進みます。60×3.14＝188.4で、188.4cm進みます。\n\nほかの 選択肢\n・「94.2」…30×3.14の答えで、半径にそのまま3.14をかけた数です。直径にかけます。\n・「60」…車輪の直径そのものです。進む長さは円周です。\n・「376.8」…２回転分の長さです。問いは１回転です。",
  "math_g5_hand_circle_016":"中心の角は360÷6＝60°です。２つの辺は半径で等しいので二等辺三角形、底角も60°で、正三角形になります。１辺は半径と同じ6cmです。\n\nほかの 選択肢\n・「3」…半径の半分です。１辺は半径と同じです。\n・「12」…直径の長さです。正六角形の１辺は、半径と同じです。\n・「9」…半径と半径の半分を足した数のようなもので、図形の関係から出る数ではありません。",
  "math_g5_hand_circle_017":"直径は50cm＝0.5mです。１回転で0.5×3.14＝1.57m進み、10回転では1.57×10＝15.7mです。\n\nほかの 選択肢\n・「157」…15.7の小数点の位置をずらした数です。単位がcmのような数でもあります。\n・「78.5」…半径の25cmに3.14をかけた数です。円周は直径にかけます。\n・「31.4」…10×3.14の答えで、回転の数に3.14だけをかけた数です。",
  "math_g5_hand_circle_018":"半径10cmの円は直径が20cmなので、円周は20×3.14＝62.8cmです。直径10cmの円周は10×3.14＝31.4cmです。62.8－31.4＝31.4で、31.4cm長いです。\n\nほかの 選択肢\n・「10」…半径と直径の長さの数です。円周のちがいではありません。\n・「62.8」…半径10cmの円の円周です。ちがいを求めるには、直径10cmの円周をひきます。\n・「94.2」…2つの円周を足した数です。問いは、ちがいです。",
  "math_g5_hand_circle_019":"直径＝円周÷円周率です。94.2÷3.14＝30で、直径は30cmです。\n\nほかの 選択肢\n・「15」…半径の長さです。問いは直径です。\n・「60」…30×2の答えで、直径をさらに2倍した数です。\n・「45」…94.2÷2.1のような計算のミスで、3.14でわっていません。",
  "math_g5_hand_circle_020":"円の中心のまわりの角は360°です。正十二角形は12に分けるので、360÷12＝30で、中心の角は30°です。\n\nほかの 選択肢\n・「12」…頂点の数（三角形の数）です。角の大きさではありません。\n・「36」…正十角形の中心の角（360÷10）です。正十二角形は30°です。\n・「60」…正六角形の中心の角（360÷6）です。正十二角形は30°です。",
  "math_g5_hand_circle_021":"円周＝直径×円周率なので、直径は157÷3.14＝50mです。\n\nほかの 選択肢\n・「25」…半径の長さです。問いは直径です。\n・「100」…50×2の答えで、直径をさらに2倍した数です。\n・「78.5」…157÷2の答えです。3.14でわって直径を求めます。",
  "math_g5_hand_circle_022":"円周は直径10cmなので10×3.14＝31.4cmです。正六角形は一辺が半径と同じ5cmなので、5×6＝30cmです。31.4－30＝1.4で、1.4cmちがいます。\n\nほかの 選択肢\n・「0.7」…1.4の半分です。ちがいは1.4cmです。\n・「3.14」…円周率の数です。長さのちがいではありません。\n・「2.4」…計算まちがいの数です。31.4－30＝1.4です。",
  "math_g5_hand_congruent_001":"ぴったり重ね合わせることができる２つの図形を「合同な図形」といいます。形も大きさも同じです。\n\nほかの 選択肢\n・「相似な図形」…形は同じで、大きさがちがってもよい図形です。\n・「対称な図形」…線対称や点対称のように、折ったり回したりして重なる１つの図形のことです。\n・「平行な図形」…平行は、直線のならび方の言葉で、図形の関係の名前ではありません。",
  "math_g5_hand_congruent_002":"合同な図形を重ねたとき、重なり合う頂点を「対応する頂点」といいます。辺は「対応する辺」、角は「対応する角」です。\n\nほかの 選択肢\n・「対角の頂点」…四角形で、向かい合う頂点のことです。\n・「となりあう頂点」…同じ辺の両はしの頂点です。\n・「向かい合う頂点」…四角形のななめの頂点のことです。",
  "math_g5_hand_congruent_003":"合同な図形はぴったり重なるので、対応する辺の長さは等しくなっています。\n\nほかの 選択肢\n・「２倍になっている」…２倍の長さなら、ぴったり重なりません。\n・「半分になっている」…半分の長さなら、ぴったり重なりません。\n・「ちがっている」…長さがちがうと、ぴったり重なりません。",
  "math_g5_hand_congruent_004":"辺ＡＢと辺ＥＦは対応する辺です。合同な図形の対応する辺は等しいので、辺ＥＦも5cmです。\n\nほかの 選択肢\n・「10」…辺ＡＢの2倍です。合同な図形で対応する辺は2倍にならず、等しいです。\n・「2.5」…辺ＡＢの半分です。合同な図形で対応する辺は半分にならず、等しいです。\n・「6」…辺ＡＢとちがう数です。対応する辺は、5cmで等しくなります。",
  "math_g5_hand_congruent_005":"合同な図形はぴったり重なるので、対応する角の大きさは等しくなっています。\n\nほかの 選択肢\n・「２倍になっている」…２倍の角なら、ぴったり重なりません。\n・「半分になっている」…半分の角なら、ぴったり重なりません。\n・「ちがっている」…角の大きさがちがうと、ぴったり重なりません。",
  "math_g5_hand_congruent_006":"うら返してぴったり重なる図形も、合同な図形といえます。向きが反対でも、形と大きさが同じなら合同です。答えは、いえるです。\n\nほかの 選択肢\n・「いえない」…うら返して重なる図形も、形と大きさが同じなので、合同といえます。\n・「三角形のときだけいえる」…合同は、三角形にかぎらず、どんな図形でも同じです。\n・「四角形のときだけいえる」…合同は、四角形にかぎらず、どんな図形でも同じです。",
  "math_g5_hand_congruent_007":"角Ａと角Ｄは対応する角です。合同な図形の対応する角は等しいので、角Ｄも70°です。\n\nほかの 選択肢\n・「110」…180－70の答えです。となり合う角の関係で、対応する角ではありません。\n・「35」…70の半分です。合同な図形で対応する角は半分になりません。\n・「140」…70の2倍です。合同な図形で対応する角は2倍になりません。",
  "math_g5_hand_congruent_008":"３つの辺の長さがそれぞれ等しい２つの三角形は、合同です。3cm、4cm、5cmなら、形が１つに決まるので、答えは、いえるです。\n\nほかの 選択肢\n・「いえない」…３つの辺の長さが等しければ、三角形の形は決まるので、合同といえます。\n・「角の大きさがわからないのでいえない」…辺の長さが3つわかれば、角の大きさも決まります。\n・「もう１つ条件がないといえない」…３つの辺の長さが等しいだけで、合同といえます。",
  "math_g5_hand_congruent_009":"合同といえるのは、３つの辺、２つの辺とその間の角、１つの辺とその両はしの角が、それぞれ等しいときです。「３つの角の大きさがそれぞれ等しい」だけでは、大きさのちがう三角形もあるので、合同とはいえません。\n\nほかの 選択肢\n・「３つの辺の長さがそれぞれ等しい」…三角形の形が１つに決まるので、合同といえます。\n・「２つの辺の長さとその間の角の大きさがそれぞれ等しい」…三角形の形が１つに決まるので、合同といえます。\n・「１つの辺の長さとその両はしの角の大きさがそれぞれ等しい」…三角形の形が１つに決まるので、合同といえます。",
  "math_g5_hand_congruent_010":"三角形の角の和は180°です。50＋60＝110、180－110＝70で、のこりの角は70°です。\n\nほかの 選択肢\n・「110」…50＋60の答えです。180°からひいていません。\n・「130」…180－50の答えです。60°もひく必要があります。\n・「120」…180－60の答えです。50°もひく必要があります。",
  "math_g5_hand_congruent_011":"辺ＢＣと辺ＦＧは対応する辺です。合同な図形の対応する辺は等しいので、辺ＦＧも6cmです。\n\nほかの 選択肢\n・「12」…辺ＢＣの2倍です。合同な図形で対応する辺は2倍にならず、等しいです。\n・「3」…辺ＢＣの半分です。合同な図形で対応する辺は半分にならず、等しいです。\n・「9」…辺ＢＣとちがう数です。対応する辺は、6cmで等しくなります。",
  "math_g5_hand_congruent_012":"正方形の対角線で分けた２つの三角形は、３つの辺の長さがそれぞれ等しい（正方形の辺２本と、共通の対角線）ので、合同である、といえます。対角線を折り目にして、ぴったり重ねることもできます。\n\nほかの 選択肢\n・「合同ではない」…２つの三角形は、辺も角も同じなので、合同です。\n・「大きさだけが同じ」…大きさだけでなく、形も同じです。ぴったり重なります。\n・「形だけが同じ」…形だけでなく、大きさも同じです。ぴったり重なります。",
  "math_g5_hand_congruent_013":"平行四辺形は向かい合う辺の長さが等しく、対角線は２つの三角形に共通の辺です。３つの辺がそれぞれ等しいので、合同である、といえます。\n\nほかの 選択肢\n・「合同ではない」…３つの辺がそれぞれ等しいので、合同です。\n・「面積だけが同じ」…面積だけでなく、形も同じです。ぴったり重なります。\n・「合同とは限らない」…平行四辺形の対角線で分けると、必ず合同になります。",
  "math_g5_hand_congruent_014":"合同な図形は、ぴったり重なるので、面積も等しくなります。\n\nほかの 選択肢\n・「どちらかが大きい」…ぴったり重なるなら、大きさは同じなので、どちらかが大きいことはありません。\n・「２倍になる」…２倍の面積なら、ぴったり重なりません。\n・「わからない」…合同だとわかっているので、面積が等しいことがわかります。",
  "math_g5_hand_congruent_015":"合同な三角形は、対応する辺の長さがすべて等しいので、まわりの長さも等しくなります。答えは12cmです。\n\nほかの 選択肢\n・「6」…12の半分です。合同な三角形は、まわりの長さも半分になりません。\n・「24」…12の2倍です。合同な三角形は、まわりの長さも2倍になりません。\n・「18」…12とちがう数です。まわりの長さは12cmのままです。",
  "math_g5_hand_congruent_016":"どちらも角Ａが80°、角Ｂ（角Ｅ）が50°で、三角形の角の和から、のこりの角も180－130＝50°で等しくなります。でも、３つの角が等しいだけでは、大きさがちがうこともあるので、答えは「合同とは限らない」です。\n\nほかの 選択肢\n・「必ず合同である」…３つの角が等しくても、辺の長さがちがう三角形があります。\n・「合同ではない」…辺の長さが等しいこともあるので、合同でないと決まるわけではありません。\n・「角Ｃが等しくないので合同ではない」…角Ｃも、角Ｆも50°で、等しいです。",
  "math_g5_hand_congruent_017":"Ａ→Ｐ、Ｂ→Ｑ、Ｃ→Ｒと対応するので、辺ＱＲは辺ＢＣに対応します。辺ＢＣが7cmなので、辺ＱＲも7cmです。\n\nほかの 選択肢\n・「5」…辺ＡＢの長さです。辺ＡＢに対応するのは、辺ＰＱです。\n・「6」…辺ＣＡの長さです。辺ＣＡに対応するのは、辺ＲＰです。\n・「18」…３つの辺の長さの和（5＋7＋6）です。辺ＱＲ１つ分の長さではありません。",
  "math_g5_hand_congruent_018":"４つの辺が等しくても、角の大きさがちがうひし形があるので、「合同とは限らない」が答えです。たとえば、正方形とつぶれたひし形は、辺が同じでも形がちがいます。\n\nほかの 選択肢\n・「必ず合同である」…辺が等しくても、角の大きさがちがう四角形があります。\n・「合同ではない」…正方形どうしなら合同になることもあるので、合同でないと決まるわけではありません。\n・「どちらも正方形だから合同」…問いは、正方形とはかぎりません。",
  "math_g5_hand_congruent_019":"角Ａ（角Ｄ）は、辺ＡＢと辺ＡＣ（辺ＤＥと辺ＤＦ）にはさまれた角です。２つの辺の長さとその間の角の大きさがそれぞれ等しいので、合同です。\n\nほかの 選択肢\n・「３つの角の大きさがそれぞれ等しいから」…角は１つしかわかっていません。\n・「３つの辺の長さがそれぞれ等しいから」…辺は２つしかわかっていません。\n・「１つの辺の長さとその両はしの角がそれぞれ等しいから」…わかっている角は１つで、辺の両はしの角ではありません。",
  "math_g5_hand_congruent_020":"「２つの辺とその間の角」がわかると、三角形が１つに決まります。辺が４cm、５cmでその間の角が60°なら、かくことができます。\n\nほかの 選択肢\n・「３つの角が60°、60°、60°」…正三角形になりますが、辺の長さがわからないので、大きさは決まりません。\n・「辺が５cm、５cmだけ」…間の角がわからないので、形がいくつもできます。\n・「辺が４cm、角が40°だけ」…条件が少なく、三角形はいくつもできます。",
  "math_g5_hand_congruent_021":"三角形ＡＢＣと三角形ＣＤＡは、Ａ→Ｃ、Ｂ→Ｄと対応するので、辺ＡＢに対応するのは、辺ＣＤです。\n\nほかの 選択肢\n・「辺ＢＣ」…辺ＢＣに対応するのは、辺ＤＡです。\n・「辺ＤＡ」…辺ＤＡは、辺ＢＣに対応する辺です。\n・「辺ＡＣ」…辺ＡＣは、2つの三角形に共通の辺で、自分自身に対応します。",
  "math_g5_hand_congruent_022":"合同な長方形を横にくっつけると、横は7×2＝14cm、たては4cmです。まわりの長さは(4＋14)×2＝36cmです。\n\nほかの 選択肢\n・「22」…もとの長方形(4＋7)×2のまわりの長さです。くっつけた大きな長方形ではありません。\n・「44」…(4＋18)×2のような、横の長さをまちがえた計算です。横は14cmです。\n・「56」…4×14の答えで、大きな長方形の面積です。まわりの長さではありません。",
  "math_g5_hand_decdiv_001":"4.8÷2＝2.4です。0.1の何こ分かで考えると、48÷2＝24なので、2.4になります。答えは2.4Lです。\n\nほかの 選択肢\n・「24」…小数点を忘れた数です。4.8÷2は、2.4です。\n・「9.6」…4.8×2の答えです。等しく分けるので、かけ算ではなく、わり算です。\n・「2.8」…4.8－2の答えです。等しく分けるので、ひき算ではなく、わり算です。",
  "math_g5_hand_decdiv_002":"7.5÷5＝1.5です。0.1の何こ分かで考えると、75÷5＝15なので、1.5になります。答えは1.5mです。\n\nほかの 選択肢\n・「15」…小数点を忘れた数です。7.5÷5は、1.5です。\n・「2.5」…7.5－5の答えです。等しく分けるので、ひき算ではなく、わり算です。\n・「12.5」…7.5＋5の答えです。等しく分けるので、たし算ではなく、わり算です。",
  "math_g5_hand_decdiv_003":"わる数もわられる数も10倍すると、答えは変わりません。3.6÷0.6＝36÷6＝6です。\n\nほかの 選択肢\n・「0.6」…わる数の0.6と同じ数です。3.6÷0.6の答えは6です。\n・「3」…3.6÷1.2のような数です。3.6÷0.6は6です。\n・「4.2」…3.6＋0.6の答えです。わり算を、たし算にしてしまった数です。",
  "math_g5_hand_decdiv_004":"わる数もわられる数も10倍すると、答えは変わりません。0.9÷0.3＝9÷3＝3です。\n\nほかの 選択肢\n・「0.3」…わる数と同じ数です。0.9÷0.3の答えは3です。\n・「0.6」…0.9－0.3の答えです。わり算を、ひき算にしてしまった数です。\n・「1.2」…0.9＋0.3の答えです。わり算を、たし算にしてしまった数です。",
  "math_g5_hand_decdiv_005":"6.4÷4＝1.6です。0.1の何こ分かで考えると、64÷4＝16なので、1.6になります。答えは1.6mです。\n\nほかの 選択肢\n・「16」…小数点を忘れた数です。6.4÷4は、1.6です。\n・「2.4」…6.4－4の答えです。等分するので、ひき算ではなく、わり算です。\n・「10.4」…6.4＋4の答えです。等分するので、たし算ではなく、わり算です。",
  "math_g5_hand_decdiv_006":"0.4mずつに切るので、2.4÷0.4で本数を求めます。10倍して24÷4＝6で、6本できます。\n\nほかの 選択肢\n・「0.6」…2.4÷4のように、わる数を整数にしてしまった数です。2.4÷0.4＝6です。\n・「2」…2.4－0.4のような、ひき算の答えです。本数は、わり算で求めます。\n・「2.8」…2.4＋0.4の答えです。本数は、たし算ではなく、わり算で求めます。",
  "math_g5_hand_decdiv_007":"わる数の６は整数なので、わられる数の小数点の位置をそのままそろえて商に書きます。84÷6＝14で、8.4は84の10分の１だから、商も14の10分の１の1.4です。\n\nほかの 選択肢\n・「14」…小数点を付け忘れたり、位を１つずらしたりすると出る数です。8.4÷6は、8.4より小さい数になります。\n・「2.4」…８.４から６をひき算した数です。この問題はわり算なので、ちがいます。\n・「4.2」…わる数を２と見まちがえて、8.4÷２をした数です。わる数は６なので、ちがいます。",
  "math_g5_hand_decdiv_008":"わる数もわられる数も10倍すると、1.8÷0.9は18÷9と同じになり、商は２です。わる数とわられる数を同じ数倍しても、商は変わりません。\n\nほかの 選択肢\n・「0.2」…18÷9＝２を、小数点の位置をまちがえて0.2にした数です。1.8は0.9の２倍なので、商は２です。\n・「0.9」…わる数の0.9をそのまま答えにした数です。1.8÷0.9は、0.9が何こ分かを聞いているので、ちがいます。\n・「2.7」…1.8と0.9をたし算した数です。わり算の問題なので、ちがいます。",
  "math_g5_hand_decdiv_009":"９mを1.5mずつに切る本数は、９÷1.5で求めます。両方を10倍して90÷15にすると、商は６です。1.5mが６本で、ちょうど９mになります。\n\nほかの 選択肢\n・「0.6」…６をもとに小数点をずらした数です。1.5mは１mより長いので、本数は９本より少なくなりますが、0.6本ではありません。\n・「7.5」…９mから1.5mをひき算した数です。本数を聞いているので、わり算で考えます。\n・「10.5」…９と1.5をたし算した数です。わり算の問題なので、ちがいます。",
  "math_g5_hand_decdiv_010":"7.2÷0.8は、両方を10倍して72÷8にします。商は９です。0.8を９こ集めると7.2になることからも確かめられます。\n\nほかの 選択肢\n・「90」…９の位を１つずらして、10倍にした数です。0.8×90は72なので、ちがいます。\n・「6.4」…7.2から0.8をひき算した数です。この問題はわり算なので、ちがいます。\n・「8」…7.2と0.8をたした数です。たし算にしてしまったときに出る数で、ちがいます。",
  "math_g5_hand_decdiv_011":"5.4÷1.8は、両方を10倍して54÷18にすると、商は３です。1.8を３こ集めると5.4になります。\n\nほかの 選択肢\n・「30」…３の位を１つずらした数です。1.8×30＝54なので、5.4÷1.8の商ではありません。\n・「3.6」…5.4から1.8をひき算した数です。わり算の問題なので、ちがいます。\n・「7.2」…5.4と1.8をたした数です。たし算にしてしまったときに出る数で、ちがいます。",
  "math_g5_hand_decdiv_012":"9.6÷2.4は、両方を10倍して96÷24にします。24×４＝96なので、商は４です。\n\nほかの 選択肢\n・「40」…４の位を１つずらした数です。2.4×40＝96なので、9.6÷2.4の商ではありません。\n・「7.2」…9.6から2.4をひき算した数です。わり算の問題なので、ちがいます。\n・「12」…9.6と2.4をたした数です。たし算にしてしまったときに出る数で、ちがいます。",
  "math_g5_hand_decdiv_013":"わる数の0.15を整数にするため、両方を100倍して450÷15にします。商は30です。0.15を30こ集めると4.5になります。\n\nほかの 選択肢\n・「3」…30の位を１つずらして、10分の１にした数です。0.15×３は0.45なので、4.5にはなりません。\n・「300」…30の位を１つずらして、10倍にした数です。0.15×300＝45なので、ちがいます。\n・「45」…わられる数の4.5を10倍しただけで、わる数を整数にするのを忘れたときの数です。",
  "math_g5_hand_decdiv_014":"わる数が１より小さいとき、商はわられる数より大きくなります。８÷0.5は、８の中に0.5がいくつあるかを聞いていて、８÷0.5＝16です。答えは「８より大きい」です。\n\nほかの 選択肢\n・「８より小さい」…わる数が１より大きいときの考え方です。0.5は１より小さいので、商は８より大きくなります。\n・「８と同じ」…わる数が１のときの商です。\n・「８の10分の１になる」…わる数が10のときの商です。",
  "math_g5_hand_decdiv_015":"８÷1.6は、両方を10倍して80÷16にします。商は５で、1.6を５こ集めると８になります。\n\nほかの 選択肢\n・「50」…５の位を１つずらして、10倍にした数です。1.6×50＝80なので、ちがいます。\n・「6.4」…1.6×４を計算した数など、ちがうしくみで出た数です。1.6×５＝８なので、商は５です。\n・「9.6」…８と1.6をたした数です。たし算にしてしまったときに出る数で、ちがいます。",
  "math_g5_hand_decdiv_016":"12÷0.75は、両方を100倍して1200÷75にします。75×16＝1200なので、商は16です。わる数が１より小さいので、商は12より大きくなります。\n\nほかの 選択肢\n・「160」…16の位を１つずらして、10倍にした数です。0.75×160＝120なので、ちがいます。\n・「9」…12×0.75の積です。わり算の問題なのに、かけ算をしたときに出る数です。\n・「11.25」…12から0.75をひき算した数です。わり算の問題なので、ちがいます。",
  "math_g5_hand_decdiv_017":"７÷３＝2.333…です。小数第１位までのがい数なので、すぐ下の小数第２位の３を見ます。５より小さいので切り捨てて、2.3です。\n\nほかの 選択肢\n・「2.33」…小数第２位までのがい数です。この問題は小数第１位までなので、ちがいます。\n・「2.4」…小数第２位が３なので、切り上げるのはまちがいです。切り上げは、５以上のときにします。\n・「2.2」…小数第１位より下をすべて切り捨てるのではなく、四捨五入です。2.33は2.2より2.3に近いので、ちがいます。",
  "math_g5_hand_decdiv_018":"10÷７＝1.4285…です。小数第２位までなので、すぐ下の小数第３位の８を見ます。５以上なので切り上げて、1.43です。\n\nほかの 選択肢\n・「1.4」…小数第１位までのがい数です。この問題は小数第２位までなので、ちがいます。\n・「1.42」…小数第３位の８を切り捨ててしまった数です。８は５以上なので、切り上げます。\n・「1.429」…小数第３位までのがい数です。この問題は小数第２位までなので、ちがいます。",
  "math_g5_hand_decdiv_019":"7.5÷２＝３あまり1.5です。２m×３本＝６mで、7.5－６＝1.5mがのこります。あまりの小数点は、わられる数の7.5にそろえます。答えは「３本とれて、1.5mあまる」です。\n\nほかの 選択肢\n・「３本とれて、0.15mあまる」…あまりの小数点を、わられる数にそろえず、１けた左にずらした数です。あまりは1.5mです。\n・「４本とれて、0.5mあまる」…４本とるには、２m×４＝８mが必要です。\n・「３本とれて、1.5mたりない」…７.５mから６mを切ると1.5mのこります。",
  "math_g5_hand_decdiv_020":"わる数の0.12を整数にするため、両方を100倍して360÷12にします。商は30です。0.12を30こ集めると3.6になります。\n\nほかの 選択肢\n・「3」…30の位を１つずらして、10分の１にした数です。0.12×３は0.36なので、ちがいます。\n・「300」…30の位を１つずらして、10倍にした数です。0.12×300＝36なので、ちがいます。\n・「36」…わられる数の3.6を10倍した数です。わる数も同じように変えないと、商は変わってしまいます。",
  "math_g5_hand_decdiv_021":"長方形の面積＝たて×横なので、横＝面積÷たてです。6.3÷1.8は、両方を10倍して63÷18＝3.5になります。\n\nほかの 選択肢\n・「35」…3.5の位を１つずらして、10倍にした数です。1.8×35は63なので、ちがいます。\n・「4.5」…面積6.3からたての1.8をひき算した数です。面積とたての関係は、ひき算ではありません。\n・「8.1」…面積6.3とたての1.8をたし算した数です。横は、面積をたてでわって求めます。",
  "math_g5_hand_decdiv_022":"2.4Lを0.3Lずつ分けるので、2.4÷0.3で求めます。両方を10倍して24÷3＝８です。カップが８こ必要です。\n\nほかの 選択肢\n・「80」…８の位を１つずらして、10倍にした数です。0.3L×80は24Lなので、ちがいます。\n・「2.7」…2.4Lと0.3Lをたした数です。こ数を聞いているので、わり算で考えます。\n・「2.1」…2.4Lから0.3Lをひいた数です。こ数を聞いているので、わり算で考えます。",
  "math_g5_hand_decdiv_023":"１kgのねだんは、450円を1.5kgでわって求めます。450÷1.5は、両方を10倍して4500÷15＝300です。\n\nほかの 選択肢\n・「675」…450円に1.5をかけた数です。１kgは1.5kgより軽いので、ねだんは450円より安くなります。\n・「3000」…300の位を１つずらして、10倍にした数です。1.5kgが3000円になるわけではないので、ちがいます。\n・「450」…1.5kg分のねだんそのものです。聞かれているのは、１kgのねだんです。",
  "math_g5_hand_decdiv_024":"6.8÷0.4は、両方を10倍して68÷４にします。商は17です。0.4を17こ集めると6.8になります。\n\nほかの 選択肢\n・「170」…17の位を１つずらして、10倍にした数です。0.4×170＝68なので、ちがいます。\n・「6.4」…6.8から0.4をひいた数です。わり算の問題なので、ちがいます。\n・「7.2」…6.8と0.4をたした数です。たし算にしてしまったときに出る数で、ちがいます。",
  "math_g5_hand_decdiv_025":"12.6÷0.9は、両方を10倍して126÷９にします。商は14です。0.9を14こ集めると12.6になります。\n\nほかの 選択肢\n・「140」…14の位を１つずらして、10倍にした数です。0.9×140＝126なので、ちがいます。\n・「11.7」…12.6から0.9をひいた数です。わり算の問題なので、ちがいます。\n・「13.5」…12.6と0.9をたした数です。わり算の問題なので、ちがいます。",
  "math_g5_hand_decdiv_026":"計算は左から順にします。まず3.5÷0.7＝５、次に５×２＝10です。わり算とかけ算がならんでいるときは、左から計算します。\n\nほかの 選択肢\n・「2.5」…３.５÷0.7＝５を、さらに２でわった数です。式は「×２」なので、かけ算をします。\n・「5」…3.5÷0.7＝５で止めてしまい、×２をしていない数です。\n・「20」…５を４倍するなど、計算のとちゅうでまちがえたときに出る数です。５×２＝10なので、ちがいます。",
  "math_g5_hand_decdiv_027":"横は 7.2÷2.4＝３m です。長方形のまわりの長さは、（たて＋横）×２なので、（2.4＋３）×２＝10.8mです。\n\nほかの 選択肢\n・「5.4」…たてと横をたしただけで、×２をしていない数です。まわりは、たてと横が２本ずつあります。\n・「7.8」…たて２本分と横１本分をたした数です。横も２本あるので、ちがいます。\n・「8.4」…たて１本分と横２本分をたした数です。たても２本あるので、ちがいます。",
  "math_g5_hand_decdiv_028":"1.26÷0.18は、両方を100倍して126÷18にします。商は７です。0.18を７こ集めると1.26になります。\n\nほかの 選択肢\n・「70」…７の位を１つずらして、10倍にした数です。0.18×70＝12.6なので、ちがいます。\n・「1.08」…1.26から0.18をひいた数です。わり算の問題なので、ちがいます。\n・「6」…６に近い数ですが、0.18×６＝1.08で、1.26になりません。",
  "math_g5_hand_decdiv_029":"５÷0.35は、0.35mを14本とると0.35×14＝4.9mです。５－4.9＝0.1なので、14本とれて0.1mあまります。あまりは、わる数の0.35より小さくなります。答えは「14本とれて、0.1mあまる」です。\n\nほかの 選択肢\n・「14本とれて、0.01mあまる」…あまりの小数点の位置をまちがえた数です。\n・「15本とれて、0.1mあまる」…15本とるには、0.35×15＝5.25mが必要です。\n・「14本とれて、1mあまる」…あまりの1mは、わる数の0.35mより大きいのでまちがいです。もう１本とれてしまいます。",
  "math_g5_hand_decdiv_030":"１Lでぬれる面積は、1.2÷1.5で求めます。両方を10倍して12÷15＝0.8です。1.5Lより少ない１Lでは、ぬれる面積も1.2m²より少なくなります。\n\nほかの 選択肢\n・「8」…0.8の位を１つずらして、10倍にした数です。１Lでは1.2m²より広くはぬれません。\n・「1.25」…1.5÷1.2の商です。わる数とわられる数を入れかえてしまったときに出る数です。\n・「0.3」…1.5から1.2をひき算した数です。この問題はわり算なので、ちがいます。",
  "math_g5_hand_decdiv_031":"速さは、道のり÷時間で求めます。20÷2.5は、両方を10倍して200÷25＝８です。１時間に８km進みます。\n\nほかの 選択肢\n・「80」…８の位を１つずらして、10倍にした数です。2.5時間で20kmなのに、１時間で80kmは進めません。\n・「50」…20に2.5をかけた数です。速さは、かけ算でなくわり算で求めます。\n・「17.5」…20から2.5をひいた数です。この問題はわり算なので、ちがいます。",
  "math_g5_hand_decdiv_032":"□÷0.5＝12は、□＝12×0.5と考えます。わり算の式の□は、答えにわる数をかけると求められます。12×0.5＝６です。たしかめると、６÷0.5＝12になります。\n\nほかの 選択肢\n・「24」…12÷0.5をした数です。□を求めるには、逆の計算のかけ算をします。\n・「12」…答えの12をそのまま書いた数です。6÷0.5＝12なので、□は６です。\n・「12.5」…12と0.5をたし算した数です。わり算の逆は、かけ算です。",
  "math_g5_hand_decdiv_033":"20÷３＝6.666…です。小数第２位までなので、すぐ下の小数第３位の６を見ます。５以上なので切り上げて、6.67です。\n\nほかの 選択肢\n・「6.6」…小数第１位までで切り捨てた数です。小数第２位まで求めるので、ちがいます。\n・「6.7」…小数第１位までに丸めた数です。小数第２位まで求めるので、ちがいます。\n・「6.66」…小数第３位の６を切り捨てた数です。６は５以上なので、切り上げます。",
  "math_g5_hand_decdiv_034":"左から順に計算します。2.7÷0.9＝３、３÷３＝１です。わり算が続くときは、前から順に計算します。答えは 1 です。\n\nほかの 選択肢\n・「9」…0.9÷３を先に計算して、2.7÷0.3をした数です。順番がちがうので、ちがいます。\n・「3」…2.7÷0.9＝３で止めてしまい、最後の÷３をしていない数です。\n・「0.9」…わる数の0.9をそのまま答えにした数です。式の最後まで計算すると１になります。",
  "math_g5_hand_decdiv_035":"長さは、全体の重さ÷１mの重さで求めます。15÷0.6は、両方を10倍して150÷６＝25です。ロープの長さは25mです。\n\nほかの 選択肢\n・「9」…15×0.6の積です。長さを求めるのに、かけ算をしてしまった数です。\n・「2.5」…25の位を１つずらして、10分の１にした数です。0.6kg×2.5は1.5kgなので、ちがいます。\n・「14.4」…15kgから0.6kgをひき算した数です。この問題はわり算なので、ちがいます。",
  "math_g5_hand_decdiv_036":"5.4÷0.8は、0.8×６＝4.8で、６ふくろできます。5.4－4.8＝0.6kgあまります。あまりは、わる数の0.8より小さくなります。答えは「６ふくろできて、0.6kgあまる」です。\n\nほかの 選択肢\n・「６ふくろできて、0.06kgあまる」…あまりの小数点の位置をまちがえた数です。\n・「７ふくろできて、0.2kgあまる」…７ふくろ作るには、0.8×７＝5.6kgが必要です。\n・「６ふくろできて、6kgあまる」…あまりの６kgは、0.8kgのふくろにまだ何ふくろも作れるので、まちがいです。",
  "math_g5_hand_decmul_001":"１mが0.3kgのロープ４mの重さは、0.3×４で求めます。３×４＝12で、0.3は小数点以下が１けたなので、積も１けたにして1.2です。\n\nほかの 選択肢\n・「12」…小数点を付け忘れた数です。0.3kgを４倍して12kgにはなりません。\n・「0.7」…0.3と0.4をたし算した数に当たります。この問題はかけ算なので、ちがいます。\n・「1.6」…0.3×４＝1.2なので、1.6にはなりません。0.3を４回たすと1.2です。",
  "math_g5_hand_decmul_002":"１つ1.5Lのバケツが３つなので、1.5×３で求めます。15×３＝45で、小数点以下が１けたなので4.5です。1.5Lは１Lと２Lの間なので、全部で３Lと６Lの間になります。\n\nほかの 選択肢\n・「0.45」…小数点の位置を１つずらした数です。１つのバケツだけで1.5Lあるので、全部が0.45Lにはなりません。\n・「4」…1.5を１と見て、１×３をした数です。0.5Lの分が入っていません。\n・「6」…1.5を２と見て、２×３をした数です。1.5は２より小さいので、ちがいます。",
  "math_g5_hand_decmul_003":"0.6×0.5は、６×５＝30を求めます。小数点以下が１けた＋１けたで合わせて２けたなので、0.30、つまり0.3です。0.5m²は１m²の半分なので、水も0.6Lの半分の0.3Lです。\n\nほかの 選択肢\n・「3」…小数点以下の数を数えずに、30の0をとった数です。0.5m²では0.6Lより少ない量です。\n・「0.5」…ぬる面積の0.5をそのまま答えた数です。水の量を聞かれています。\n・「0.6」…１m²に使う水の量をそのまま書いた数です。0.5m²では、これより少なくなります。",
  "math_g5_hand_decmul_004":"0.2×0.3は、２×３＝６を求めて、小数点以下のけた数を合わせます。１けた＋１けたで２けたなので、0.06です。\n\nほかの 選択肢\n・「0.6」…小数点以下を１けたしか取らなかった数です。0.2も0.3も１より小さいので、積は0.2より小さくなります。\n・「0.5」…0.2と0.3をたした数です。面積はたて×横なので、かけ算で求めます。\n・「0.05」…小数点以下は２けたでよいのですが、２×３＝６を５としているので、ちがいます。",
  "math_g5_hand_decmul_005":"１こ1.2kgを５こ運ぶので、1.2×５で求めます。12×５＝60で、小数点以下が１けたなので6.0＝６です。\n\nほかの 選択肢\n・「60」…小数点を付け忘れた数です。１こで1.2kgもあるので、５こで60kgにはなりません。\n・「6.2」…1.2に５をたした数です。同じ重さが５こなので、かけ算をします。\n・「5」…1.2×５の0.2の部分（0.2×５＝１）を忘れて、整数部分だけで計算した数です。",
  "math_g5_hand_decmul_006":"代金は、１mのねだん×長さで求めます。300×0.4＝120円です。0.4mは１mより短いので、代金は300円より安くなります。\n\nほかの 選択肢\n・「1200」…位を１つずらして、10倍にした数です。0.4mは１mより短いので、300円より安くなります。\n・「300」…１mのねだんそのものです。0.4mを買うので、300円より安くなります。\n・「150」…300円の半分です。0.5mを買ったときの代金で、0.4mではありません。",
  "math_g5_hand_decmul_007":"正方形の面積は、１辺×１辺です。0.5×0.5は、５×５＝25を求め、小数点以下が２けたなので0.25です。\n\nほかの 選択肢\n・「2.5」…小数点の位置を１つずらした数です。0.5より小さい長さどうしのかけ算なので、積は0.5より小さくなります。\n・「1」…0.5＋0.5をした数です。面積はかけ算で求めます。\n・「0.5」…１辺の長さをそのまま書いた数です。面積は、１辺×１辺で求めます。",
  "math_g5_hand_decmul_008":"0.8kgの鉄のぼうが３mなので、0.8×３で求めます。８×３＝24で、小数点以下が１けたなので2.4です。\n\nほかの 選択肢\n・「24」…小数点を付け忘れた数です。１mが0.8kgなら、３mは３kgより軽いはずです。\n・「3.8」…0.8に３をたした数です。同じ重さが３こ分あるので、かけ算をします。\n・「2.8」…0.8に２をたした数です。０.８を３回たすと2.4になります。",
  "math_g5_hand_decmul_009":"毎日4.2Lを２日間使うので、4.2×２で求めます。42×２＝84で、小数点以下が１けたなので8.4です。\n\nほかの 選択肢\n・「84」…小数点を付け忘れた数です。１日に4.2Lなので、２日間で84Lにはなりません。\n・「6.2」…4.2に２をたした数です。同じ量を２日分使うので、かけ算をします。\n・「8.2」…４×２＝８に、0.2をそのままたした数です。0.2も２日分で0.4になります。",
  "math_g5_hand_decmul_010":"1.4×2.5は、14×25＝350を求め、小数点以下が２けたなので3.50＝3.5です。2.5mは２mと３mの間なので、重さは1.4×２＝2.8kgと1.4×３＝4.2kgの間になります。\n\nほかの 選択肢\n・「35」…小数点以下のけたを数えずに、350の0だけをとった数です。1.4kgの2.5倍は3.5kgです。\n・「2.8」…1.4×２の積です。長さは２mではなく2.5mなので、ちがいます。\n・「4.2」…1.4×３の積です。長さは３mではなく2.5mなので、ちがいます。",
  "math_g5_hand_decmul_011":"2.3×1.2は、23×12＝276を求めます。小数点以下は１けた＋１けたで２けたなので、2.76です。2.3の1.2倍だから、2.3より少し大きい数になります。\n\nほかの 選択肢\n・「27.6」…小数点以下を１けたしか取らなかった数です。2.3の1.2倍が27.6になることはありません。\n・「3.5」…2.3と1.2をたし算した数です。この問題はかけ算なので、ちがいます。\n・「2.66」…2.3×0.2＝0.46を使うと、2.3＋0.46＝2.76です。2.66にはなりません。",
  "math_g5_hand_decmul_012":"0.75Lのなべが４つなので、0.75×４＝3.00＝３です。75×４＝300で、小数点以下が２けたなので3.00になります。\n\nほかの 選択肢\n・「30」…小数点を付け忘れた数です。0.75Lは１Lより少ないので、４つ分で30Lにはなりません。\n・「3.75」…0.75に３をたした数です。同じ量が４つ分なので、かけ算をします。\n・「2.8」…0.75を0.7と見て、0.7×４をした数に近い数です。0.75×４＝３です。",
  "math_g5_hand_decmul_013":"畑の面積は、たて×横です。2.5×1.6は、25×16＝400を求め、小数点以下が２けたなので4.00＝４です。\n\nほかの 選択肢\n・「40」…小数点以下のけたを数えず、400の0を１つだけとった数です。2.5×1.6は、４m²です。\n・「4.1」…2.5と1.6をたし算した数です。面積はかけ算で求めます。\n・「3.5」…2.5に1.6の整数部分の１だけをたした数です。かけ算の問題なので、ちがいます。",
  "math_g5_hand_decmul_014":"0.8m²では、１m²に使う1.5kgの0.8倍のまきを使います。1.5×0.8は、15×８＝120で、小数点以下が２けたなので1.20＝1.2です。0.8m²は１m²より小さいので、まきも1.5kgより少なくなります。\n\nほかの 選択肢\n・「12」…小数点以下のけたを数えずに、120の0だけをとった数です。1.5kgより少なくなります。\n・「2.3」…1.5と0.8をたし算した数です。使う量は、かけ算で求めます。\n・「1.5」…１m²に使う量をそのまま書いた数です。0.8m²では、これより少なくなります。",
  "math_g5_hand_decmul_015":"かける数が１より小さいとき、積はかけられる数より小さくなります。3.5×0.9は、3.5の10分の９なので、3.15です。答えは「3.5より小さい」です。\n\nほかの 選択肢\n・「3.5より大きい」…かける数が１より大きいときの考え方です。\n・「3.5と同じ」…かける数が１のときの積です。\n・「3.5の10倍になる」…3.5×10の積です。10倍するのは、かける数が10のときです。",
  "math_g5_hand_decmul_016":"かける数が１より大きいとき、積はかけられる数より大きくなります。2.4×1.1は、2.4に2.4の10分の１（0.24）をたした2.64です。答えは「2.4より大きい」です。\n\nほかの 選択肢\n・「2.4より小さい」…かける数が１より小さいときの考え方です。\n・「2.4と同じ」…かける数が１のときの積です。\n・「2.4の10分の１になる」…2.4×0.1の積です。かける数は0.1ではなく1.1です。",
  "math_g5_hand_decmul_017":"0.25は4分の１と同じなので、12×0.25は12の４分の１、つまり12÷４＝３です。12×25＝300で小数点以下が２けたと考えても3.00＝３です。\n\nほかの 選択肢\n・「30」…小数点の位置を１つずらした数です。0.25は１より小さいので、積は12より小さくなります。\n・「3.25」…３に0.25をたした数です。12×0.25はかけ算なので、たし算の答えにはなりません。\n・「2.5」…12×0.2＝2.4に近い数ですが、0.25は0.2より大きいので、積は３になります。",
  "math_g5_hand_decmul_018":"ぬれる面積は、１Lの面積×Lの数です。8.5×2.4は、85×24＝2040で、小数点以下が２けたなので20.40＝20.4です。\n\nほかの 選択肢\n・「204」…小数点以下のけたを数えずに、2040の0をとった数です。8.5m²の2.4倍は約20m²です。\n・「10.9」…8.5と2.4をたし算した数です。ぬれる面積は、かけ算で求めます。\n・「19.4」…8.5×２＝17に2.4をそのままたした数です。0.4Lの分は8.5×0.4＝3.4m²です。",
  "math_g5_hand_decmul_019":"3.2×0.05は、32×５＝160を求めます。小数点以下は１けた＋２けたで３けたなので、0.160＝0.16です。\n\nほかの 選択肢\n・「1.6」…小数点以下を２けたとして、小数点を１つ右にずらした数です。0.05倍は小さくなるので、3.2より小さい数です。\n・「0.32」…3.2×0.1の積です。かける数は0.1ではなく0.05です。\n・「0.016」…小数点以下を４けたとした数です。３けたが正しいので、ちがいます。",
  "math_g5_hand_decmul_020":"1.25×８は、1.25を８回たすことです。125×８＝1000で、小数点以下が２けたなので10.00＝10です。1.25は４分の５だから、8×5÷4＝10と考えることもできます。\n\nほかの 選択肢\n・「9.25」…1.25と８をたし算した数です。この問題はかけ算なので、ちがいます。\n・「100」…位を１つずらして、10倍にした数です。1.25の８倍は、10ほどです。\n・「8」…８をそのまま書いた数です。1.25は１より大きいので、積は８より大きくなります。",
  "math_g5_hand_decmul_021":"代金は、１mのねだん×長さで求めます。125×2.4は、125×24＝3000で、2.4の小数点以下が１けたなので300です。\n\nほかの 選択肢\n・「3000」…小数点以下のけたを数えず、3000をそのまま書いた数です。２.4mなので300円ほどです。\n・「250」…125×２の積です。2.4mなので、0.4mの分の125×0.4＝50円も足します。\n・「275」…125×２＝250に、25円をたした数です。0.4mの分は125×0.4＝50円なので、250＋50＝300です。",
  "math_g5_hand_decmul_022":"正方形の面積は、１辺×１辺です。0.6×0.6は、６×６＝36を求め、小数点以下が２けたなので0.36です。\n\nほかの 選択肢\n・「3.6」…小数点以下を１けたとして、位をまちがえた数です。0.6より小さい数どうしのかけ算は、0.6より小さくなります。\n・「1.2」…0.6＋0.6をした数です。面積は、たし算ではなくかけ算で求めます。\n・「0.12」…0.6×0.2の積です。かけるのは0.6と0.6なので、ちがいます。",
  "math_g5_hand_decmul_023":"4.5×2.2は、45×22＝990を求めます。小数点以下は１けた＋１けたで２けたなので、9.90＝9.9です。\n\nほかの 選択肢\n・「99」…小数点以下のけたを数えずに、990の0をとった数です。4.5の2.2倍は約10です。\n・「6.7」…4.5と2.2をたした数です。この問題はかけ算なので、ちがいます。\n・「9.45」…4.5×2＝９に、4.5×0.2＝0.9ではなく0.45をたした数です。4.5×0.2＝0.9なので、9＋0.9＝9.9です。",
  "math_g5_hand_decmul_024":"14日間で作る水の量は、0.35×14で求めます。35×14＝490で、小数点以下が２けたなので4.90＝4.9です。\n\nほかの 選択肢\n・「49」…小数点以下のけたを数えずに、490の0をとった数です。0.35Lを14日分では、4.9Lほどです。\n・「4.2」…0.35×12の積に近い数です。日数は14日なので、ちがいます。\n・「5.4」…0.35×14＝4.9で、5.4にはなりません。0.35を15回たしても5.25です。",
  "math_g5_hand_decmul_025":"2.5×４＝10と、かけ算の順番を入れかえて先に計算すると、くふうできます。1.2×10＝12です。かける順番を変えても、積は変わりません。\n\nほかの 選択肢\n・「120」…位を１つずらして、10倍にした数です。1.2×10は12です。\n・「7.7」…1.2と2.5と４をたし算した数です。かけ算の問題なので、ちがいます。\n・「10.2」…2.5×４＝10に、1.2の0.2だけをたした数です。1.2×10＝12が正しいです。",
  "math_g5_hand_decmul_026":"直方体の体積は、たて×横×高さです。1.5×２＝３、３×0.8＝2.4m³です。0.8は１より小さいので、体積は３より小さくなります。\n\nほかの 選択肢\n・「24」…位を１つずらして、10倍にした数です。たて×横の３m²に、高さ0.8mをかけるので、３より小さくなります。\n・「4.3」…1.5と２と0.8をたし算した数です。体積はかけ算で求めます。\n・「3」…1.5×２＝３で止めてしまい、高さの0.8をかけていない数です。",
  "math_g5_hand_decmul_027":"2.5×0.4を先に計算すると、１になります。１×7.3＝7.3です。かけ算は、計算しやすい組み合わせを先に計算できます。\n\nほかの 選択肢\n・「73」…位を１つずらして、10倍にした数です。1×7.3は7.3です。\n・「10.2」…2.5と0.4と7.3をたし算した数です。かけ算の問題なので、ちがいます。\n・「8.3」…2.5×0.4＝１に7.3をたした数です。たし算ではなく、かけ算をします。",
  "math_g5_hand_decmul_028":"□×0.8＝5.6なので、□＝5.6÷0.8です。両方を10倍して56÷８＝７です。たしかめると、７×0.8＝5.6になります。\n\nほかの 選択肢\n・「0.7」…７の位を１つずらして、10分の１にした数です。0.7×0.8は0.56なので、ちがいます。\n・「4.48」…5.6×0.8をした数です。□を求めるには、逆の計算のわり算をします。\n・「4.8」…5.6から0.8をひいた数です。□×0.8の式なので、わり算で求めます。",
  "math_g5_hand_decmul_029":"3.6×□＝1.08なので、□＝1.08÷3.6です。両方を100倍して108÷360＝0.3です。たしかめると、3.6×0.3＝1.08になります。\n\nほかの 選択肢\n・「3」…0.3の位を１つずらして、10倍にした数です。3.6×３は10.8なので、ちがいます。\n・「0.03」…0.3の位を１つずらして、10分の１にした数です。3.6×0.03は0.108なので、ちがいます。\n・「0.4」…3.6×0.4＝1.44なので、1.08になりません。",
  "math_g5_hand_decmul_030":"1.5kgのパイプ１mのうち、0.6mの重さなので、1.5×0.6で求めます。15×６＝90で、小数点以下が２けたなので0.90＝0.9です。0.6mは１mより短いので、1.5kgより軽くなります。\n\nほかの 選択肢\n・「9」…小数点以下のけたを数えずに、90をそのまま書いた数です。0.6mは１mより短いので、1.5kgより軽くなります。\n・「2.1」…1.5と0.6をたし算した数です。重さは、かけ算で求めます。\n・「0.6」…切った長さの0.6をそのまま書いた数です。聞かれているのは重さです。",
  "math_g5_hand_decmul_031":"道のりは、速さ×時間で求めます。4.5×1.5は、45×15＝675で、小数点以下が２けたなので6.75kmです。4.5×１＝4.5と、4.5×0.5＝2.25をたしても、6.75になります。\n\nほかの 選択肢\n・「6.05」…4.5×0.5の2.25を、1.55と計算まちがいした数に近いです。4.5＋2.25＝6.75です。\n・「6.57」…6.75の数字の順番を入れかえた数です。45×15＝675から、6.75になります。\n・「7.25」…4.5＋2.75をした数です。4.5×0.5は2.25なので、4.5＋2.25＝6.75です。",
  "math_g5_hand_decmul_032":"0.25×４＝１を先に計算するとくふうできます。１×0.4＝0.4です。かけ算は、順番を入れかえても積が変わりません。\n\nほかの 選択肢\n・「4」…位を１つずらして、10倍にした数です。１×0.4＝0.4です。\n・「0.1」…位を１つずらして、10分の１にした数です。１×0.4＝0.4です。\n・「1」…0.25×４＝１で止めてしまい、0.4をかけていない数です。",
  "math_g5_hand_decmul_033":"3.6を４×0.9と見て、2.5×４を先に計算すると10になります。10×0.9＝９です。2.5×3.6を直接計算しても、９になります。\n\nほかの 選択肢\n・「10」…（2.5×４）まで計算して、0.9をかけていない数です。\n・「90」…位を１つずらして、10倍にした数です。10×0.9は９です。\n・「6.1」…2.5と3.6をたし算した数です。かけ算の問題なので、ちがいます。",
  "math_g5_hand_decmul_034":"0.9×0.9＝0.81、0.81×0.9＝0.729です。小数点以下は１けた＋１けた＋１けたで３けたなので、0.729になります。0.9は１より小さいので、かけるたびに小さくなります。\n\nほかの 選択肢\n・「0.81」…0.9を２回かけたところで止めた数です。0.9を３回かけるので、ちがいます。\n・「0.27」…0.9×３＝2.7を使った数です。0.9を３回かけるのと、３倍するのはちがいます。\n・「7.29」…729の小数点を右へずらしすぎた数です。小数点以下は３けたなので0.729です。0.9は１より小さいので、積も１より小さくなります。",
  "math_g5_hand_decmul_035":"のこりの面積は、畑全体の面積から、のぞいた場所の面積をひきます。全体は 3.2×2.5＝８m²、のぞく場所は 1×0.5＝0.5m²。８－0.5＝7.5m²です。\n\nほかの 選択肢\n・「8」…全体の面積だけを答えた数です。のぞいた部分の0.5m²をひいていません。\n・「8.5」…８に、のぞいた0.5m²をたした数です。のぞくときは、ひき算をします。\n・「7.2」…のぞいた部分を0.8m²として、８から0.8をひいた数です。のぞく場所は1×0.5＝0.5m²です。",
  "math_g5_hand_decmul_036":"正方形の面積は、１辺×１辺です。1.2×1.2は、12×12＝144で、小数点以下が２けたなので1.44です。\n\nほかの 選択肢\n・「4.8」…1.2×４の積です。まわりの長さを求める式で、面積ではありません。\n・「14.4」…小数点以下のけたを数えずに、位をずらした数です。1.2の1.2倍は約1.4です。\n・「2.4」…1.2×２の積です。かけるのは２ではなく1.2です。",
  "math_g5_hand_fracrel_001":"わり算の商は、わられる数を分子、わる数を分母にして分数で表せます。３÷４は、３を４等分した１つ分の３つ分で、3/4です。\n\nほかの 選択肢\n・「4/3」…わられる数と、わる数を入れかえた分数です。３÷４なので、分子が３、分母が４です。\n・「3/7」…分子と分母をたした数を分母にした分数です。わり算の商は、たし算では表しません。\n・「1/12」…分子と分母をかけた数を分母にした分数です。３÷４の商は、3/4です。",
  "math_g5_hand_fracrel_002":"分数は、分子÷分母の商です。1/2は１÷２なので、0.5です。0.1が５こ分、と考えることもできます。\n\nほかの 選択肢\n・「0.2」…分母の２を小数第１位に書いた数です。1/2は１÷２で、0.5です。\n・「0.25」…1/4を小数にした数です。1/2と1/4は、分母がちがうので別の数です。\n・「1.2」…「１」と「２」をならべて書いた数です。1.2は１より大きいですが、1/2は１より小さいので、ちがいます。",
  "math_g5_hand_fracrel_003":"0.3は、0.1が３こ分です。0.1は1/10なので、0.3は3/10です。小数第１位までの数は、分母が10の分数になります。\n\nほかの 選択肢\n・「3/100」…0.03を分数にした数です。0.3は小数第１位までの数なので、分母は100ではなく10です。\n・「1/3」…3をそのまま分母に置いた分数です。0.3は３分の１ではなく、10分の３です。\n・「30/10」…3/10＝0.3なので、30/10は3になってしまいます。分子の30は多すぎます。",
  "math_g5_hand_fracrel_004":"約分は、分子と分母を同じ数でわって、かんたんな分数にすることです。6/8は、分子も分母も２でわれるので、3/4になります。\n\nほかの 選択肢\n・「2/4」…分子と分母を、ちがう数でわった分数です。約分は、同じ数でわります。\n・「6/4」…分母だけを２でわった分数です。分子も同じ数でわらないと、大きさが変わってしまいます。\n・「1/2」…6/8を、分母が２、分子が１のようにわりすぎた分数です。1/2＝4/8なので、6/8とは大きさがちがいます。",
  "math_g5_hand_fracrel_005":"通分は、分母を同じにすることです。２と３の最小公倍数は６なので、1/2＝3/6、1/3＝2/6と、分母を６にそろえます。答えは「3/6と2/6」です。\n\nほかの 選択肢\n・「2/4と2/6」…分母がそろっていません。2/4と2/6では、通分したことになりません。\n・「1/6と1/6」…1/2と1/3の分子を、そのまま1/6にした分数です。大きさが変わってしまいます。\n・「2/6と3/6」…分子がちがう順番にならんだ分数です。1/2は3/6、1/3は2/6なので、順番がぎゃくです。",
  "math_g5_hand_fracrel_006":"５÷３の商は、分子を５、分母を３として、5/3と表せます。わられる数が分子、わる数が分母です。5/3は１より大きい分数です。\n\nほかの 選択肢\n・「3/5」…分子と分母を入れかえた分数です。５÷３は、５が分子で３が分母です。\n・「１と1/5」…5/3は１と2/3と同じ大きさです。１と1/5は、大きさがちがいます。\n・「2/3」…５÷３のあまりの２を使って、5-3＝2を分子にした分数です。商は5/3です。",
  "math_g5_hand_fracrel_007":"3/5は、３÷５の商です。３÷５＝0.6なので、3/5＝0.6です。0.1が６こ分と考えることもできます。\n\nほかの 選択肢\n・「0.35」…「３」と「５」をならべて書いた数です。0.35は35/100で、3/5とは大きさがちがいます。\n・「1.5」…3/5は１より小さいので、1.5のような１より大きい数にはなりません。\n・「0.53」…「５」と「３」をならべて書いた数です。0.53は53/100で、3/5とは大きさがちがいます。",
  "math_g5_hand_fracrel_008":"0.75は0.01が75こ分なので、75/100です。分子と分母を25でわって、約分すると3/4になります。\n\nほかの 選択肢\n・「7/5」…７と５をならべて書いた分数です。0.75は75/100であり、7/5ではありません。\n・「75/10」…75/10は7.5と同じ大きさです。0.75の分母は、10ではなく100です。\n・「3/5」…3/5は0.6と同じです。0.75とは大きさがちがうので、ちがいます。",
  "math_g5_hand_fracrel_009":"12と18の最大公約数は６です。分子と分母を６でわると、2/3になります。大きさが変わらず、もっともかんたんな分数になります。\n\nほかの 選択肢\n・「3/2」…分子と分母を入れかえた分数です。約分では、分子と分母は入れかわりません。\n・「1/2」…12/18＝0.666…で、1/2＝0.5とは大きさがちがいます。約分は同じ数でわります。\n・「1/3」…12/18は、18のうちの12です。1/3は18のうちの６なので、半分の大きさです。",
  "math_g5_hand_fracrel_010":"分母のちがう分数は、通分すると大きさをくらべられます。３と４の最小公倍数の12にそろえると、2/3＝8/12、3/4＝9/12です。9/12のほうが大きいので、3/4です。\n\nほかの 選択肢\n・「2/3」…通分すると8/12で、3/4の9/12より小さい分数です。\n・「同じ大きさ」…通分すると8/12と9/12になって、大きさがちがいます。\n・「比べられない」…分母がちがう分数も、通分すれば大きさをくらべられます。",
  "math_g5_hand_fracrel_011":"1.5は、１と0.5です。0.5は5/10＝1/2なので、1.5＝１と1/2です。\n\nほかの 選択肢\n・「１と1/5」…0.5の５を分母にした帯分数です。0.5は5/10＝1/2なので、1/5ではありません。\n・「２と1/2」…２と1/2は2.5です。整数部分が１ではなく２になっているので、ちがいます。\n・「3/5」…3/5は0.6です。1.5は１より大きい数なので、真分数にはなりません。",
  "math_g5_hand_fracrel_012":"７÷４＝１あまり３なので、7/4は、整数が１、分数が3/4の帯分数になります。1/4が７こ分で、1と3/4です。答えは「１と3/4」です。\n\nほかの 選択肢\n・「１と1/4」…1と1/4は5/4です。7/4とは大きさがちがいます。\n・「２と3/4」…２と3/4は11/4です。7/4とは大きさがちがいます。\n・「１と7/4」…帯分数の分数部分は、１より小さくなければなりません。7/4は分子が分母より大きいので、書き方がまちがいです。",
  "math_g5_hand_fracrel_013":"3/4を小数にすると、３÷４＝0.75です。0.8と0.75をくらべると、0.8のほうが大きいので、0.8mのほうが長いです。\n\nほかの 選択肢\n・「3/4m」…3/4mは0.75mで、0.8mより短いです。大小がぎゃくになっています。\n・「同じ長さ」…0.75mと0.8mは、同じ長さではありません。0.05mのちがいがあります。\n・「比べられない」…分数と小数も、どちらかにそろえれば大きさをくらべられます。",
  "math_g5_hand_fracrel_014":"２Lを３人で等しく分けるので、２÷３です。わり算の商は分数で表せて、2/3になります。答えは2/3Lです。\n\nほかの 選択肢\n・「3/2L」…分子と分母が入れかわった分数です。３人で分けるので、３が分母です。\n・「0.6L」…２÷３は0.666…と、わりきれません。0.6だと３人分で1.8Lになり、２Lになりません。\n・「2/5L」…２と３をたした数を分母にした分数です。わり算の商は、たし算では表しません。",
  "math_g5_hand_fracrel_015":"分子と分母を同じ数でわると、大きさが同じ分数になります。4/6を２でわって、2/3です。\n\nほかの 選択肢\n・「4/3」…分子の４はそのままで、分母だけ６を３にした分数です。分子も分母も同じ数でわらないと、大きさが変わります。\n・「3/2」…3/2は、分子と分母が入れかわった分数です。4/6は１より小さいですが、3/2は１より大きいです。\n・「6/4」…6/4は、分子と分母が入れかわった分数で、1より大きいです。4/6は１より小さいので、ちがいます。",
  "math_g5_hand_fracrel_016":"18と24の最大公約数は６です。分子と分母を６でわると、3/4になります。\n\nほかの 選択肢\n・「2/3」…2/3は0.666…で、18/24＝0.75とは大きさがちがいます。\n・「1/2」…1/2は0.5で、18/24＝0.75とは大きさがちがいます。\n・「4/3」…分子と分母が入れかわった分数です。18/24は１より小さいので、4/3のように１より大きくはなりません。",
  "math_g5_hand_fracrel_017":"5/8は、５÷８の商です。５÷８＝0.625なので、5/8＝0.625です。\n\nほかの 選択肢\n・「0.58」…「５」と「８」をならべて書いた数です。5/8は、５÷８を計算して求めます。\n・「1.6」…８÷５＝1.6の商です。分子と分母を入れかえてしまった数です。\n・「0.85」…「８」と「５」をならべて書いた数です。5/8は５÷８を計算します。",
  "math_g5_hand_fracrel_018":"0.45は0.01が45こ分なので、45/100です。分子と分母を５でわって、9/20になります。\n\nほかの 選択肢\n・「45/10」…45/10は4.5です。0.45の分母は10ではなく100です。\n・「9/10」…9/10は0.9です。0.45とは大きさがちがいます。\n・「4/5」…4/5は0.8です。0.45とは大きさがちがいます。",
  "math_g5_hand_fracrel_019":"小数にそろえてくらべます。3/4＝0.75、2/3＝0.666…、0.7です。0.75＞0.7＞0.666…なので、いちばん大きいのは3/4です。\n\nほかの 選択肢\n・「0.7」…0.7は0.75より小さいので、いちばん大きくはありません。\n・「2/3」…2/3は0.666…で、0.75より小さいので、いちばん大きくはありません。\n・「全部同じ」…3/4＝0.75、0.7、2/3＝0.666…と、大きさがちがうので、全部同じではありません。",
  "math_g5_hand_fracrel_020":"２と3/8の小数は、整数部分の２に、3/8を小数にした数をたします。３÷８＝0.375なので、２と3/8＝2.375です。\n\nほかの 選択肢\n・「2.38」…3/8＝0.375を、四捨五入して2.38にした数です。ぴったりの値は2.375です。\n・「2.83」…整数の２のあとに、８、３の順にならべた数です。3/8は0.375で、0.83ではありません。\n・「2.3」…3/8を0.3と考えた数です。３÷８＝0.375なので、2.3ではありません。",
  "math_g5_hand_fracrel_021":"７÷８の商は、わり算の筆算で0.875です。7/8と同じ大きさです。\n\nほかの 選択肢\n・「0.78」…「７」と「８」をならべて書いた数です。７÷８を計算すると0.875です。\n・「8.75」…小数点の位置がちがう数です。７÷８は１より小さい数です。\n・「1.14」…８÷７の商です。わる数とわられる数を入れかえてしまったときの数です。",
  "math_g5_hand_fracrel_022":"1/3＝4/12、1/2＝6/12です。この間にある分母12の分数は、5/12だけです。\n\nほかの 選択肢\n・「3/12」…3/12は1/3の4/12より小さいので、間にはありません。\n・「7/12」…7/12は1/2の6/12より大きいので、間にはありません。\n・「4/12」…4/12は1/3と同じ大きさです。「より大きい」数ではありません。",
  "math_g5_hand_fraction_001":"1/2と1/3を通分して分母を６にそろえると、3/6と2/6です。分子どうしをたして、3/6＋2/6＝5/6です。\n\nほかの 選択肢\n・「2/5」…分母どうし、分子どうしをたした分数です。通分してから分子だけをたします。\n・「2/6」…通分したあと、分子の２だけを答えた分数です。3/6との和を忘れています。\n・「1/6」…1/2－1/3の差の1/6です。この問題はたし算なので、ちがいます。",
  "math_g5_hand_fraction_002":"通分して、1/2＝3/6、1/3＝2/6にします。分子どうしをひいて、3/6－2/6＝1/6です。\n\nほかの 選択肢\n・「0」…0になるのは、同じ大きさの数どうしをひいたときです。1/2と1/3は大きさがちがいます。\n・「1/5」…分母どうしをたして５にした分数です。通分して計算します。\n・「2/6」…通分したあと、ひく分子を１と取りちがえた分数です。3/6－2/6の分子は３－２＝１です。",
  "math_g5_hand_fraction_003":"1/2を分母が４の分数にすると2/4です。1/4＋2/4＝3/4です。\n\nほかの 選択肢\n・「2/6」…分母どうし、分子どうしをたして2/6にした分数です。分母は変わりません。\n・「2/4」…1/4＋1/4の答えです。1/2は2/4なので、1/4＋2/4＝3/4です。\n・「1/6」…分母をたした数を分母にした分数です。分母は、通分したら変わりません。",
  "math_g5_hand_fraction_004":"2/3を分母が６の分数にすると4/6です。4/6－1/6＝3/6で、約分すると1/2になります。\n\nほかの 選択肢\n・「1/3」…3/6を約分するときのまちがいに近い数です。3/6は1/2であり、1/3ではありません。\n・「1/6」…4/6から3/6をひいてしまったときの数です。1/6をひくので、答えは3/6です。\n・「5/6」…4/6＋1/6のたし算の答えです。この問題はひき算なので、ちがいます。",
  "math_g5_hand_fraction_005":"1/3を分母が６の分数にすると2/6です。2/6＋1/6＝3/6で、約分すると1/2になります。\n\nほかの 選択肢\n・「2/9」…分母どうし、分子どうしをたして2/9にした分数です。分母は変わりません。\n・「2/6」…通分したあと、1/6をたさずに2/6のままにした分数です。\n・「1/9」…分母をたした9を分母にした分数です。分母は、通分したら変わりません。",
  "math_g5_hand_fraction_006":"1/2を分母が４の分数にすると2/4です。3/4－2/4＝1/4です。\n\nほかの 選択肢\n・「2/2」…分母どうし、分子どうしをそれぞれひいた分数です。分母は変わりません。\n・「2/4」…通分せず、分子の３から１をひいた分数です。1/2は2/4なので、ひく分子は２です。\n・「1/2」…ひく数の1/2をそのまま答えにした分数です。3/4から1/2をひくので、答えは1/4です。",
  "math_g5_hand_fraction_007":"通分するときの分母は、２と３の公倍数です。いちばん小さい公倍数は６です。1/2＝3/6、1/3＝2/6になります。\n\nほかの 選択肢\n・「2」…２は２の倍数ですが、３の倍数ではありません。3ではわりきれません。\n・「3」…３は３の倍数ですが、２の倍数ではありません。2ではわりきれません。\n・「5」…５は２でも３でもわりきれないので、共通の分母にはできません。",
  "math_g5_hand_fraction_008":"1/5を分母が10の分数にすると2/10です。2/10＋1/10＝3/10です。\n\nほかの 選択肢\n・「2/15」…分母どうし、分子どうしをたして2/15にした分数です。分母は変わりません。\n・「2/10」…通分したあと、1/10のたし算を忘れた数です。2/10は、1/5と同じです。\n・「1/5」…もとの1/5をそのまま書いた数です。3/10と1/5＝2/10は大きさがちがいます。",
  "math_g5_hand_fraction_009":"通分して、2/3＝8/12、1/4＝3/12にします。8/12＋3/12＝11/12です。\n\nほかの 選択肢\n・「3/7」…分母どうし、分子どうしをたして3/7にした分数です。通分してから分子だけをたします。\n・「3/12」…通分したあと、1/4の3/12だけを答えにした数です。\n・「5/12」…通分したあとの分子を、ひいて5/12にした分数です。この問題はたし算です。",
  "math_g5_hand_fraction_010":"通分して、3/4＝9/12、2/3＝8/12にします。9/12＋8/12＝17/12。17/12は１と5/12なので、答えは１と5/12です。\n\nほかの 選択肢\n・「5/7」…分母どうし、分子どうしをたして5/7にした分数です。通分してから分子だけをたします。\n・「5/12」…17/12の分数部分だけ書いて、整数の１を書き忘れた分数です。\n・「１と1/12」…17/12を帯分数に直すとき、あまりをまちがえた数です。17÷12＝１あまり５なので、1と5/12です。",
  "math_g5_hand_fraction_011":"通分して、5/6＝10/12、3/4＝9/12にします。10/12－9/12＝1/12です。\n\nほかの 選択肢\n・「2/2」…分母どうし、分子どうしをそれぞれひいた分数です。分母は変わりません。\n・「2/12」…3/4を8/12とまちがえて通分した数です。3/4は9/12です。\n・「1/6」…2/12は1/6と同じ大きさです。通分したあとの差は、10/12－9/12＝1/12です。",
  "math_g5_hand_fraction_012":"分数部分を通分して、1/2＝3/6、2/3＝4/6にします。3/6＋4/6＝7/6＝１と1/6なので、整数と合わせて、１＋１と1/6＝２と1/6です。\n\nほかの 選択肢\n・「１と3/5」…分母どうし、分子どうしをたして3/5にした数に近い数です。通分してから分子だけをたします。\n・「２と1/5」…7/6の分数部分を、分母が５の分数としてしまった数です。7÷６＝１あまり１なので、1/6です。\n・「１と1/6」…くり上がった１を整数にたし忘れた数です。7/6＝１と1/6なので、整数部分は１＋１＝２です。",
  "math_g5_hand_fraction_013":"分数部分を通分して、1/3＝4/12、1/4＝3/12にします。２と4/12－１と3/12は、整数部分が２－１＝１、分数部分が4/12－3/12＝1/12なので、１と1/12です。\n\nほかの 選択肢\n・「１と1/3」…分数部分を、通分せずに1/3のままにした数です。通分してから4/12－3/12を計算します。\n・「１と2/12」…分数部分の分子を、４－２で2とまちがえた数です。1と2/12は1と1/6です。\n・「１と7/12」…分数部分の分子を、４＋３でたしてしまった数です。この問題はひき算です。",
  "math_g5_hand_fraction_014":"2/5を分母が10の分数にすると4/10です。3/10＋4/10＝7/10です。\n\nほかの 選択肢\n・「5/15」…分母どうし、分子どうしをたして5/15にした分数です。分母は変わりません。\n・「5/10」…通分せず、分子の３と２をたして5/10にした分数です。2/5は4/10なので、分子は４です。\n・「1/2」…5/10を約分した数です。通分が正しくないので、答えがちがいます。",
  "math_g5_hand_fraction_015":"通分して、2/3＝8/12、1/4＝3/12にします。8/12＋3/12＝11/12Lです。\n\nほかの 選択肢\n・「3/7L」…分母どうし、分子どうしをたして3/7にした分数です。通分してから分子だけをたします。\n・「3/12L」…なべに入っている1/4Lだけの量です。バケツの分もたします。\n・「5/12L」…通分したあとの分子をひいて5/12にした分数です。「合わせて」はたし算です。",
  "math_g5_hand_fraction_016":"通分して、1/2＝5/10、1/5＝2/10にします。のこりは使った分をひくので、5/10－2/10＝3/10Lです。\n\nほかの 選択肢\n・「1/3L」…分母どうしをひいて、1/3にした分数です。通分してから分子をひきます。\n・「2/7L」…分母を２＋５＝７にしてしまった分数です。通分して分母を10にそろえて計算します。\n・「1/10L」…通分したあと、ひく分子を４にして5/10－4/10としてしまった数です。ひくのは2/10です。",
  "math_g5_hand_fraction_017":"通分して、5/6＝25/30、7/10＝21/30にします。25/30＋21/30＝46/30。46/30を２で約分すると23/15で、帯分数で１と8/15です。\n\nほかの 選択肢\n・「12/16」…分母どうし、分子どうしをたして12/16にした分数です。通分してから分子だけをたします。\n・「１と1/15」…23/15を帯分数に直すとき、あまりを１とまちがえた数です。23÷15＝１あまり８なので、1と8/15です。\n・「１と4/15」…46/30を約分するときにまちがえた数です。46/30は、２でわって23/15＝1と8/15です。",
  "math_g5_hand_fraction_018":"1/3を分母が６の分数にすると2/6です。1/6＋2/6＝3/6で、約分すると1/2です。\n\nほかの 選択肢\n・「2/9」…分母どうし、分子どうしをたして2/9にした分数です。通分してから分子だけをたします。\n・「2/6」…約分する前の3/6ではなく、2/6になっています。分子は１＋２＝３です。\n・「1/9」…分母をたした9を分母にした分数です。分母は変わりません。",
  "math_g5_hand_fraction_019":"通分して、3/4＝9/12、1/6＝2/12にします。9/12＋2/12＝11/12です。\n\nほかの 選択肢\n・「4/10」…分母どうし、分子どうしをたして4/10にした分数です。通分してから分子だけをたします。\n・「4/6」…分母をそろえないまま分子だけをたして4/6にした分数です。通分が必要です。\n・「5/12」…3/4を3/12とまちがえて通分した数です。3/4は9/12です。",
  "math_g5_hand_fraction_020":"分数部分を通分して、2/5＝4/10にします。１と4/10＋3/10＝１と7/10です。\n\nほかの 選択肢\n・「１と5/15」…分母どうし、分子どうしをたして１と5/15にした分数です。通分してから分子だけをたします。\n・「１と1/2」…通分せずに分子どうしをたして、1と5/10＝1と1/2にした数です。2/5は4/10です。\n・「２と1/10」…整数部分を２にしてしまった数です。",
  "math_g5_hand_fraction_021":"３から1/4をひくときは、３を２と4/4に直して、くり下げます。２と4/4－1/4＝２と3/4です。\n\nほかの 選択肢\n・「２と1/4」…分数部分を4/4－1/4でなく、1/4としてしまった数です。4/4－1/4は3/4です。\n・「３と1/4」…３に1/4をたした数です。この問題はひき算です。\n・「2/4」…整数と分子をそのままひいて2/4にしてしまった数です。くり下げを使います。",
  "math_g5_hand_fraction_022":"通分して、2/3＝10/15、3/5＝9/15にします。10/15＋9/15＝19/15。19/15は１と4/15です。\n\nほかの 選択肢\n・「5/8」…分母どうし、分子どうしをたして5/8にした分数です。通分してから分子だけをたします。\n・「１と1/15」…19/15を帯分数に直すとき、あまりを１とまちがえた数です。19÷15＝１あまり４なので、1と4/15です。\n・「１と9/15」…3/5の9/15を、分数部分に使ってしまった数です。2/3の分もたします。",
  "math_g5_hand_fraction_023":"1/4を分母が８の分数にすると2/8です。7/8－2/8＝5/8です。\n\nほかの 選択肢\n・「6/4」…分母どうし、分子どうしをひいて6/4にした分数です。分母は変わりません。\n・「6/8」…通分せずに分子の７から１をひいて6/8にした分数です。1/4は2/8です。\n・「3/4」…6/8を約分した数です。もとの6/8がまちがっているので、答えもちがいます。",
  "math_g5_hand_fraction_024":"分母を６にそろえて、1/2＝3/6、1/3＝2/6にします。3/6＋2/6＋1/6＝6/6＝１です。\n\nほかの 選択肢\n・「3/11」…分母どうし、分子どうしをたして3/11にした分数です。通分してから分子だけをたします。\n・「1/2」…最初の1/2だけを答えにした数です。３つの分数をたします。\n・「2/3」…1/2＋1/6＝4/6＝2/3で止めてしまった数です。1/3の分もたします。",
  "math_g5_hand_fraction_025":"分母を12にそろえて、3/4＝9/12、1/3＝4/12、1/6＝2/12にします。左から順に、9/12－4/12＝5/12、5/12＋2/12＝7/12です。\n\nほかの 選択肢\n・「3/7」…分母どうし、分子どうしをたして3/7にした分数です。通分してから分子だけを計算します。\n・「5/12」…9/12－4/12＝5/12で止めてしまった数です。最後に2/12をたします。\n・「1/2」…5/12に1/12をたした数です。たすのは1/6＝2/12なので、7/12です。",
  "math_g5_hand_fraction_026":"２と2/12－１と9/12は、2/12から9/12がひけないので、２と2/12を１と14/12に直します。14/12－9/12＝5/12、整数部分は１－１＝０なので、答えは5/12です。\n\nほかの 選択肢\n・「１と5/12」…くり下げたあとに、整数部分の１がのこった数です。１－１＝０なので、整数部分はなくなります。\n・「１と1/12」…くり下げたあとの14/12－9/12を、1/12と計算まちがいした数です。14－９は５です。\n・「7/12」…大きいほうの分数から小さいほうの分数をひいてしまった数です。2/12は9/12より小さいので、くり下げが必要です。",
  "math_g5_hand_fraction_027":"のこりは、１から使った分をひきます。使った分は 1/3＋1/4＝4/12＋3/12＝7/12。１－7/12＝12/12－7/12＝5/12mです。\n\nほかの 選択肢\n・「7/12m」…切り取った長さの合計7/12mです。のこりを聞かれているので、１からひきます。\n・「5/7m」…分母を３＋４＝７にしてしまった分数です。通分して分母を12にそろえて計算します。\n・「2/7m」…分母を３＋４＝７にして、分子を３－１のようにしたような分数です。通分して計算します。",
  "math_g5_hand_fraction_028":"□＝5/6－1/3です。1/3を分母が６の分数にして2/6です。5/6－2/6＝3/6＝1/2です。たしかめると、1/2＋1/3＝3/6＋2/6＝5/6です。\n\nほかの 選択肢\n・「1/6」…5/6－4/6のように、ひく数をまちがえると出る数です。ひくのは1/3＝2/6です。\n・「1/3」…問題文のたされる数をそのまま答えにした分数です。□は求める数です。\n・「7/6」…5/6に1/3をたした数です。□を求めるには、ひき算をします。",
  "math_g5_hand_fraction_029":"□＝1/10＋2/5です。2/5を分母が10の分数にして4/10。1/10＋4/10＝5/10＝1/2です。たしかめると、1/2－2/5＝5/10－4/10＝1/10です。\n\nほかの 選択肢\n・「3/10」…4/10－1/10のひき算です。□を求めるには、たし算をします。\n・「3/5」…2/5を5/10としてしまった数に近い数です。2/5は4/10です。\n・「1/4」…1/4は2.5/10と同じなので、1/10＋2/5の答えにはなりません。",
  "math_g5_hand_fraction_030":"通分して、2/3＝8/12、3/4＝9/12です。9/12－8/12＝1/12なので、Ｂのほうが1/12L多いです。答えは「Ｂが1/12L多い」です。\n\nほかの 選択肢\n・「Ａが1/12L多い」…大小がぎゃくになっています。3/4のほうが2/3より大きいです。\n・「Ｂが1/6L多い」…1/6は2/12と同じです。差は9/12－8/12＝1/12です。\n・「Ａが1/6L多い」…大小がぎゃくで、差も2/12になっています。差は1/12です。",
  "math_g5_hand_fraction_031":"２日間でやった分は、1/3＋1/4＝4/12＋3/12＝7/12です。のこりは全体１から、１－7/12＝5/12です。\n\nほかの 選択肢\n・「7/12」…２日間にやった分です。のこりを聞かれているので、１からひきます。\n・「2/7」…分母どうし、分子どうしをたしひきした分数です。通分して計算します。\n・「1/12」…1/3－1/4の差です。のこりは、１から２日分をひいて求めます。",
  "math_g5_hand_fraction_032":"通分して、1/6＝5/30、1/10＝3/30にします。5/30＋3/30＝8/30、約分して4/15です。\n\nほかの 選択肢\n・「2/16」…分母どうし、分子どうしをたして2/16にした分数です。通分してから分子だけをたします。\n・「2/60」…分母どうしをかけた60を分母にして、分子をたした分数です。通分では、最小公倍数を使います。\n・「1/15」…8/30の分子と分母を８でわった形です。30は８でわりきれません。２でわると、4/15です。",
  "math_g5_hand_fraction_033":"整数どうしは４＋２＝６、分数どうしは1/5＋3/10。1/5＝2/10なので、2/10＋3/10＝5/10＝1/2です。合わせて、６と1/2です。\n\nほかの 選択肢\n・「６と4/15」…分母どうし、分子どうしをたして4/15にした数です。通分してから分子だけをたします。\n・「６と4/10」…分数部分を、約分せずに4/10にした数です。1/5＝2/10なので、2/10＋3/10＝5/10です。\n・「７と1/2」…整数部分を７にしてしまった数です。分数部分は5/10で１にならないので、くり上がりません。",
  "math_g5_hand_fraction_034":"1と1/4を分母が12にして、5/6＝10/12、１と3/12にします。10/12＋3/12＝13/12＝１と1/12。１＋１と1/12＝２と1/12です。\n\nほかの 選択肢\n・「１と6/10」…分母どうしをたして、１と6/10にした数です。通分してから分子だけをたします。\n・「２と5/12」…分数部分の13/12を、くり上がりを考えずに5/12とした数に近い数です。13/12は１と1/12です。\n・「２と1/6」…1/12を2/12としてしまった数です。13/12＝１と1/12です。",
  "math_g5_hand_fraction_035":"分母を12にそろえて、1/2＝6/12、1/3＝4/12、1/4＝3/12にします。6/12＋4/12＋3/12＝13/12＝１と1/12kmです。\n\nほかの 選択肢\n・「3/9km」…分母どうし、分子どうしをたして3/9にした分数です。通分してから分子だけをたします。\n・「13/24km」…分母を24にそろえてしまった数です。12の方が、最小公倍数なのでかんたんです。\n・「１と1/9km」…13/12を帯分数に直すとき、分母を９としてしまった数です。13÷12＝１あまり１なので、1と1/12です。",
  "math_g5_hand_graph_001":"全体を長方形の帯にして、それぞれの部分の割合を、長さで表したグラフが帯グラフです。いくつかの帯グラフをならべると、割合の変わり方もくらべられます。\n\nほかの 選択肢\n・「円グラフ」…円グラフは、全体を円で表し、割合をおうぎ形の大きさで表すグラフです。\n・「折れ線グラフ」…折れ線グラフは、時間とともに変わる数を、点をつないだ線で表すグラフです。\n・「ぼうグラフ」…ぼうグラフは、数の大きさを、ぼうの長さで表すグラフです。",
  "math_g5_hand_graph_002":"全体を円にして、部分の割合をおうぎ形の大きさで表したグラフが円グラフです。円の中心の角の大きさが、割合を表します。\n\nほかの 選択肢\n・「帯グラフ」…帯グラフは、全体を長方形の帯にして、割合を長さで表すグラフです。\n・「折れ線グラフ」…折れ線グラフは、時間とともに変わる数を、点をつないだ線で表すグラフです。\n・「ぼうグラフ」…ぼうグラフは、数の大きさを、ぼうの長さで表すグラフです。",
  "math_g5_hand_graph_003":"帯グラフや円グラフは、全体を100％として、その部分を表します。部分の割合を全部たすと、もとの全体の100％になります。\n\nほかの 選択肢\n・「50」…50％は全体の半分です。全部の合計は半分ではなく、全体そのものです。\n・「90」…90％では、全体が10％足りません。部分を全部合わせると、全体になります。\n・「200」…200％は全体の２倍です。部分の合計が全体より大きくなることはありません。",
  "math_g5_hand_graph_004":"全体は100％なので、のこりは100から他の割合の合計をひいて求めます。木材と鉄の合計は40＋35＝75％。100－75＝25％です。\n\nほかの 選択肢\n・「75」…木材と鉄の割合を合わせた75％です。石は、100％からその合計をひいたのこりです。\n・「35」…鉄の割合の35％です。石の割合を聞かれています。\n・「15」…100－75＝25なので、15％ではありません。15％だと合計が90％になって、100％にたりません。",
  "math_g5_hand_graph_005":"円全体が100％です。４分の１は、100÷４＝25％になります。円グラフの中心の角では、360°の４分の１の90°です。\n\nほかの 選択肢\n・「50」…50％は円全体の半分で、半円にあたります。\n・「75」…75％は円全体の４分の３です。４分の１は25％です。\n・「20」…20％は円全体の５分の１です。４分の１ではありません。",
  "math_g5_hand_graph_006":"半円は円全体の半分なので、100％の半分の50％です。中心の角では、360°の半分の180°です。\n\nほかの 選択肢\n・「25」…25％は円全体の４分の１で、半円の半分です。\n・「75」…75％は円全体の４分の３です。半円は、半分です。\n・「100」…100％は円全体です。半円は半分なので、ちがいます。",
  "math_g5_hand_graph_007":"町の人口の200人の30％なので、200×0.3＝60人です。30％は0.3、つまり10分の３と同じです。\n\nほかの 選択肢\n・「30」…30％という割合の数字を、そのまま人数にした数です。人数は、200人の30％で求めます。\n・「170」…200人から30人をひいた数です。30％は30人ではなく、200×0.3＝60人です。\n・「140」…スキーが好きでない70％の人数200×0.7＝140人です。好きな人は30％です。",
  "math_g5_hand_graph_008":"クラス全体の40人の25％なので、40×0.25＝10人です。25％は4分の１と同じなので、40÷４＝10と考えることもできます。\n\nほかの 選択肢\n・「25」…25％の数字を、そのまま人数にした数です。人数は、40人の25％で求めます。\n・「15」…40人から25人をひいた数です。25％は25人ではなく、40×0.25＝10人です。\n・「20」…40人の半分の20人です。半分は50％で、25％ではありません。",
  "math_g5_hand_graph_009":"木材は全体の400この45％なので、400×0.45＝180こです。45％は0.45です。\n\nほかの 選択肢\n・「220」…木材以外のこ数、400－180＝220こです。木材は45％です。\n・「200」…400この半分の200こです。半分は50％で、45％ではありません。\n・「150」…400この150こは37.5％で、45％ではありません。",
  "math_g5_hand_graph_010":"割合は、くらべる量÷もとにする量です。理科の本50さつ÷全体250さつ＝0.2。0.2は20％です。\n\nほかの 選択肢\n・「5」…250÷50＝５の５です。わる数とわられる数を入れかえてしまった数です。\n・「50」…50という、さつ数をそのまま％にした数です。割合は、50÷250で求めます。\n・「200」…200は250－50の、理科以外の本のさつ数です。割合ではありません。",
  "math_g5_hand_graph_011":"500人の12％なので、500×0.12＝60人です。12％は0.12です。\n\nほかの 選択肢\n・「12」…12％という割合の数字を、そのまま人数にした数です。人数は、500人の12％で求めます。\n・「120」…500人の24％にあたる数で、12％ではありません。12％は100人あたり12人なので、500人では60人です。\n・「600」…全体の500人より多い数です。12％は100％より小さいので、部分は500人より少なくなります。",
  "math_g5_hand_graph_012":"町の人口の120人の15％なので、120×0.15＝18人です。15％は0.15です。\n\nほかの 選択肢\n・「15」…15％という割合の数字を、そのまま人数にした数です。人数は、120人の15％で求めます。\n・「8」…８人は、120人の約6.7％にあたる数です。15％は120×0.15＝18人です。\n・「180」…全体の120人より多い数です。15％は100％より小さいので、部分は120人より少なくなります。",
  "math_g5_hand_graph_013":"全体は100％です。100から、わかっている割合の合計をひきます。35＋25＋20＝80、100－80＝20％です。\n\nほかの 選択肢\n・「80」…３つの割合の合計の80％です。のこりの１つは、100％からその合計をひいて求めます。\n・「25」…25％だと合計が105％になって、100％をこえます。\n・「15」…15％だと合計が95％になって、100％にたりません。",
  "math_g5_hand_graph_014":"ふえた分は、今年の割合から去年の割合をひきます。35－30＝５で、５％分ふえました。割合のちがいは、ひき算で求めます。\n\nほかの 選択肢\n・「30」…去年の割合の30％をそのまま答えにした数です。聞かれているのはふえた分です。\n・「35」…今年の割合の35％をそのまま答えにした数です。聞かれているのはふえた分です。\n・「10」…35－30＝５なので、10％ではありません。10％だと、今年は40％になります。",
  "math_g5_hand_graph_015":"全部の80人の５％なので、80×0.05＝４人です。５％は0.05です。答えは 4 です。\n\nほかの 選択肢\n・「5」…５％という割合の数字を、そのまま人数にした数です。人数は、80人の５％で求めます。\n・「16」…80の20％の人数です。80×0.2＝16人で、５％は80×0.05＝４人です。\n・「8」…80の10％の人数です。80×0.1＝８人で、５％は４人です。",
  "math_g5_hand_graph_016":"全体の600人の18％なので、600×0.18＝108人です。18％は0.18です。\n\nほかの 選択肢\n・「1080」…108の位を１つずらして、10倍にした数です。18％は全体の約５分の１なので、部分は600人より少ないです。\n・「492」…全体の600人から108人をひいた、のこりの82％の人数です。\n・「150」…600人の25％、150人です。18％は25％より小さいので、ちがいます。",
  "math_g5_hand_graph_017":"円グラフの全体の中心の角は360°です。90°の部分の割合は、90÷360＝0.25。0.25は25％です。\n\nほかの 選択肢\n・「90」…90というのは角の大きさで、割合ではありません。割合は、90÷360で求めます。\n・「50」…50％は、180°にあたる半円の割合です。90°は、その半分です。\n・「75」…75％は、270°にあたる割合です。90°は、その３分の１です。",
  "math_g5_hand_graph_018":"円グラフの全体の中心の角は360°です。10％はその0.1倍なので、360×0.1＝36°です。\n\nほかの 選択肢\n・「18」…5％にあたる角です。10％は、18°の２倍の36°です。\n・「72」…20％にあたる角です。10％は、72°の半分の36°です。\n・「90」…25％にあたる角です。90°は、円の４分の１です。10％は、それより小さいです。",
  "math_g5_hand_graph_019":"若い人は 2400×0.35＝840人、お年寄りは 2400×0.15＝360人です。差は 840－360＝480人です。割合のちがいを20％と考えて 2400×0.2＝480としても同じです。\n\nほかの 選択肢\n・「840」…若い人の人数です。お年寄りとの差を聞かれています。\n・「360」…お年寄りの人数です。若い人の人数との差を聞かれています。\n・「1200」…合計の若い人とお年寄りの合計の人数 840＋360＝1200人です。差を聞かれているので、ひき算をします。",
  "math_g5_hand_graph_020":"スキーを選んだ12人が、全体の30人の何％かを求めます。12÷30＝0.4。0.4は40％です。\n\nほかの 選択肢\n・「30」…30は、全体の人数です。割合ではありません。割合は、12÷30＝0.4で、40％です。\n・「20」…20％は、そりの６人の割合、6÷30＝0.2です。スキーではありません。\n・「10」…10％は、その他の３人の割合、3÷30＝0.1です。スキーではありません。",
  "math_g5_hand_graph_021":"帯全体の20cmが100％です。35％の長さは、20×0.35＝７cmです。\n\nほかの 選択肢\n・「13」…帯の全体の20cmから７cmをひいたのこりの、65％の長さ13cmです。\n・「0.7」…７の位をずらして、0.1倍にした数です。20cmの35％は、1cmより長いです。\n・「70」…７の位を１つずらして、10倍にした数です。20cmの35％が70cmになることはありません。",
  "math_g5_hand_graph_022":"全体は100％なので、のこりは100から他の割合の合計をひいて求めます。45＋30＋10＝85、100－85＝15％です。\n\nほかの 選択肢\n・「25」…25％だと合計が110％になって、100％をこえます。\n・「10」…10％はＤの割合です。Ｃの割合を聞かれています。\n・「20」…20％だと合計が105％になって、100％をこえます。",
  "math_g5_hand_intdec_001":"10倍すると、小数点が右へ１けたうつります。3.45の小数点を右へ１けたうつして、34.5です。\n\nほかの 選択肢\n・「0.345」…小数点を左へ１けたうつした数で、10分の１にしたときの数です。\n・「345」…小数点を右へ２けたうつした数で、100倍にしたときの数です。\n・「3.45」…もとの3.45と同じ数です。10倍すると、位が１つ上がります。",
  "math_g5_hand_intdec_002":"100倍すると、小数点が右へ２けたうつります。3.45は、345になります。\n\nほかの 選択肢\n・「34.5」…小数点を右へ１けたうつした数で、10倍にしたときの数です。\n・「0.345」…小数点を左へ１けたうつした数で、10分の１にしたときの数です。\n・「3450」…小数点を右へ３けたうつした数で、1000倍にしたときの数です。",
  "math_g5_hand_intdec_003":"10分の１にすると、小数点が左へ１けたうつります。3.45は、0.345になります。\n\nほかの 選択肢\n・「34.5」…小数点を右へ１けたうつした数で、10倍にしたときの数です。\n・「0.0345」…小数点を左へ２けたうつした数で、100分の１にしたときの数です。\n・「345」…小数点を右へ２けたうつした数で、100倍にしたときの数です。",
  "math_g5_hand_intdec_004":"10倍すると、小数点が右へ１けたうつります。0.6は６になります。0.6は0.1が６こ分で、10倍すると１が６こ分になります。\n\nほかの 選択肢\n・「60」…小数点を右へ２けたうつした数で、100倍にしたときの数です。\n・「0.06」…小数点を左へ１けたうつした数で、10分の１にしたときの数です。\n・「0.6」…もとの0.6と同じ数です。10倍すると、位が１つ上がります。",
  "math_g5_hand_intdec_005":"100倍すると、小数点が右へ２けたうつります。2.5は、250になります。\n\nほかの 選択肢\n・「25」…小数点を右へ１けたうつした数で、10倍にしたときの数です。\n・「2500」…小数点を右へ３けたうつした数で、1000倍にしたときの数です。\n・「0.25」…小数点を左へ２けたうつした数で、100分の１にしたときの数です。",
  "math_g5_hand_intdec_006":"10分の１にすると、小数点が左へ１けたうつります。4.8は、0.48になります。\n\nほかの 選択肢\n・「48」…小数点を右へ１けたうつした数で、10倍にしたときの数です。\n・「0.048」…小数点を左へ２けたうつした数で、100分の１にしたときの数です。\n・「4.8」…もとの4.8と同じ数です。10分の１にすると、位が１つ下がります。",
  "math_g5_hand_intdec_007":"小数点を右へ１けたうつすと、各位の数字が１つ上の位にあがり、数は10倍になります。たとえば、0.5が５になります。\n\nほかの 選択肢\n・「100」…100倍になるのは、小数点を右へ２けたうつしたときです。\n・「1」…小数点を右へうつすと数は大きくなるので、１倍（そのまま）にはなりません。\n・「2」…２倍ではありません。小数点を右へ１けたうつすと10倍、２けたうつすと100倍になります。",
  "math_g5_hand_intdec_008":"100倍すると、小数点が右へ２けたうつります。0.07は、７になります。\n\nほかの 選択肢\n・「0.7」…小数点を右へ１けたうつした数で、10倍にしたときの数です。\n・「70」…小数点を右へ３けたうつした数で、1000倍にしたときの数です。\n・「0.0007」…小数点を左へ２けたうつして、100分の１にした数です。100倍は右へうつします。",
  "math_g5_hand_intdec_009":"100分の１にすると、小数点が左へ２けたうつります。520は、5.20＝5.2になります。\n\nほかの 選択肢\n・「52」…小数点を左へ１けたうつした数で、10分の１にしたときの数です。\n・「0.52」…小数点を左へ３けたうつした数で、1000分の１にしたときの数です。\n・「0.052」…小数点を左へ４けたうつした数で、10000分の１にしたときの数です。",
  "math_g5_hand_intdec_010":"1000分の１にすると、小数点が左へ３けたうつります。12.5は、0.0125になります。\n\nほかの 選択肢\n・「0.125」…小数点を左へ２けたうつした数で、100分の１にしたときの数です。\n・「0.00125」…小数点を左へ４けたうつした数で、10000分の１にしたときの数です。\n・「0.0012」…0.00125を切り捨てた数で、位もちがっています。12.5の小数点を左へ３けたうつして、0.0125です。",
  "math_g5_hand_intdec_011":"小数第１位は小数点のすぐ右の位で、小数第２位はその次の位です。6.38の小数第１位は３、小数第２位は８です。この問題の「小数第２位」にあたるのは８で、３は小数第１位の数字です。\n\nほかの 選択肢\n・「6」…６は、小数点の左の一の位の数字です。小数第２位ではありません。\n・「8」…８は、小数点から数えて２つ目の位の数字で、小数第２位そのものです。\n・「38」…38は、小数第１位と小数第２位をならべた数で、位を表す数字ではありません。",
  "math_g5_hand_intdec_012":"0.001が10こで0.01、100こで0.1、1000こで１になります。0.001×1000＝１です。\n\nほかの 選択肢\n・「0.1」…0.1は、0.001を100こ集めた数です。\n・「10」…10は、0.001を10000こ集めた数です。\n・「100」…100は、0.001を100000こ集めた数です。",
  "math_g5_hand_intdec_013":"0.01が何こ分かは、4.06÷0.01で求めます。4.06は0.01が406こ分です。4は0.01が400こ、0.06は0.01が６こ分で、合わせて406こです。\n\nほかの 選択肢\n・「46」…46は、4と6をならべた数です。0.01が46こ分だと0.46です。\n・「4.06」…4.06は、集めた数そのものです。何こ集めたかを聞かれています。\n・「40.6」…40.6は、0.1が406こ分の数です。0.01の場合は、4.06です。",
  "math_g5_hand_intdec_014":"0.1を35こ集めた数は、0.1×35＝3.5です。0.1が10こで１になるので、30こで３、のこりの５こで0.5になります。\n\nほかの 選択肢\n・「35」…35は、0.1を350こ集めた数です。\n・「0.35」…0.35は、0.01を35こ集めた数です。0.1ではなく、0.01の場合です。\n・「3.05」…3.05は、整数の３と0.05をたした数です。0.1を35こ集めた数とはちがいます。",
  "math_g5_hand_intdec_015":"右へ１けたうつすと10倍になるので、もとの数は4.5の10分の１です。4.5÷10＝0.45です。0.45の小数点を右へ１けたうつすと、4.5になります。\n\nほかの 選択肢\n・「45」…4.5をさらに10倍した数です。もとの数は4.5より小さいです。\n・「0.045」…4.5の100分の１の数です。もとの数は4.5の10分の１です。\n・「4.05」…4.05は、0.45とは数字がちがいます。10倍しても4.5になりません。",
  "math_g5_hand_intdec_016":"2.305÷0.001を計算して、2305です。2.305は、0.001が2305こ集まった数です。2は0.001が2000こ、0.3は300こ、0.005は５こ分で、合わせて2305です。\n\nほかの 選択肢\n・「235」…235は、2と3と5をならべたものです。2.305は、0.001が235こではありません。\n・「23.05」…23.05は、小数点をうつした数です。何こ集めるかを聞かれています。\n・「305」…305は、小数点の右の305をそのまま答えにした数です。整数の２の分もたしていません。",
  "math_g5_hand_intdec_017":"10倍した数が7.2なので、もとの数は7.2÷10＝0.72です。たしかめると、0.72×10＝7.2です。\n\nほかの 選択肢\n・「72」…72は、7.2をさらに10倍した数です。もとの数は、7.2より小さいです。\n・「0.072」…0.072は、7.2の100分の１です。もとの数は7.2の10分の１です。\n・「7.02」…7.02は、数字をまちがえた数です。10倍しても7.2になりません。",
  "math_g5_hand_intdec_018":"ある数の100分の１が0.063なので、ある数は0.063の100倍です。0.063×100＝6.3です。たしかめると、6.3÷100＝0.063です。\n\nほかの 選択肢\n・「0.63」…0.63は、0.063の10倍です。100倍ではありません。\n・「63」…63は、0.063の1000倍です。\n・「0.00063」…0.00063は、0.063の100分の１です。100分の１にしてしまった数です。",
  "math_g5_hand_intdec_019":"1kmは1000mです。1.5km＝1.5×1000＝1500mです。小数点を右へ３けたうつします。\n\nほかの 選択肢\n・「150」…150mは、1.5を100倍した数です。1km＝1000mなので、1000倍します。\n・「15」…15mは、1.5を10倍した数です。1kmは10mではなく1000mです。\n・「15000」…15000mは、1.5km×10000の数です。1kmは1000mです。",
  "math_g5_hand_intdec_020":"3.6kg＝3600gです。3600÷1000＝3.6gです。kgをgに直してから、1000分の１にします。\n\nほかの 選択肢\n・「0.36」…0.36は、3.6を10分の１にした数です。1000分の１にします。\n・「36」…36は、3.6を10倍した数です。1000分の１にするので、小さくなります。\n・「0.0036」…0.0036は、3.6kgの1000分の１を、kgのまま答えた数です。gに直すと3.6gです。",
  "math_g5_hand_intdec_021":"0.04を100倍すると、小数点が右へ２けたうつって４になります。４は0.4の何倍かは、４÷0.4＝10で、10倍です。\n\nほかの 選択肢\n・「100」…100倍は、0.04をもとにして考えたときの倍です。0.4と比べると、10倍です。\n・「1」…１倍は、同じ大きさのときです。４と0.4はちがうので、１倍ではありません。\n・「0.1」…0.1倍は、10分の１にした数です。４は0.4より大きいので、0.1倍ではありません。",
  "math_g5_hand_intdec_022":"35.7を10倍すると、小数点が右へ１けたうつって357です。それを100分の１にすると、小数点が左へ２けたうつって3.57です。\n\nほかの 選択肢\n・「357」…10倍した数です。そのあと、100分の１にするのを忘れています。\n・「35.7」…もとの35.7です。10倍して100分の１にすると、10分の１になります。\n・「0.357」…0.357は、35.7を100分の１にした数です。10倍してから100分の１にするので、もとの10分の１の3.57になります。",
  "math_g5_hand_multiple_001":"３の倍数は、３でわりきれる数です。10～16のうち、３でわりきれるのは12（12÷３＝４）だけです。３の倍数は 3、6、9、12、15…とならびます。\n\nほかの 選択肢\n・「10」…10÷３＝３あまり１で、わりきれません。３の倍数ではありません。\n・「14」…14÷３＝４あまり２で、わりきれません。３の倍数ではありません。\n・「16」…16÷３＝５あまり１で、わりきれません。３の倍数ではありません。",
  "math_g5_hand_multiple_002":"約数は、その数をわりきれる数です。12の約数は 1、2、3、4、6、12 で、いちばん大きいのは12自身です。どんな数でも、その数自身が、いちばん大きい約数です。\n\nほかの 選択肢\n・「6」…６は12の約数ですが、12のほうが大きいので、いちばん大きくはありません。\n・「4」…４は12の約数ですが、12のほうが大きいので、いちばん大きくはありません。\n・「24」…24は12の倍数であり、約数ではありません。12を24でわることはできません。",
  "math_g5_hand_multiple_003":"６の倍数は 6、12、18、24…、９の倍数は 9、18、27…です。共通の倍数（公倍数）で、いちばん小さいのは18です。これを最小公倍数といいます。\n\nほかの 選択肢\n・「3」…３は６と９の最大公約数で、公約数です。倍数ではありません。\n・「36」…36は６と９の公倍数ですが、18より大きいので、最小ではありません。\n・「54」…54は６と９の公倍数ですが、18より大きいので、最小ではありません。",
  "math_g5_hand_multiple_004":"８の約数は 1、2、4、8、12の約数は 1、2、3、4、6、12 です。共通の約数（公約数）は 1、2、4 で、いちばん大きいのは４です。これを最大公約数といいます。\n\nほかの 選択肢\n・「2」…２は８と12の公約数ですが、４のほうが大きいので、最大ではありません。\n・「24」…24は８と12の最小公倍数です。最大公約数ではありません。\n・「1」…１は公約数ですが、４のほうが大きいので、最大ではありません。",
  "math_g5_hand_multiple_005":"10の約数は、10をわりきれる数で、1、2、5、10 の４こです。小さい順にわり算で調べていくと、もれなく見つかります。答えは 4 です。\n\nほかの 選択肢\n・「2」…２こは、素数の２と５だけを数えた数です。１と10も約数です。\n・「3」…３こでは、１、２、５は数えていますが、10自身をぬかしています。\n・「5」…５こは、１から５までを全部約数と考えた数です。３と４は10をわりきれないので、約数ではありません。",
  "math_g5_hand_multiple_006":"４の倍数は、４でわりきれる数です。16÷４＝４でわりきれます。４の倍数は 4、8、12、16、20、24…です。\n\nほかの 選択肢\n・「14」…14÷４＝３あまり２で、わりきれません。４の倍数ではありません。\n・「18」…18÷４＝４あまり２で、わりきれません。４の倍数ではありません。\n・「22」…22÷４＝５あまり２で、わりきれません。４の倍数ではありません。",
  "math_g5_hand_multiple_007":"４の倍数は 4、8、12、16、20、24…、６の倍数は 6、12、18、24…です。共通の倍数で、いちばん小さいのは12です。\n\nほかの 選択肢\n・「2」…２は４と６の最大公約数で、倍数ではなく約数です。\n・「24」…24は４と６の公倍数ですが、12より大きいので、最小ではありません。\n・「10」…10は４の倍数でも６の倍数でもありません。４と６をたした数です。",
  "math_g5_hand_multiple_008":"12の約数は 1、2、3、4、6、12、18の約数は 1、2、3、6、9、18 です。共通の約数は 1、2、3、6 で、いちばん大きいのは６です。\n\nほかの 選択肢\n・「3」…３は12と18の公約数ですが、６のほうが大きいので、最大ではありません。\n・「36」…36は12と18の最小公倍数です。最大公約数ではありません。\n・「2」…２は12と18の公約数ですが、６のほうが大きいので、最大ではありません。",
  "math_g5_hand_multiple_009":"15の倍数は 15、30、45、60…、20の倍数は 20、40、60…です。共通の倍数で、いちばん小さいのは60です。\n\nほかの 選択肢\n・「5」…５は15と20の最大公約数です。倍数ではなく約数です。\n・「30」…30は15の倍数ですが、20の倍数ではありません。30÷20は、わりきれません。\n・「300」…300は15と20の公倍数ですが、60より大きいので、最小ではありません。15×20の積です。",
  "math_g5_hand_multiple_010":"24の約数は、24をわりきれる数で、1、2、3、4、6、8、12、24の８こです。かけて24になる２つの数の組、1×24、2×12、3×8、4×6 から見つけられます。\n\nほかの 選択肢\n・「6」…６こでは、約数をもれなく数えていません。８と24もふくめます。\n・「4」…４こでは、24の約数が足りません。かけて24になる組は４組あり、約数は８こです。\n・「12」…12こは、24以下の数をたくさん約数としてしまった数です。5や7など、わりきれない数があります。",
  "math_g5_hand_multiple_011":"５の倍数は、5、10、15、20、25、30の６こです。30÷５＝６なので、６こと求めることもできます。答えは 6 です。\n\nほかの 選択肢\n・「5」…５こでは、30をぬかしています。30は５の倍数です。\n・「7」…７こでは、多すぎます。35は30をこえています。\n・「30」…30こは、１から30までの全部を数えた数です。５の倍数は、そのうち６こだけです。",
  "math_g5_hand_multiple_012":"奇数は２でわると１あまる数、偶数は２でわりきれる数です。奇数と奇数をたすと、1あまる数が２つで、あまりが合わさって、いつも偶数になります。たとえば 3＋5＝８、7＋9＝16です。\n\nほかの 選択肢\n・「{奇数|きすう}」…奇数と奇数をたした答えは、いつも偶数で、奇数にはなりません。\n・「{偶数|ぐうすう}のときも{奇数|きすう}のときもある」…奇数どうしをたして、奇数になることはありません。\n・「どちらでもない」…整数は、偶数か奇数のどちらかです。",
  "math_g5_hand_multiple_013":"同じ大きさの正方形にあまりなく切るには、１辺をたてと横の公約数にします。いちばん大きいものは最大公約数です。18と24の最大公約数は６なので、１辺は６cmです。答えは 6 です。\n\nほかの 選択肢\n・「3」…３cmは18と24の公約数ですが、６cmのほうが大きいので、最大ではありません。\n・「72」…72は18と24の最小公倍数です。切る正方形の１辺ではありません。\n・「2」…２cmは18と24の公約数ですが、６cmのほうが大きいので、最大ではありません。",
  "math_g5_hand_multiple_014":"同時に出発するのは、６の倍数と８の倍数が重なるときです。重なる最初が最小公倍数で、６と８の最小公倍数は24なので、24分後です。\n\nほかの 選択肢\n・「2」…２は６と８の最大公約数です。２分後には、まだ同時に出発しません。\n・「14」…14は６と８をたした数です。14分は、６の倍数でも８の倍数でもありません。\n・「48」…48は24の倍数で、２回目に同時に出発するときです。次に同時なのは、24分後です。",
  "math_g5_hand_multiple_015":"素数は、１とその数自身でしかわりきれない数です。１から10では、２、３、５、７の４こです。４、６、８、10は２でもわりきれ、９は３でもわりきれるので、素数ではありません。１は素数にふくめません。答えは 4 です。\n\nほかの 選択肢\n・「3」…３こでは、７をぬかしています。７も素数です。\n・「5」…５こでは、素数でない９や１を数えてしまっています。９は３でもわりきれます。\n・「6」…６こでは、素数でない数を多く数えています。４、６、８、９、10は素数ではありません。",
  "math_g5_hand_multiple_016":"最小公倍数は、３つの数すべての倍数で、いちばん小さい数です。９の倍数 9、18、27、36のうち、４でも６でもわりきれる最小の数は36です。36÷４＝９、36÷６＝６です。\n\nほかの 選択肢\n・「18」…18は９と６の公倍数ですが、４でわりきれません。18÷４は、わりきれません。\n・「24」…24は４と６の公倍数ですが、９でわりきれません。24÷９は、わりきれません。\n・「72」…72は３つの数の公倍数ですが、36より大きいので、最小ではありません。",
  "math_g5_hand_multiple_017":"24の約数は 1、2、3、4、6、8、12、24、36の約数は 1、2、3、4、6、9、12、18、36 です。共通の約数のうち、いちばん大きいのは12です。\n\nほかの 選択肢\n・「6」…６は24と36の公約数ですが、12のほうが大きいので、最大ではありません。\n・「4」…４は24と36の公約数ですが、12のほうが大きいので、最大ではありません。\n・「72」…72は24と36の最小公倍数です。最大公約数ではありません。",
  "math_g5_hand_multiple_018":"同じ人数ずつに分けるとき、できるだけ多い人数にするには、最大公約数を使います。40と56の最大公約数は８なので、１グループは８人で、40人は５グループ、56人は７グループです。\n\nほかの 選択肢\n・「4」…４人は40と56の公約数ですが、８人のほうが多いので、最大ではありません。\n・「16」…16は56の約数でも、40の約数でもありません。40÷16は、わりきれません。\n・「280」…280は40と56の最小公倍数です。人数を分けるときは、公約数を使います。",
  "math_g5_hand_multiple_019":"３と４の公倍数は、最小公倍数12の倍数です。12の倍数は 12、24、36、48、60、72、84、96の８こで、次の108は100をこえます。\n\nほかの 選択肢\n・「7」…７こでは、1つぬかしています。12から96まで、数えなおします。\n・「9」…９こでは、108を数えています。108は100より大きいので、ふくめません。\n・「33」…33は、100÷３の33こで、３の倍数の数です。３と４の公倍数ではありません。",
  "math_g5_hand_multiple_020":"あまりなく切るには、１辺をたてと横の最大公約数にします。12と20の最大公約数は４なので、１辺は４cmです。たてに12÷４＝３まい、横に20÷４＝５まいで、3×5＝15まいです。\n\nほかの 選択肢\n・「4」…４は正方形の１辺の長さで、まい数ではありません。\n・「5」…５は、横に切れるまい数です。まい数は、たてと横をかけます。\n・「60」…60は12と20の最小公倍数です。まい数ではありません。",
  "math_g5_hand_multiple_021":"５でも６でも３あまる数は、５と６の公倍数に３をたした数です。最小公倍数は30なので、30＋3＝33です。33÷５＝６あまり３、33÷６＝５あまり３です。\n\nほかの 選択肢\n・「18」…18÷５は３あまり３ですが、18÷６は３でわりきれます。あまりが３にならないので、ちがいます。\n・「30」…30は５でも６でもわりきれる数で、あまりが出ません。３をたします。\n・「63」…63は、30の２倍に３をたした数です。33のほうが小さいので、最小ではありません。",
  "math_g5_hand_multiple_022":"２つの整数の積は、最大公約数×最小公倍数と同じです。4×24＝96です。一方が８なら、もう一方は 96÷8＝12です。たしかめると、８と12の最大公約数は４、最小公倍数は24です。\n\nほかの 選択肢\n・「3」…３は、８との最大公約数が１になってしまい、４になりません。\n・「6」…６は、８との最大公約数が２になってしまい、４になりません。\n・「16」…16は、８との最大公約数が８になってしまい、４になりません。",
  "math_g5_hand_percent_001":"百分率にするには、割合を100倍します。0.25×100＝25なので、25％です。0.01が１％、0.25は0.01が25こ分と考えます。\n\nほかの 選択肢\n・「2.5」…2.5は、0.25を10倍した数です。百分率にするには、100倍します。\n・「250」…250は、0.25を1000倍した数です。百分率にするには、100倍します。\n・「0.25」…0.25は、もとの小数をそのまま書いた数です。％にするには、100倍します。",
  "math_g5_hand_percent_002":"％を小数に直すには、100でわります。40÷100＝0.4です。1％が0.01なので、40％は0.01が40こ分の0.4です。\n\nほかの 選択肢\n・「4」…４は、40％を10でわった数です。小数に直すには、100でわります。\n・「40」…40は、％の数字をそのまま書いた数です。小数に直すには、100でわります。\n・「0.04」…0.04は、40％を1000でわった数です。小数に直すには、100でわります。",
  "math_g5_hand_percent_003":"割合は、くらべる量が、もとにする量の何倍かを表す数で、くらべる量÷もとにする量で求めます。たとえば、20人の中の５人なら、５÷20＝0.25です。\n\nほかの 選択肢\n・「もとにする量÷くらべる量」…もとにする量÷くらべる量では、わる数とわられる数が反対になっています。\n・「くらべる量×もとにする量」…くらべる量×もとにする量は、かけ算です。割合は、わり算で求めます。\n・「くらべる量－もとにする量」…くらべる量－もとにする量は、ひき算です。割合は、わり算で求めます。",
  "math_g5_hand_percent_004":"割合は、くらべる量÷もとにする量です。雪あそびを選んだ５人÷全体の20人＝0.25。0.25を100倍して、25％です。\n\nほかの 選択肢\n・「15」…15は、20－５の、選ばなかった人数です。割合ではありません。\n・「20」…20は、全体の人数です。割合は、５÷20で求めます。\n・「75」…75％は、雪あそびを選ばなかった15人の割合です。選んだ人の割合は、25％です。",
  "math_g5_hand_percent_005":"割合の１割は、0.1です。百分率で表すと、0.1×100＝10％です。1割＝10％とおぼえましょう。\n\nほかの 選択肢\n・「1」…１％は、0.01です。１割は、その10倍です。\n・「100」…100％は、全体です。割合では、10割にあたります。\n・「0.1」…0.1は、小数で表した割合です。百分率にするには、100倍して10％です。",
  "math_g5_hand_percent_006":"150人の40％は、150×0.4＝60人です。40％は小数で0.4です。\n\nほかの 選択肢\n・「90」…90人は、150人から60人をひいた、のこりの60％の人数です。\n・「110」…110人は、150人から40人をひいた数です。40％は40人ではありません。\n・「600」…600人は、全体の150人より多い数です。部分が全体より多くなることはありません。",
  "math_g5_hand_percent_007":"割合は、くらべる量÷もとにする量です。入っている20こ÷箱の80こ＝0.25。0.25を％に直して、25％です。\n\nほかの 選択肢\n・「75」…75％は、入っていない60この割合です。入っている割合を聞かれています。\n・「60」…60は、80－20で、入っていない数です。割合ではありません。\n・「0.25」…0.25は、小数で表した割合です。％にするには、100倍して25％です。",
  "math_g5_hand_percent_008":"定員の125％は、定員の1.25倍です。80×1.25＝100人です。125％は100％より大きいので、定員より多い人数になります。\n\nほかの 選択肢\n・「64」…64人は、80÷1.25の数です。もとの数に1.25をかけます。\n・「105」…105人は、80人に25人をたした数です。25％は、25人ではなく、80×0.25＝20人です。\n・「125」…125人は、125％の数字をそのまま人数にした数です。人数は、80人の125％で求めます。",
  "math_g5_hand_percent_009":"１割は10％、１分は１％です。３割５分は、30％＋５％＝35％です。小数では、0.35です。\n\nほかの 選択肢\n・「3.5」…3.5は、３割５分を3.5としてしまった数です。百分率では、35％です。\n・「350」…350は、３割５分を100倍しすぎた数です。35％が正しいです。\n・「0.35」…0.35は、小数で表した割合です。％にするには、100倍して35％です。",
  "math_g5_hand_percent_010":"30％引きは、定価の70％で買うことです。1200×0.7＝840円です。30％引きの30％は、1200×0.3＝360円で、それを1200円からひいても、1200－360＝840円です。\n\nほかの 選択肢\n・「360」…360円は、引いてもらう金額です。代金は、1200円からひいたのこりです。\n・「1230」…1230円は、1200円に30円をたした数です。引くので、代金は1200円より安くなります。\n・「1560」…1560円は、30％ふやした1200×1.3の数です。引くのですから、代金は安くなります。",
  "math_g5_hand_percent_011":"もとにする量は、くらべる量÷割合で求めます。45÷0.3は、わる数もわられる数も10倍して、450÷3＝150です。たしかめると、150×0.3＝45になります。\n\nほかの 選択肢\n・「135」…135は、45に３をかけた数です。もとにする量は、45÷0.3で求めます。\n・「75」…75は、45と30をたした数です。割合の30％を30と考えてしまっています。\n・「1500」…1500は、150の位を１つずらして10倍にした数です。1500の30％は450です。",
  "math_g5_hand_percent_012":"２割引きは、定価の８割（80％）で買うことです。800×0.8＝640円です。800×0.2＝160円を引いた、800－160＝640円と考えても同じです。\n\nほかの 選択肢\n・「160」…160円は、引いてもらう金額です。代金は、800円から引いたのこりです。\n・「560」…560円は、３割引きのときの代金800×0.7です。２割引きではありません。\n・「820」…820円は、800円に20円をたした数です。引くので、代金は800円より安くなります。",
  "math_g5_hand_percent_013":"小数を百分率で表すには、100倍します。0.08×100＝８なので、８％です。0.01が１％なので、0.08は0.01が８こ分です。\n\nほかの 選択肢\n・「0.8」…0.8は、0.08をそのまま10倍した数です。百分率にするには、100倍します。\n・「80」…80は、0.08を1000倍した数です。百分率にするには、100倍します。\n・「0.08」…0.08は、もとの小数をそのまま書いた数です。％にするには、100倍します。",
  "math_g5_hand_percent_014":"25％ねあがりは、もとのねだんの125％（1.25倍）になることです。200×1.25＝250円です。ふえた分は200×0.25＝50円で、200＋50＝250円と考えても同じです。\n\nほかの 選択肢\n・「175」…175円は、200円から25円をひいた数です。ふえるので、200円より高くなります。\n・「225」…225円は、200円に25円をたした数です。25％は25円ではなく、200×0.25＝50円です。\n・「150」…150円は、200円の75％のねだんです。ねあがりではなく、ねさげです。",
  "math_g5_hand_percent_015":"今年の人数は去年の人数の何％かを聞かれています。もとにする量は去年の400人なので、480÷400＝1.2。1.2は120％です。\n\nほかの 選択肢\n・「20」…20％は、去年より何％ふえたかです。今年が去年の何％かではありません。\n・「83」…83％は、去年÷今年、400÷480の割合です。もとにする量が反対です。\n・「80」…80％だと、今年は去年より少なくなります。480人は400人より多いです。",
  "math_g5_hand_percent_016":"もとの人数の80％が120人なので、もとの人数＝120÷0.8です。両方を10倍して1200÷８＝150人です。たしかめると、150×0.8＝120になります。\n\nほかの 選択肢\n・「96」…96人は、120に0.8をかけた数です。もとの数を求めるには、わり算をします。\n・「200」…200人は、120÷0.6の数です。割合は60％ではなく、80％です。\n・「1500」…1500人は、150の位を１つずらして10倍にした数です。1500の80％は1200です。",
  "math_g5_hand_percent_017":"３割引きは、定価の７割（70％）で売ることです。1500×0.7＝1050円です。引く額は、1500×0.3＝450円で、1500－450＝1050円と考えても同じです。\n\nほかの 選択肢\n・「450」…450円は、引く金額です。売るねだんは、1500円から引いたのこりです。\n・「1200」…1200円は、２割引きのときのねだん、1500×0.8です。３割引きではありません。\n・「1950」…1950円は、3割ふやしたときの、1500×1.3の数です。引くのですから、安くなります。",
  "math_g5_hand_percent_018":"20％へらしたので、今月は先月の80％です。50×0.8＝40kgです。へらした量は50×0.2＝10kgで、50－10＝40kgと考えても同じです。\n\nほかの 選択肢\n・「10」…10kgは、へらした量です。今月の量は、先月からひいたのこりです。\n・「60」…60kgは、20％ふやしたときの、50×1.2の数です。へらしたのですから、少なくなります。\n・「30」…30kgは、50kgから20kgをひいた数です。20％は20kgではなく、50×0.2＝10kgです。",
  "math_g5_hand_percent_019":"割合は、くらべる量÷もとにする量です。当たった14回÷なげた40回＝0.35。0.35を％に直して、35％です。\n\nほかの 選択肢\n・「26」…26％は、40－14の、はずれた26回を使った数です。割合ではありません。\n・「54」…54％は、40＋14をした数です。割合は、14÷40で求めます。\n・「14」…14は、当たった回数です。割合は、14÷40＝0.35で、35％です。",
  "math_g5_hand_percent_020":"もとにする量は、くらべる量÷割合で求めます。定員の60％が90人なので、90÷0.6＝900÷６＝150人です。たしかめると、150×0.6＝90になります。\n\nほかの 選択肢\n・「54」…54人は、90に0.6をかけた数です。定員を求めるには、わり算をします。\n・「135」…135人は、90の1.5倍の数です。割合は60％なので、90÷0.6で求めます。\n・「1500」…1500人は、150の位を１つずらして10倍にした数です。1500人の60％は900人です。",
  "math_g5_hand_prism_001":"角柱の向かい合う平行で合同な２つの面を底面といいます。底面は、角柱の上と下（立てたとき）にある、同じ形の面です。\n\nほかの 選択肢\n・「側面」…側面は、底面のまわりをかこむ面です。\n・「頂点」…頂点は、辺と辺が集まる点です。\n・「辺」…辺は、面と面が交わる線です。",
  "math_g5_hand_prism_002":"角柱で、底面のまわりをかこむ、たての面を側面といいます。側面は底面に垂直で、角柱では長方形（または正方形）になります。\n\nほかの 選択肢\n・「底面」…底面は、向かい合う平行で合同な２つの面です。\n・「頂点」…頂点は、辺と辺が集まる点です。\n・「辺」…辺は、面と面が交わる線です。",
  "math_g5_hand_prism_003":"角柱の底面の形が、その角柱の名前になります。三角柱の底面は三角形です。\n\nほかの 選択肢\n・「四角形」…四角形は、四角柱の底面の形です。\n・「円」…円は、円柱の底面の形です。三角柱は、角柱の仲間で、底面は多角形です。\n・「五角形」…五角形は、五角柱の底面の形です。",
  "math_g5_hand_prism_004":"三角柱の面は、底面が２つ、側面が３つです。2＋3＝5こです。\n\nほかの 選択肢\n・「3」…３こは、側面だけの数です。底面の２こもふくめます。\n・「4」…４こは、底面と側面の数をまちがえた数です。底面は２つあります。\n・「6」…６こは、四角柱の面の数 2＋4 です。三角柱の側面は３つです。",
  "math_g5_hand_prism_005":"円柱の底面は、向かい合う２つの合同な円です。円柱という名前のとおり、底面が円の柱です。\n\nほかの 選択肢\n・「三角形」…三角形は、三角柱の底面の形です。円柱の底面は円です。\n・「長方形」…長方形は、円柱の側面を開いたときの形です。\n・「だ円」…だ円は、円をつぶしたような形です。円柱の底面は、まん丸な円です。",
  "math_g5_hand_prism_006":"角柱の側面の数は、底面の辺の数と同じです。四角柱は、底面が四角形で辺が４本あるので、側面は４つです。\n\nほかの 選択肢\n・「2」…２つは、底面の数です。側面の数は、底面の辺の数と同じです。\n・「6」…６つは、四角柱の面全部の数、4＋2 です。側面だけでは４つです。\n・「8」…８つは、四角柱の頂点の数です。側面の数ではありません。",
  "math_g5_hand_prism_007":"五角柱の底面は五角形で、頂点が５つあります。底面は２つあるので、頂点は 5×2＝10こです。\n\nほかの 選択肢\n・「5」…５こは、底面１つ分の頂点の数です。底面は２つあるので、２倍にします。\n・「7」…７こは、5＋2 のたし算です。底面が２つあるので、5×2 をします。\n・「15」…15こは、五角柱の辺の数、5×3 です。頂点の数ではありません。",
  "math_g5_hand_prism_008":"三角柱の辺は、底面の辺が３本ずつ２つ分で 3×2＝６本、底面をつなぐたての辺が３本あります。6＋3＝9本です。\n\nほかの 選択肢\n・「6」…６本は、底面の辺だけの数です。たての辺の３本もふくめます。\n・「8」…８本では、数えかたが足りません。底面の辺６本、たての辺３本で、合わせて９本です。\n・「12」…12本は、四角柱の辺の数、4×3 です。三角柱の底面は三角形で、辺は3×3＝９本です。",
  "math_g5_hand_prism_009":"六角柱の面は、底面が２つ、側面が６つで、2＋6＝8こです。側面の数は、底面の辺の数と同じです。\n\nほかの 選択肢\n・「6」…６こは、側面だけの数です。底面の２こもふくめます。\n・「7」…７こは、側面を５つとして数えた数です。側面は底面の辺の数と同じ６つです。\n・「12」…12こは、六角柱の頂点の数です。面の数ではありません。",
  "math_g5_hand_prism_010":"角柱の高さは、２つの底面の間の長さで、底面に垂直にはかります。ななめにはかったり、底面の外のまわりをはかったりしません。答えは「２つの底面の間の垂直な長さ」です。\n\nほかの 選択肢\n・「底面の１辺の長さ」…底面の１辺の長さは、底面の大きさを表す長さで、高さではありません。\n・「側面のななめの長さ」…側面のななめの長さは、底面に垂直でないので、高さではありません。\n・「底面のまわりの長さ」…底面のまわりの長さは、底面の周の長さで、高さではありません。",
  "math_g5_hand_prism_011":"円柱の側面を切り開くと、長方形になります。たての長さは円柱の高さ、横の長さは底面の円周の長さです。\n\nほかの 選択肢\n・「円」…円は、円柱の底面の形です。\n・「三角形」…三角形は、円柱の側面を開いた形ではありません。\n・「おうぎ形」…おうぎ形は、すい（円すい）の展開図の側面の形です。",
  "math_g5_hand_prism_012":"円柱の側面を開くと長方形になり、横の長さは底面の円周と同じです。円周＝直径×円周率です。半径５cmなら直径は10cmなので、10×3.14＝31.4cmです。\n\nほかの 選択肢\n・「15.7」…15.7は、半径5cmに3.14をかけた数で、円周の半分です。円周は、直径にかけます。\n・「10」…10は、底面の直径の長さで、円周ではありません。\n・「78.5」…78.5は、底面の円の面積 5×5×3.14 です。側面の長方形の横は、円周です。",
  "math_g5_hand_prism_013":"角柱の側面の数は、底面の辺の数と同じです。五角柱の底面は辺が５本なので、側面は５つです。\n\nほかの 選択肢\n・「2」…２つは、底面の数です。側面の数は、底面の辺の数と同じです。\n・「7」…７つは、五角柱の面全部の数、5＋2 です。側面だけでは５つです。\n・「10」…10は、五角柱の頂点の数です。側面の数ではありません。",
  "math_g5_hand_prism_014":"六角柱の辺は、底面の辺が６本ずつ２つ分で 6×2＝12本、たての辺が６本です。12＋6＝18本です。\n\nほかの 選択肢\n・「12」…12本は、底面の辺だけの数です。たての辺の６本もふくめます。\n・「16」…16本では、数えかたが足りません。底面の辺12本、たての辺６本で、合わせて18本です。\n・「24」…24本は、六角柱の辺の数より多い数です。たての辺は、底面の辺の数と同じ６本です。",
  "math_g5_hand_prism_015":"三角柱の底面は三角形で、頂点が３つあります。底面の頂点からもう１つの底面の頂点へたての辺が出ているので、底面に垂直な辺は３本です。答えは 3 です。\n\nほかの 選択肢\n・「2」…２本は、底面の数です。垂直な辺は、底面の頂点の数と同じです。\n・「6」…６本は、三角柱の頂点の数です。辺の数ではありません。\n・「9」…９本は、三角柱の辺全部の数です。底面の辺は、底面に垂直ではありません。",
  "math_g5_hand_prism_016":"角柱の頂点は、底面の頂点が２つ分です。16÷2＝８こなので、底面は頂点が８こある八角形です。答えは 8 です。\n\nほかの 選択肢\n・「16」…16は、角柱の頂点の数です。底面の頂点は、その半分です。\n・「6」…六角形の角柱は、頂点が 6×2＝12こです。16こにはなりません。\n・「10」…十角形の角柱は、頂点が 10×2＝20こです。16こにはなりません。",
  "math_g5_hand_prism_017":"角柱の辺の数は、底面の辺の数の３倍です。（底面の辺×２とたての辺）27÷3＝９なので、底面は九角形です。答えは 9 です。\n\nほかの 選択肢\n・「7」…七角形の角柱は、辺が 7×3＝21本です。27本にはなりません。\n・「8」…八角形の角柱は、辺が 8×3＝24本です。27本にはなりません。\n・「10」…十角形の角柱は、辺が 10×3＝30本です。27本にはなりません。",
  "math_g5_hand_prism_018":"角柱の面は、底面の２つと、側面です。側面は 10－2＝８こで、側面の数は底面の辺の数と同じなので、底面は八角形です。答えは 8 です。\n\nほかの 選択肢\n・「10」…10は、角柱の面の全部の数です。底面の２つをひいた数が、辺の数です。\n・「5」…五角形の角柱は、面が 5＋2＝７こです。10こにはなりません。\n・「12」…十二角形の角柱は、面が 12＋2＝14こです。10こにはなりません。",
  "math_g5_hand_prism_019":"円柱の側面の展開図の長方形で、横は底面の円周、たては高さです。円周は 10×3.14＝31.4cm、たては８cm。面積は 31.4×8＝251.2cm²です。\n\nほかの 選択肢\n・「25.12」…25.12は、251.2の位を１つずらして、10分の１にした数です。\n・「125.6」…125.6は、半径５cmに3.14をかけた15.7cmを横として、15.7×８とした数です。円周は直径にかけます。\n・「314」…314は、直径10cmをかけて10×10×3.14とした数です。側面の長方形の面積とはちがいます。",
  "math_g5_hand_prism_020":"側面は、底面の辺の長さを横、高さをたてにした長方形です。側面を全部合わせると、横は底面のまわりの長さ、たては高さになります。底面のまわりは 3＋4＋5＝12cm。12×10＝120cm²です。\n\nほかの 選択肢\n・「60」…60cm²は、側面の合計の半分です。３つの長方形は、全部たしあわせます。\n・「12」…12cmは、底面のまわりの長さです。高さの10cmをかけます。\n・「150」…150cm²は、側面の合計より大きい数です。底面のまわりは12cmで、15cmではありません。",
  "math_g5_hand_prism_021":"四角柱の側面は、長方形が４つです。１つの側面は、底面の１辺×高さ＝5×8＝40cm²です。４つで 40×4＝160cm²です。\n\nほかの 選択肢\n・「40」…40cm²は、側面１つ分の面積です。側面は４つあるので、４倍します。\n・「200」…200cm²は、側面を５つとした数、40×5 です。四角柱の側面は４つです。\n・「320」…320cm²は、側面を８つとした数、40×8 です。四角柱の側面は４つです。",
  "math_g5_hand_prism_022":"円柱の側面の長方形の横は、底面の円周です。円周＝直径×3.14なので、直径は 18.84÷3.14＝６cm。半径は直径の半分で３cmです。\n\nほかの 選択肢\n・「6」…６cmは、底面の円の直径です。半径は、その半分です。\n・「1.5」…1.5cmは、半径３cmの半分です。直径６cmの半分は３cmです。\n・「9.42」…9.42cmは、円周18.84cmの半分です。半径ではありません。",
  "math_g5_hand_proportion_001":"xが２倍、３倍…になるとき、yも２倍、３倍…になる関係を、比例といいます。たとえば、1本5円のえんぴつの本数と代金は比例しています。\n\nほかの 選択肢\n・「反比例している」…反比例は、xが２倍になると、yが２分の１倍になる関係です。この問題はyも２倍です。\n・「和が一定になっている」…和が一定とは、xとyをたすと、いつも同じ数になる関係です。xがふえるとyがへります。\n・「関係がない」…xが２倍になるとyも２倍になるので、関係があります。",
  "math_g5_hand_proportion_002":"y＝２×xのxに４を入れます。y＝2×4＝８です。yはxの２倍になっています。答えは 8 です。\n\nほかの 選択肢\n・「6」…６は、2＋4 のたし算です。y＝2×x なので、かけ算にします。\n・「2」…２は、式の２をそのまま書いた数です。xの値の４を入れて計算します。\n・「16」…16は、2×4×2 のように、２回かけた数です。y＝2×4＝８です。",
  "math_g5_hand_proportion_003":"代金は、１本のねだん×本数です。5×4＝20円です。yはxに比例していて、y＝５×xです。\n\nほかの 選択肢\n・「9」…９は、5＋4 のたし算です。代金は、1本のねだん×本数のかけ算で求めます。\n・「5」…５は、１本のねだんです。４本の代金を聞かれています。\n・「45」…45は、5×9 のような、本数をまちがえた数です。本数は４本なので、5×4＝20円です。",
  "math_g5_hand_proportion_004":"表を見ると、yはxの３倍になっています。x＝４のとき12です。xが５のときは 3×5＝15です。比例のとき、yは決まった数をxにかけた数になります。\n\nほかの 選択肢\n・「12」…12は、x＝４のときのyの値です。xが５のときは、３だけふえます。\n・「18」…18は、x＝６のときのyの値です。xが５のときは、15です。\n・「5」…５は、xの値そのものです。yは、xの３倍の15です。",
  "math_g5_hand_proportion_005":"比例のグラフは、０の点（原点）を通る直線になります。x＝０のとき、y＝0×(きまった数)＝０になるからです。答えは「０の点を通る直線」です。\n\nほかの 選択肢\n・「０の点を通らない直線」…０の点を通らない直線は、比例ではなく、一定の数をたした関係などです。比例では、xが０のとき、yも０です。\n・「まがった線」…比例のグラフは、まっすぐな線になります。\n・「たての直線」…たての直線は、xの値が変わらないグラフです。比例は、xが変わると、yも変わります。",
  "math_g5_hand_proportion_006":"yがxに比例しているとは、xが２倍、３倍…になるとyも２倍、３倍…になることです。正方形のまわりの長さは、1辺の４倍なので、1辺が２倍になるとまわりも２倍になります。答えは「正方形の１辺x cmとまわりの長さy cm」です。\n\nほかの 選択肢\n・「正方形の１辺x cmと面積y cm²」…正方形の面積は、１辺が２倍になると４倍になるので、比例していません。\n・「弟の年れいx才と兄の年れいy才」…年れいの関係は、弟が２倍の年れいになっても、兄が２倍の年れいにはなりません。\n・「人の年れいx才と身長y cm」…身長は、年れいが２倍になっても、２倍になりません。",
  "math_g5_hand_proportion_007":"水の量は、１分間に入る量×時間です。y＝4×xで、x＝６のとき、y＝4×6＝24Lです。\n\nほかの 選択肢\n・「10」…10は、4＋6 のたし算です。水の量は、1分間の量×時間のかけ算で求めます。\n・「20」…20は、4×5 の、５分間の水の量です。時間は６分間です。\n・「30」…30は、5×6 の数などで、4Lずつ入れた水の量ではありません。4×6＝24Lです。",
  "math_g5_hand_proportion_008":"y＝3×xで、yが21のとき、21＝3×xです。x＝21÷3＝７です。わり算で、xが求められます。\n\nほかの 選択肢\n・「18」…18は、21－3 のひき算です。x を求めるには、y÷3 をします。\n・「24」…24は、21＋3 のたし算です。x を求めるには、y÷3 をします。\n・「9」…９は、x＝９のときのyが27になる数です。y＝21のxは、21÷3＝７です。",
  "math_g5_hand_proportion_009":"代金は、１個のねだん×個数です。１個80円のパンをx個買うので、代金yは y＝80×x と表せます。\n\nほかの 選択肢\n・「y＝x÷80」…x÷80は、個数を１個のねだんでわる式です。代金は、かけ算で求めます。\n・「y＝80＋x」…80＋xは、たし算です。代金は、個数が２倍になると、２倍になるので、かけ算です。\n・「y＝x－80」…x－80は、ひき算です。代金は、個数が２倍になると、２倍になるので、かけ算です。",
  "math_g5_hand_proportion_010":"xが１のときのyの値は、yをxでわって求めます。表で x＝２のとき y＝６なので、6÷2＝3です。y＝３×xとなります。\n\nほかの 選択肢\n・「2」…２は、xの値です。xが１のときのyの値は、６÷２で求めます。\n・「6」…６は、x＝２のときのyの値です。xが１のときは、その半分です。\n・「18」…18は、6×3 の数などで、ふえてしまっています。xが小さくなると、yも小さくなります。",
  "math_g5_hand_proportion_011":"xが３から９へ、9÷3＝3倍になっています。比例では、yも３倍になるので、5×3＝15です。このように、倍で考えるとかんたんです。\n\nほかの 選択肢\n・「8」…８は、5＋3 のたし算です。比例は、かけ算の関係です。\n・「11」…11は、xがふえた６を、yにそのままたした数、5＋6 です。比例では、yも３倍になります。\n・「30」…30は、5×6 の数です。xは６倍ではなく、３倍になっています。",
  "math_g5_hand_proportion_012":"針金３mが12gなので、１mの重さは 12÷3＝４gです。７mでは 4×7＝28gです。針金の重さは、長さに比例しています。\n\nほかの 選択肢\n・「36」…36は、12×3 の数です。７mの重さを求めるには、１mの重さに７をかけます。\n・「16」…16は、12＋4 のたし算です。比例の関係は、かけ算で考えます。\n・「21」…21は、3×7 の数で、長さの３mと７mをかけた数です。重さは28gです。",
  "math_g5_hand_proportion_013":"紙のまい数が変わると、厚さも同じ割合で変わります。1まいの厚さは 2 ÷ 10＝0.2mm なので、35まいでは 0.2 × 35＝7mm です。（35まいは10まいの3.5倍なので、2 × 3.5＝7 でも求められます。）\n\nほかの 選択肢\n・「3.5」…35 ÷ 10 のように、まい数どうしをわった数です。答えは厚さ（mm）なので、まい数をわってもちがいます。\n・「70」…10まいの厚さ2mmに35をかけた数です。35まいは10まいの3.5倍なので、2mmの35倍にはなりません。\n・「12」…10＋2 のようなたし算で出る数です。比例は、たし算でなく「何倍か」で考えます。",
  "math_g5_hand_proportion_014":"比例は、xが2倍、3倍…になると、yも2倍、3倍…になる関係です。毎分同じ量ずつ水を入れると、時間が2倍になれば水の量も2倍になるので、比例しています。\n\nほかの 選択肢\n・「60ページの本を読んだページ数xとのこりのページ数y」…y＝60－x の関係です。\n・「たて５cmの長方形の横x cmとまわりの長さy cm」…まわりの長さは（5＋x）×2 です。\n・「人の年れいx才と体重ykg」…年れいが2倍になっても体重は2倍になりません。",
  "math_g5_hand_proportion_015":"xが2から4になると2倍です。比例では、yも同じ2倍になるので、9 × 2＝18 です。\n\nほかの 選択肢\n・「11」…9＋2 のたし算で出る数です。比例は、たし算ではなく、倍で考えます。\n・「13」…9＋4 のたし算で出る数です。xは2ふえただけで、4ふえたわけではありません。\n・「36」…9 × 4 の答えです。xは2から4で2倍になっただけなので、yを4倍にしてはいけません。",
  "math_g5_hand_proportion_016":"y＝□×x の□は、y÷x で求められます。14 ÷ 4＝3.5 なので、y＝3.5×x です。たしかめると、3.5 × 4＝14 になります。\n\nほかの 選択肢\n・「3」…14÷4＝3.5 の小数部分を切りすてた数です。3 × 4＝12 で、14にならないのでちがいます。\n・「4」…xの値の4をそのまま入れた数です。4 × 4＝16 で、14にならないのでちがいます。\n・「7」…14を2でわった数です。7 × 4＝28 で、14にならないのでちがいます。",
  "math_g5_hand_proportion_017":"水の量＝20×時間 の関係です。時間は、水の量÷20 で求められるので、120 ÷ 20＝6 です。たしかめると、20 × 6＝120 になります。\n\nほかの 選択肢\n・「4」…20 × 4＝80Lで、120Lに足りないのでちがいます。\n・「5」…20 × 5＝100Lで、120Lに足りないのでちがいます。\n・「12」…20 × 12＝240Lで、多すぎます。120÷20 の答えは12ではありません。",
  "math_g5_hand_proportion_018":"道のり＝速さ×時間 です。時間が3.5時間なので、48 × 3.5＝168km 進みます。（48 × 3＝144 に、半時間の24をたしても 168 です。）\n\nほかの 選択肢\n・「144」…48 × 3 の答えです。3.5時間のうち、半時間（0.5時間）分をたしわすれた数です。\n・「192」…48 × 4 の答えです。3.5時間を4時間として計算してしまった数なので、多すぎます。\n・「156」…48 × 3.25 の答えです。3.25時間（3時間15分）のときの道のりで、3.5時間ではありません。",
  "math_g5_hand_proportion_019":"紙1まいの重さは 450 ÷ 100＝4.5g です。240まいでは 4.5 × 240＝1080g になります。（240まいは100まいの2.4倍なので、450 × 2.4＝1080 でも求められます。）\n\nほかの 選択肢\n・「590」…450＋140 のようにたし算で考えた数です。重さは、まい数の倍に合わせて何倍にもなります。\n・「540」…450 に 90 をたした数のようです。240まいは100まいの2.4倍なので、重さも2.4倍になります。\n・「1800」…450 × 4 の答えです。240まいは100まいの4倍ではなく、2.4倍です。",
  "math_g5_hand_proportion_020":"（4，10）を通る比例なので、yはxの 10 ÷ 4＝2.5 倍です。y＝2.5×x に x＝6 を入れると、2.5 × 6＝15 です。\n\nほかの 選択肢\n・「12」…10＋2 のようにたし算で考えた数です。比例は、たし算でなく倍で考えます。\n・「16」…10＋6 のたし算で出る数です。xの6をそのままたしても、yにはなりません。\n・「24」…4 × 6 の答えです。xどうしをかけた数で、yを求める式になっていません。",
  "math_g5_hand_proportion_021":"xが2から5になると 5 ÷ 2＝2.5倍です。比例では、yも2.5倍になるので、8 × 2.5＝20 です。\n\nほかの 選択肢\n・「11」…8＋3 のたし算で出る数です。xが3ふえたからと、yに3をたすのはまちがいです。\n・「13」…8＋5 のたし算で出る数です。比例は、たし算でなく倍で考えます。\n・「40」…8 × 5 の答えです。xは5倍ではなく2.5倍になっているので、多すぎます。",
  "math_g5_hand_proportion_022":"地図上のきょりと実さいのきょりは比例します。1cmが5kmなので、7.5cmでは 5 × 7.5＝37.5km です。\n\nほかの 選択肢\n・「12.5」…5＋7.5 のたし算で出る数です。地図上の1cmが5kmなら、7.5cmは5kmの7.5倍です。\n・「35」…5 × 7＝35 で、0.5cm分の2.5kmをたしわすれた数です。\n・「40」…5 × 8＝40 で、7.5cmを8cmとして計算した数です。",
  "math_g5_hand_speed_001":"速さ＝道のり÷時間 です。2時間で100km なので、100 ÷ 2＝50。1時間に50km進む、時速50kmです。\n\nほかの 選択肢\n・「98」…100－2 のひき算で出る数です。速さは、ひき算では求められません。\n・「102」…100＋2 のたし算で出る数です。速さは道のり÷時間で求めます。\n・「200」…100 × 2 の答えです。これは、同じ速さで2倍の時間走ったときの道のりです。",
  "math_g5_hand_speed_002":"道のり＝速さ×時間 です。分速60mで5分なので、60 × 5＝300m です。\n\nほかの 選択肢\n・「3000」…60 × 50 の答えです。時間が5分なので、10倍も多くなってしまいます。\n・「240」…60 × 4 の答えです。4分間歩いたときの道のりです。\n・「360」…60 × 6 の答えです。6分間歩いたときの道のりです。",
  "math_g5_hand_speed_003":"速さは、1時間・1分・1秒など、単位の時間に進む道のりです。だから、道のりを時間でわって、速さ＝道のり÷時間 で求めます。\n\nほかの 選択肢\n・「道のり×時間」…「速さ×時間」の形は、道のりを求める式です。\n・「時間÷道のり」…1kmあたり何時間かかるか、のような数を表す式です。速さは、道のりを時間でわります。\n・「道のり－時間」…道のり（kmなど）から時間（時間など）はひけません。",
  "math_g5_hand_speed_004":"道のり＝速さ×時間 です。秒速5mで10秒間なので、5 × 10＝50m 進みます。\n\nほかの 選択肢\n・「15」…5＋10 のたし算で出る数です。道のりは、速さに時間をかけます。\n・「500」…5 × 100 の答えです。時間は10秒なので、10倍も多くなってしまいます。\n・「25」…5 × 5 の答えです。10秒間ではなく、5秒間走ったときの道のりです。",
  "math_g5_hand_speed_005":"道のり＝速さ×時間 です。時速40kmで3時間なので、40 × 3＝120km 進みます。\n\nほかの 選択肢\n・「80」…40 × 2 の答えです。2時間走ったときの道のりです。\n・「160」…40 × 4 の答えです。4時間走ったときの道のりです。\n・「1200」…40 × 30 の答えです。時間が3時間なので、10倍も多くなってしまいます。",
  "math_g5_hand_speed_006":"分速＝道のり÷時間 です。150mを3分で歩いたので、150 ÷ 3＝50。分速50mです。\n\nほかの 選択肢\n・「450」…150 × 3 の答えです。速さを求めるときは、かけ算ではなくわり算を使います。\n・「75」…150 ÷ 2 の答えです。3分でなく2分で歩いた速さです。\n・「153」…150＋3 のたし算で出る数です。速さは、道のりを時間でわって求めます。",
  "math_g5_hand_speed_007":"時速54kmは、1時間に54km＝54000m 進む速さです。1時間は60分なので、54000 ÷ 60＝900。1分間では900m進み、分速900mです。\n\nほかの 選択肢\n・「90」…54000を600でわった数です。1時間は60分なので、600でわってはいけません。\n・「540」…54000を100でわった数です。分速に直すときは、60でわります。\n・「3240」…54 × 60 の答えです。時速を分速に直すときは、60をかけずに、60でわります。",
  "math_g5_hand_speed_008":"秒速10mは、1秒に10m進む速さです。1時間は60 × 60＝3600秒なので、1時間に 10 × 3600＝36000m＝36km 進みます。時速36kmです。\n\nほかの 選択肢\n・「3.6」…36000mをkmに直すとき、1000でなく10000でわってしまった数です。位が1つずれています。\n・「360」…36000を100でわった数です。1km＝1000m なので、1000でわります。\n・「60」…1分＝60秒の「60」を、そのまま答えにした数です。時速にするには、1時間＝3600秒を使います。",
  "math_g5_hand_speed_009":"時間＝道のり÷速さ です。240kmを時速60kmで進むので、240 ÷ 60＝4時間です。たしかめると、60 × 4＝240 になります。\n\nほかの 選択肢\n・「0.25」…60÷240 のように、わる数とわられる数を逆にした数です。時間は、道のり÷速さです。\n・「40」…240 ÷ 6 のように、位をまちがえた数です。60 × 40＝2400 で、240になりません。\n・「5」…60 × 5＝300kmで、240kmより長すぎます。",
  "math_g5_hand_speed_010":"1.2km＝1200m です。時間＝道のり÷速さ なので、1200 ÷ 80＝15分です。単位をmにそろえてから計算するのがコツです。\n\nほかの 選択肢\n・「150」…12000mで計算してしまった数です。1.2km＝1200m で、1.2kmを12000mとしてはいけません。\n・「1.5」…位が1つずれた数です。80 × 1.5＝120m で、1200mにはなりません。\n・「12」…80 × 12＝960m で、1200mに足りません。",
  "math_g5_hand_speed_011":"速さをくらべるときは、単位をそろえます。時速30km＝30000m÷60＝分速500m です。分速400mの犬ぞりより速いのは、雪上車です。\n\nほかの 選択肢\n・「犬ぞり」…犬ぞりは分速400mで、雪上車の分速500mより遅いです。\n・「同じ速さ」…分速500mと分速400mは同じ速さではありません。\n・「比べられない」…時速と分速でも、単位をそろえれば速さはくらべられます。",
  "math_g5_hand_speed_012":"時速48kmは1時間の速さですが、走ったのは30分です。30分＝0.5時間なので、48 × 0.5＝24km 進みます。\n\nほかの 選択肢\n・「96」…48 × 2 の答えです。30分を2時間としてしまった数で、多すぎます。\n・「48」…1時間分の道のりです。30分は1時間の半分なので、半分の24kmになります。\n・「12」…48 × 0.25 の答えです。0.25時間は15分なので、30分ではありません。",
  "math_g5_hand_speed_013":"道のり＝速さ×時間 です。秒速340mで3秒間なので、340 × 3＝1020m 進みます。\n\nほかの 選択肢\n・「680」…340 × 2 の答えです。3秒でなく、2秒間に進む道のりです。\n・「1360」…340 × 4 の答えです。3秒でなく、4秒間に進む道のりです。\n・「3400」…340 × 10 の答えです。3秒間なので、多すぎます。",
  "math_g5_hand_speed_014":"時速72kmは、1時間に72000m進む速さです。1時間＝3600秒なので、72000 ÷ 3600＝20。秒速20mです。\n\nほかの 選択肢\n・「1.2」…72÷60 の答えのようです。これは分速をkmで表した数で、秒速（m）ではありません。\n・「200」…位が1つずれた数です。1秒に200m進むなら、1時間に720kmも進んでしまいます。\n・「36」…72÷2 の答えです。時速を秒速に直すときは、半分にするのではなく、3600秒でわります。",
  "math_g5_hand_speed_015":"行きの道のりは 6 × 2＝12km です。帰りは同じ道のりを時速4kmで歩くので、12 ÷ 4＝3時間。往復では 2＋3＝5時間です。\n\nほかの 選択肢\n・「2.4」…行きだけで2時間かかっているので、往復が2.4時間になるはずはありません。\n・「3」…帰りにかかった時間だけです。行きの2時間もたします。\n・「6」…行きの2時間に、帰りの時速の4をたした数のようです。4は速さで、時間ではありません。",
  "math_g5_hand_speed_016":"2.4km＝2400m です。時間＝道のり÷速さ なので、2400 ÷ 60＝40分です。単位をmにそろえるのがコツです。\n\nほかの 選択肢\n・「4」…2.4÷60 のように、kmのまま計算した数のようです。分速はmなので、mにそろえます。\n・「400」…位が1つずれた数です。60 × 400＝24000m で、2400mより長すぎます。\n・「60」…分速の「60」をそのまま答えにした数です。60分歩くと3600mも進みます。",
  "math_g5_hand_speed_017":"平均の速さ＝全体の道のり÷全体の時間 です。前半は 40 × 2＝80km、後半は 60 × 3＝180km で、全部で 260km。260 ÷ 5＝52 なので、時速52kmです。\n\nほかの 選択肢\n・「50」…40と60の平均 （40＋60）÷2 の答えです。走った時間の長さがちがうので、速さを単純に平均してはいけません。\n・「100」…40＋60 の答えです。速さの合計では、平均の速さになりません。\n・「260」…全体の道のり260kmです。これを時間の5時間でわって、速さにします。",
  "math_g5_hand_speed_018":"3分＝180秒です。秒速15mで180秒進むので、15 × 180＝2700m です。単位の時間（秒）をそろえるのがコツです。\n\nほかの 選択肢\n・「450」…15 × 30 の答えです。3分を30秒としてしまった数で、少なすぎます。\n・「900」…15 × 60 の答えです。1分間（60秒）に進む道のりです。3分ではありません。\n・「8100」…15 × 3 × 180 の答えです。3分を「3」と「180秒」の両方でかけた数で、多すぎます。",
  "math_g5_hand_speed_019":"1時間は60分です。分速250mで60分進むので、250 × 60＝15000m＝15km です。kmに直して答えます。\n\nほかの 選択肢\n・「15000」…15000m のまま答えにした数です。問いはkmで聞いているので、1000でわって直します。\n・「150」…位が1つずれた数です。250 × 60＝15000m＝15km です。\n・「4.2」…15000÷3600 のようにわった数のようです。分速に60をかけるのに、わってしまっています。",
  "math_g5_hand_speed_020":"時速90kmは、1時間に90000m進む速さです。1時間は60分なので、90000 ÷ 60＝1500。分速1500mです。\n\nほかの 選択肢\n・「150」…位が1つずれた数です。分速150mなら、1時間に9000mしか進みません。\n・「5400」…90 × 60 の答えです。時速を分速に直すときは、かけずに60でわります。\n・「15000」…位が1つ多い数です。分速15000mなら、1時間に900000mも進んでしまいます。",
  "math_g5_hand_unit_001":"1m²あたりの人数は、人数 ÷ 面積 で求めます。6 ÷ 2＝3 なので、1m²あたり3人です。\n\nほかの 選択肢\n・「4」…6－2 のひき算で出る数です。1m²あたりの数は、わり算で求めます。\n・「8」…6＋2 のたし算で出る数です。1m²あたりの人数は、人数を面積でわります。\n・「2」…面積の2をそのまま答えにした数です。3人×2m²にして6人にならないので、ちがいます。",
  "math_g5_hand_unit_002":"1人あたりの広さは、面積 ÷ 人数 で求めます。6 ÷ 3＝2 なので、1人あたり2m²です。\n\nほかの 選択肢\n・「3」…人数の3をそのまま答えにした数です。1人あたり3m²だと、3人で9m²になってしまいます。\n・「0.5」…3 ÷ 6 の答えで、1m²あたりの人数です。問いは、1人あたりの広さなので、わる数とわられる数が逆です。\n・「4」…1人あたり4m²だと、3人で12m²になり、6m²にはなりません。",
  "math_g5_hand_unit_003":"人口密度は、1km²あたりに何人住んでいるかを表す数です。人口を面積でわるので、人口密度＝人口÷面積 です。\n\nほかの 選択肢\n・「面積÷人口」…面積÷人口 は、1人あたりの面積を表す式です。人口密度とは逆です。\n・「人口×面積」…人口と面積をかけても、1km²あたりの人数にはなりません。\n・「人口－面積」…人口（人）から面積（km²）はひけません。単位がちがうからです。",
  "math_g5_hand_unit_004":"1分間あたりの量は、全体の量 ÷ 時間 です。15 ÷ 3＝5 なので、1分間あたり5Lです。\n\nほかの 選択肢\n・「18」…15＋3 のたし算で出る数です。1分間あたりの量は、わり算で求めます。\n・「3」…時間の3をそのまま答えにした数です。1分間に3Lなら、3分間では9Lです。\n・「12」…15－3 のひき算で出る数です。1あたりの量は、わり算で求めます。",
  "math_g5_hand_unit_005":"1m²あたりの数は、全体の数 ÷ 面積 です。12 ÷ 4＝3 なので、1m²あたり3こです。\n\nほかの 選択肢\n・「4」…畑の面積の4をそのまま答えにした数です。1m²あたり4こなら、4m²で16こになります。\n・「8」…12－4 のひき算で出る数です。1あたりの数は、わり算で求めます。\n・「6」…1m²あたり6こなら、4m²で24こになり、12こにはなりません。",
  "math_g5_hand_unit_006":"1Lあたりに走るきょりは、きょり ÷ ガソリンの量 です。20 ÷ 10＝2 なので、1Lあたり2kmです。\n\nほかの 選択肢\n・「0.5」…10 ÷ 20 の答えで、1kmあたりに使うガソリンの量です。わる数とわられる数が逆です。\n・「4」…20 ÷ 5 のような計算でできる数です。1Lあたり4kmなら、10Lで40kmも走ってしまいます。\n・「5」…1Lあたり5kmなら、10Lで50km走ることになり、20kmではありません。",
  "math_g5_hand_unit_007":"1m²あたりの人数にそろえてくらべます。Ａは 4÷6＝0.666…人、Ｂは 5÷8＝0.625人 なので、正解はＡです。Ａのほうが1m²あたりの人数が多いです。\n\nほかの 選択肢\n・「Ｂ」…Ｂは1m²あたり0.625人で、Ａの0.666…人より少ないです。\n・「同じ」…Ａは0.666…人、Ｂは0.625人で、同じではありません。\n・「比べられない」…広さと人数がちがっても、1m²あたりにそろえれば、くらべられます。",
  "math_g5_hand_unit_008":"人口密度＝人口÷面積 です。600 ÷ 200＝3 なので、1km²あたり3人です。\n\nほかの 選択肢\n・「0.33」…200 ÷ 600 の答えで、1人あたりの面積です。わる数とわられる数が逆です。\n・「30」…位が1つずれた数です。1km²あたり30人なら、200km²では6000人になります。\n・「4」…1km²あたり4人なら、200km²では800人になり、600人にはなりません。",
  "math_g5_hand_unit_009":"1mあたりのねだんは、代金 ÷ 長さ です。600 ÷ 5＝120 なので、1mあたり120円です。\n\nほかの 選択肢\n・「60」…600 ÷ 10 の答えのようです。1mあたり60円なら、5mで300円にしかなりません。\n・「150」…600 ÷ 4 の答えのようです。1mあたり150円なら、5mで750円になります。\n・「240」…600 ÷ 2.5 の答えのようです。1mあたり240円なら、5mで1200円になります。",
  "math_g5_hand_unit_010":"1Lあたりに走るきょりは、きょり ÷ ガソリンの量 です。320 ÷ 16＝20 なので、1Lあたり20kmです。\n\nほかの 選択肢\n・「16」…ガソリンの量の16をそのまま答えにした数です。1Lあたり16kmなら、16Lで256kmしか走れません。\n・「40」…320 ÷ 8 の答えのような数です。1Lあたり40kmなら、16Lで640kmも走ります。\n・「24」…1Lあたり24kmなら、16Lで384km走ることになり、320kmにはなりません。",
  "math_g5_hand_unit_011":"1m²あたり8kgとれるので、5m²では 8 × 5＝40kg とれます。1あたりの量 × いくつ分 で求めます。\n\nほかの 選択肢\n・「13」…8＋5 のたし算で出る数です。いくつ分かをかけて求めます。\n・「45」…40kgに5をたした数です。8×5 の答えにたし算をしてはいけません。\n・「35」…40kgから5をひいた数です。かけ算の答えだけで十分です。",
  "math_g5_hand_unit_012":"1こあたりのねだんは、代金 ÷ 個数 です。480 ÷ 12＝40 なので、1こあたり40円です。\n\nほかの 選択肢\n・「36」…12 × 3 の答えのようです。1こ36円なら、12こで432円になり、480円にはなりません。\n・「400」…位が1つずれた数です。1こ400円なら、12こで4800円にもなります。\n・「60」…1こ60円なら、12こで720円になり、480円にはなりません。",
  "math_g5_hand_unit_013":"人口＝人口密度×面積 です。1km²あたり50人の島が12km²あるので、50 × 12＝600人です。\n\nほかの 選択肢\n・「60」…位が1つ少ない数です。600人が正しいので、60人では少なすぎます。\n・「6000」…位が1つ多い数です。50 × 12 は600で、6000にはなりません。\n・「500」…500人を12km²でわると、1km²あたり約41.7人になり、50人ではありません。",
  "math_g5_hand_unit_014":"人口密度＝人口÷面積 でくらべます。町Ａは 200÷50＝4人、町Ｂは 150÷30＝5人 なので、町Ｂのほうが高いです。\n\nほかの 選択肢\n・「町Ａ」…町Ａは1km²あたり4人で、町Ｂの5人より少ないです。\n・「同じ」…町Ａは4人、町Ｂは5人で、同じではありません。\n・「比べられない」…人口も面積もちがっても、1km²あたりにそろえれば、くらべられます。",
  "math_g5_hand_unit_015":"町Ａは 4800÷60＝80人、町Ｂは 3600÷40＝90人。人口密度の差は 90－80＝10人です。\n\nほかの 選択肢\n・「80」…町Ａの人口密度そのものです。差を求めるには、町Ｂの90人とのひき算が必要です。\n・「90」…町Ｂの人口密度そのものです。差を求めるには、町Ａの80人とのひき算が必要です。\n・「1200」…人口の差（4800－3600）です。人口密度の差を求めるときは、面積でわってからひきます。",
  "math_g5_hand_unit_016":"必要なガソリンの量は、きょり ÷ 1Lあたりに走るきょり です。45 ÷ 15＝3 なので、3Lです。\n\nほかの 選択肢\n・「0.33」…15 ÷ 45 の答えです。わる数とわられる数が逆になっています。\n・「30」…45－15 のひき算で出る数です。何Lかは、わり算で求めます。\n・「5」…5Lだと、15 × 5＝75km 走れてしまい、45kmより多いです。",
  "math_g5_hand_unit_017":"3mで480円なので、1mは 480÷3＝160円。5mでは 160×5＝800円です。まず1あたりを求めてから、いくつ分かをかけます。\n\nほかの 選択肢\n・「160」…1mあたりのねだんです。5m分にするには、さらに5をかけます。\n・「2400」…480 × 5 の答えです。480円は3mの代金なので、5倍するのは5mではなく15mの代金です。\n・「1440」…480 × 3 の答えです。5mの代金を求めるのに、3倍してしまった数です。",
  "math_g5_hand_unit_018":"面積＝人口÷人口密度 です。1260 ÷ 90＝14km² です。たしかめると、90 × 14＝1260 になります。\n\nほかの 選択肢\n・「1.4」…位が1つずれた数です。90 × 1.4＝126人で、1260人になりません。\n・「140」…位が1つずれた数です。90 × 140＝12600人で、多すぎます。\n・「16」…90 × 16＝1440人で、1260人より多いです。",
  "math_g5_hand_unit_019":"1人あたりのじょうの数は、じょうの数÷人数です。６じょうの部屋は6÷8＝0.75、８じょうの部屋は8÷10＝0.8。正解は８じょうの部屋で、1人あたりの広さが広いです。\n\nほかの 選択肢\n・「６じょうの部屋」…６じょうの部屋は1人あたり0.75じょうで、８じょうの部屋の0.8じょうよりせまいです。\n・「同じ」…0.75じょうと0.8じょうは同じではありません。\n・「比べられない」…部屋の広さも人数もちがっても、1人あたりにそろえれば、くらべられます。",
  "math_g5_hand_unit_020":"1m²あたり 35÷10＝3.5kg とれる畑です。18m²では、3.5 × 18＝63kg とれます。\n\nほかの 選択肢\n・「53」…35＋18 のたし算で出る数です。畑が広くなったら、とれる量は倍で考えます。\n・「35」…10m²分の量そのものです。18m²ならもっと多くとれます。\n・「630」…35 × 18 の答えです。35kgは10m²分なので、1m²あたり3.5kgを求めてからかけます。",
  "math_g5_hand_unit_021":"人口密度＝人口÷面積 です。1000 ÷ 2.5＝400 なので、1km²あたり400人です。\n\nほかの 選択肢\n・「2500」…1000 × 2.5 の答えです。人口密度は、人口を面積でわって求めます。\n・「4000」…位が1つ多い数です。1km²あたり4000人なら、2.5km²に10000人も住むことになります。\n・「1000」…人口の1000人をそのまま答えにした数です。1km²あたりにするには、面積の2.5でわります。",
  "math_g5_hand_volume_001":"直方体の体積＝たて×横×高さ です。3 × 4 × 2＝24cm³ です。\n\nほかの 選択肢\n・「9」…3＋4＋2 のたし算で出る数です。体積は、たし算ではなく、3つの長さをかけて求めます。\n・「12」…3 × 4 の答えで、底の面積（cm²）です。高さの2をかけていません。\n・「48」…24の2倍です。高さの2を二重にかけてしまった数です。",
  "math_g5_hand_volume_002":"立方体は、たて・横・高さが同じ長さです。体積＝1辺×1辺×1辺 なので、5 × 5 × 5＝125cm³ です。\n\nほかの 選択肢\n・「150」…5 × 5 × 6 の答えで、表面積（cm²）です。体積ではありません。\n・「75」…5 × 5 × 3 の答えです。高さを3としてしまった数です。\n・「250」…5 × 5 × 10 の答えです。高さを10としてしまった数です。",
  "math_g5_hand_volume_003":"直方体の体積は、たて×横×高さ です。1cm³の立方体が、たてに何こ、横に何こ、高さに何だんならぶかを考えると、3つの数のかけ算になります。\n\nほかの 選択肢\n・「たて×横」…たて×横 は、長方形の面積を求める式です。\n・「（たて＋横＋高さ）×２」…辺の長さをたして2倍した数で、体積ではありません。体積は、3つの長さをかけて求めます。\n・「たて＋横＋高さ」…3つの長さをたし算しても、体積にはなりません。",
  "math_g5_hand_volume_004":"1cm³の積み木が、1だん5 × 3＝15こあり、2だんなので 15 × 2＝30こ。体積は30cm³です。\n\nほかの 選択肢\n・「10」…5＋3＋2 のたし算で出る数です。積み木の数は、かけ算で求めます。\n・「15」…5 × 3 の答えで、1だんの積み木の数です。2だん分をかけていません。\n・「60」…30の2倍です。2だんを二重にかけてしまった数です。",
  "math_g5_hand_volume_005":"1m＝100cm なので、1辺が1mの立方体の体積は、100 × 100 × 100＝1000000cm³ です。1m³＝1000000cm³ とおぼえましょう。\n\nほかの 選択肢\n・「1000」…1000は、1Lのcm³の数です。1m³はそれより1000倍も大きいです。\n・「10000」…100 × 100 の答えで、1m²のcm²の数です。体積は、さらに100をかけます。\n・「100000」…位が1つ足りない数です。100 × 100 × 100 は1000000です。",
  "math_g5_hand_volume_006":"1Lは、1辺10cmの立方体の体積です。10 × 10 × 10＝1000cm³ なので、1L＝1000cm³ です。\n\nほかの 選択肢\n・「100」…10 × 10 の答えで、面積（cm²）です。高さの10もかけます。\n・「10」…1辺の長さの10そのものです。体積は、3つの長さをかけます。\n・「10000」…位が1つ多い数です。10 × 10 × 10 は1000で、10000にはなりません。",
  "math_g5_hand_volume_007":"立方体の体積＝1辺×1辺×1辺 です。2 × 2 × 2＝8m³ です。\n\nほかの 選択肢\n・「4」…2 × 2 の答えで、面積（m²）です。もう一度2をかけて体積にします。\n・「6」…2 × 3 のような計算の数です。立方体は、1辺を3回かけます。\n・「12」…2 × 6 の答えです。面の数の6をかけても、体積にはなりません。",
  "math_g5_hand_volume_008":"直方体の体積＝たて×横×高さ です。10 × 6 × 3＝180cm³ です。\n\nほかの 選択肢\n・「60」…10 × 6 の答えで、底の面積（cm²）です。高さの3をかけていません。\n・「90」…10 × （6＋3） の答えです。6と3をたし算してしまいました。たて×横×高さ とかけ算します。\n・「360」…180の2倍です。高さを二重にかけてしまった数です。",
  "math_g5_hand_volume_009":"立方体の体積＝1辺×1辺×1辺 です。4 × 4 × 4＝64cm³ です。\n\nほかの 選択肢\n・「16」…4 × 4 の答えで、面積（cm²）です。もう一度4をかけます。\n・「32」…4 × 4 × 2 の答えです。高さを2としてしまった数です。立方体の高さは1辺と同じ4cmです。\n・「48」…4 × 4 × 3 の答えです。高さを3としてしまった数です。立方体の高さは1辺と同じ4cmです。",
  "math_g5_hand_volume_010":"内のりの体積が容積です。20 × 30 × 15＝9000cm³。1L＝1000cm³ なので、9000 ÷ 1000＝9L です。\n\nほかの 選択肢\n・「90」…位が1つずれた数です。9000cm³ を100でわってしまうと90になります。1Lは1000cm³ なので、1000でわります。\n・「18」…9Lの2倍です。9000cm³ を500cm³ ずつに分けてしまったような数で、1L＝1000cm³ に合いません。\n・「4.5」…9Lの半分です。9000cm³ は、1000cm³ が9つ分なので9Lです。",
  "math_g5_hand_volume_011":"直方体の高さ＝体積 ÷（たて×横）です。たて×横＝6 × 5＝30cm² なので、120 ÷ 30＝4cm です。\n\nほかの 選択肢\n・「3」…高さ3cmだと、体積は 30 × 3＝90cm³ で、120cm³にはなりません。\n・「5」…高さ5cmだと、体積は 30 × 5＝150cm³ で、120cm³にはなりません。\n・「6」…高さ6cmだと、体積は 30 × 6＝180cm³ で、120cm³にはなりません。",
  "math_g5_hand_volume_012":"立方体の1辺をaとすると、a×a×a＝27 です。3 × 3 × 3＝27 なので、1辺は3cmです。\n\nほかの 選択肢\n・「9」…27 ÷ 3＝9 の答えです。同じ数を3回かけた数が27になる数を探します。9 × 9 × 9 は729です。\n・「6」…6 × 6 × 6＝216 で、27より大きいです。\n・「4」…4 × 4 × 4＝64 で、27より大きいです。",
  "math_g5_hand_volume_013":"水の体積は、底の面積 × 深さ です。40 × 50 × 10＝20000cm³。1L＝1000cm³ なので、20000 ÷ 1000＝20L です。\n\nほかの 選択肢\n・「200」…位が1つずれた数です。20000cm³ は20Lです。200Lは20000を100でわった数です。\n・「40」…20Lの2倍です。底の面積の計算をまちがえた数です。40 × 50 は2000です。\n・「10」…深さの10をそのまま答えにした数です。体積を求めて、Lに直します。",
  "math_g5_hand_volume_014":"1m³＝1000000cm³ で、1L＝1000cm³ です。だから、1000000 ÷ 1000＝1000 で、1m³＝1000L です。\n\nほかの 選択肢\n・「100」…1m＝100cm なので、100と考えやすいですが、体積は3つの長さをかけるので、もっと大きくなります。\n・「10」…1m³ は、1Lの10倍ではなく、1000倍です。\n・「10000」…1m³の1000000cm³ を100でわってしまうと10000になりますが、1Lは1000cm³ なので、1000でわります。",
  "math_g5_hand_volume_015":"6L＝6000cm³ です。底の面積は 30 × 20＝600cm² なので、深さ＝体積 ÷ 底の面積＝6000 ÷ 600＝10cm です。\n\nほかの 選択肢\n・「3」…6000÷2000 のような計算でできる数です。深さ3cmだと、水は 600 × 3＝1800cm³ にしかなりません。\n・「20」…横の長さの20をそのまま答えにした数です。深さ20cmなら、水は12000cm³（12L）になります。\n・「6」…水の量の6Lをそのまま答えにした数です。単位がLとcmでちがうので、cm³に直して計算します。",
  "math_g5_hand_volume_016":"積み木1この1辺は2cmなので、たてに 8÷2＝4こ、横に 6÷2＝3こ、高さに 4÷2＝2だん入ります。4 × 3 × 2＝24こです。\n\nほかの 選択肢\n・「48」…箱の体積192cm³ を、積み木1こを4cm³ と考えてわった数です。1辺2cmの積み木は 2 × 2 × 2＝8cm³ なので、192÷8＝24 です。\n・「12」…24の半分です。高さのだんの数を1だんとして、4 × 3 × 1 と計算した数です。高さ4cmは2cmの積み木で2だんです。\n・「36」…4 × 3 × 3 の答えです。高さを3だんとした数です。4÷2＝2だんです。",
  "math_g5_hand_volume_017":"直方体の体積＝たて×横×高さ です。2 × 3 × 1＝6m³ です。\n\nほかの 選択肢\n・「5」…2＋3 のたし算で出る数のようです。体積は、かけ算で求めます。\n・「12」…2 × 3 × 2 の答えです。高さは1mなので、1をかけます。\n・「3」…3 × 1 の答えです。たての2mもかけて、2 × 3 × 1 とします。",
  "math_g5_hand_volume_018":"10 × 10 × 10＝1000cm³ です。1L＝1000cm³ なので、容積は1Lです。\n\nほかの 選択肢\n・「10」…位が1つずれた数です。10Lなら10000cm³ です。\n・「1000」…1000cm³ をLに直さずに、そのまま答えにした数です。1000cm³ は1Lです。\n・「0.1」…0.1Lは100cm³ です。ここは1000cm³ なので、0.1Lではありません。",
  "math_g5_hand_volume_019":"3cmの立方体を2つ横にならべると、たて3cm、横6cm、高さ3cmの直方体になります。3 × 6 × 3＝54cm³ です。立方体1つの体積27cm³ の2倍と考えても、54です。\n\nほかの 選択肢\n・「27」…立方体1つ分の体積です。2つならべたので、2倍になります。\n・「18」…3 × 3 × 2 の答えです。横の長さは3cmでなく、3 × 2＝6cm です。\n・「108」…54の2倍です。2つを二重に数えてしまった数です。",
  "math_g5_hand_volume_020":"板の厚さが1cmで、ふたがありません。たて・横は両がわの板の分を2cm引いて、12－2＝10cm、10－2＝8cm。高さは底の板の分だけ引いて、8－1＝7cm です。10 × 8 × 7＝560cm³ です。\n\nほかの 選択肢\n・「960」…外のりの体積 12 × 10 × 8 です。板の厚さを引いていません。\n・「480」…高さを2cm引いて、10 × 8 × 6 を計算した数です。ふたがないので、高さは底の板の1cmだけを引きます。\n・「720」…内のりの3つの長さを正しく求められていない数です。たて10cm、横8cm、高さ7cm をかけます。",
  "math_g5_hand_volume_021":"40 × 30 × 20＝24000cm³ です。1L＝1000cm³ なので、24000 ÷ 1000＝24L にあたります。\n\nほかの 選択肢\n・「240」…位が1つずれた数です。24Lを240Lにすると、10倍になってしまいます。\n・「2.4」…位が1つずれた数です。24000cm³ は2.4Lではなく、24Lです。\n・「48」…24Lの2倍です。24000を500でわってしまったような数です。1Lは1000cm³ です。",
  "math_g5_hand_volume_022":"体積＝たて×横×高さ です。たてだけが2倍になると、3つのかけ算のうち1つだけが2倍になるので、体積も２倍になる、が正解です。\n\nほかの 選択肢\n・「変わらない」…たてが長くなれば体積も大きくなります。変わらないということはありません。\n・「４倍になる」…4倍になるのは、たてと横のように2つの長さを2倍にしたときです。ここは1つだけです。\n・「半分になる」…体積が半分になるのは、たてが半分になったときです。2倍にしたのですから、体積は大きくなります。",
  "math_g5_hand_volume_023":"底面積が分かっている直方体の体積は、底面積 × 高さ で求められます。24 × 5＝120cm³ です。\n\nほかの 選択肢\n・「48」…24の2倍です。高さの5ではなく、2をかけたような数です。\n・「60」…120の半分です。直方体の体積は、半分にしません。24 × 5 のままです。\n・「144」…24 × 6 の答えのような数です。高さは5cmなので、5をかけます。",
  "math_g5_hand_volume_024":"高さ＝体積 ÷ 底面積 です。72 ÷ 18＝4cm です。たしかめると、18 × 4＝72 になります。\n\nほかの 選択肢\n・「3」…18 × 3＝54 で、72になりません。\n・「6」…18 × 6＝108 で、72になりません。\n・「8」…18 × 8＝144 で、72になりません。",
  "math_g5_hand_volume_025":"立方体のたて・横・高さをすべて2倍にすると、体積は 2 × 2 × 2＝8倍になります。たとえば、1辺1cm（体積1cm³）の立方体が、1辺2cm（体積8cm³）になります。\n\nほかの 選択肢\n・「2」…1辺だけが2倍になったときの体積の変化です。3つの長さがすべて2倍になっています。\n・「4」…2 × 2 の答えで、面積の変化です。体積は、さらに2をかけます。\n・「6」…2 × 3 のような計算の数です。体積の変化は、2を3回かけた数です。",
  "math_g5_hand_volume_026":"もとの直方体の体積は 6 × 5 × 4＝120cm³、切り取る立方体は 2 × 2 × 2＝8cm³ です。のこりは 120－8＝112cm³ です。\n\nほかの 選択肢\n・「120」…切り取る前の直方体の体積です。切り取った分の8cm³ をひきます。\n・「128」…120に8をたした数です。切り取ったのですから、ひき算をします。\n・「104」…120から16をひいた数です。切り取った立方体の体積は8cm³ で、16cm³ ではありません。",
  "math_g5_hand_volume_027":"石をしずめると、水面が上がった分の水の体積が、石の体積と同じになります。上がった分は 50 × 40 × 2＝4000cm³ です。\n\nほかの 選択肢\n・「2000」…4000の半分です。水面が上がった高さの2cmを、1cmとして計算した数のようです。\n・「8000」…4000の2倍です。水面が上がった高さは2cmです。\n・「400」…位が1つずれた数です。50 × 40 × 2 は4000です。",
  "math_g5_hand_volume_028":"底の面積は 30 × 20＝600cm² です。氷が1200cm³ なので、水面は 1200 ÷ 600＝2cm 上がります。もとの深さ12cmに2cmをたして、14cm です。\n\nほかの 選択肢\n・「2」…水面が上がった分の高さです。もとの深さの12cmにたして、深さを求めます。\n・「12」…もとの深さそのままです。氷をしずめたので、水面は上がります。\n・「16」…12cmに4cm上がると考えた数です。水面は1200÷600＝2cm 上がります。",
  "math_g5_hand_volume_029":"くっつけた全体の体積は、2つの直方体の体積をたした数です。3 × 4 × 2＝24cm³、3 × 2 × 5＝30cm³ なので、24＋30＝54cm³ です。\n\nほかの 選択肢\n・「24」…1つ目の直方体だけの体積です。2つ目の30cm³ もたします。\n・「30」…2つ目の直方体だけの体積です。1つ目の24cm³ もたします。\n・「60」…2つをたした54より大きい数です。くっつけると、体積は2つの合計と同じ54cm³ です。",
  "math_g5_hand_volume_030":"1辺6cmを、1辺2cmずつに分けるので、たて・横・高さにそれぞれ 6÷2＝3こ ならびます。3 × 3 × 3＝27こできます。\n\nほかの 選択肢\n・「9」…3 × 3 の答えで、1だんの数です。高さに3だんあるので、さらに3をかけます。\n・「18」…3 × 3 × 2 の答えです。高さも3だんなので、2ではなく3をかけます。\n・「54」…27の2倍です。216cm³ を、小さい立方体を4cm³ と考えてわった数です。小さい立方体は 2 × 2 × 2＝8cm³ で、216÷8＝27 です。",
  "math_g5_hand_volume_031":"深さ20cmまでの水の体積は、50 × 30 × 20＝30000cm³＝30L です。毎分3Lずつ入れるので、30 ÷ 3＝10分かかります。\n\nほかの 選択肢\n・「3」…毎分の水の量の3をそのまま答えにした数です。時間は、全体の量÷毎分の量で求めます。\n・「20」…深さの20をそのまま答えにした数です。20分入れると、60Lも入ります。\n・「30」…必要な水の量30Lをそのまま答えにした数です。毎分3Lでわって、時間にします。",
  "math_g5_hand_volume_032":"24L＝24000cm³ です。底の面積は 40 × 30＝1200cm² なので、深さ＝24000 ÷ 1200＝20cm です。\n\nほかの 選択肢\n・「8」…24000÷3000 のような計算でできる数です。深さ8cmなら、水は 1200 × 8＝9600cm³ にしかなりません。\n・「12」…深さ12cmなら、水は 1200 × 12＝14400cm³ にしかなりません。\n・「24」…水の量の24Lをそのまま答えにした数です。単位をcm³にそろえて計算します。",
  "math_g5_hand_volume_033":"横＝体積 ÷（たて×高さ）です。4 × 3＝12 なので、48 ÷ 12＝4cm です。\n\nほかの 選択肢\n・「2」…横2cmだと、体積は 4 × 2 × 3＝24cm³ にしかなりません。\n・「6」…横6cmだと、体積は 4 × 6 × 3＝72cm³ になり、48cm³ より大きいです。\n・「12」…たて×高さの12をそのまま答えにした数です。体積の48を12でわります。",
  "math_g5_hand_volume_034":"大きい立方体の体積は 10 × 10 × 10＝1000cm³、くりぬく立方体は 5 × 5 × 5＝125cm³ です。のこりは 1000－125＝875cm³ です。\n\nほかの 選択肢\n・「1000」…くりぬく前の体積です。くりぬいた分の125cm³ をひきます。\n・「750」…1000－250 の答えのようです。くりぬいた立方体の体積は 5 × 5 × 5＝125cm³ です。\n・「500」…くりぬく前の半分です。1辺が半分になると、体積は半分ではなく8分の1になります。",
  "math_g5_hand_volume_035":"50cm＝0.5m です。単位をmにそろえて、2 × 1 × 0.5＝1m³ です。1m³＝1000L なので、水は1000Lです。\n\nほかの 選択肢\n・「2000」…50cmを1mとしてしまった数のようです。50cm＝0.5m です。2 × 1 × 1＝2m³ で、2000Lになってしまいます。\n・「500」…1m³ を500Lとしてしまった数のようです。1m³＝1000L です。\n・「10000」…位が1つ多い数です。1m³＝1000L で、10000Lではありません。",
  "math_g5_percent_001":"割合は、くらべる量÷もとにする量で求めます。くらべる量は、住んでいる30人、もとにする量は、定員の40人です。30÷40＝0.75。割合を{百分率|ひゃくぶんりつ}にするには100倍するので、0.75×100＝75％です。40÷30のように、わる数とわられる数を入れかえないように気をつけましょう。",
  "math_g5_percent_002":"20％引きは、定価の80％で売ることです。800×0.8＝640円です。800×0.2＝160円が安くなる、と考えて、800－160＝640円としても同じです。「20％引き」の答えをまちがえて、160円としないように、気をつけましょう。",
  "math_g5_speed_001":"速さ＝道のり÷時間 です。2時間で36km進んだので、36 ÷ 2＝18。1時間に18km進む、時速18kmです。たしかめると、18 × 2＝36 になります。「時速」を聞かれているので、道のりを時間でわります。かけ算にしないようにしましょう。",
  "math_g5_speed_002":"2時間30分は、30分＝0.5時間なので 2.5時間です。道のり＝速さ×時間 なので、40 × 2.5＝100km 進みます。2時間30分を「2.30時間」と書くまちがいに気をつけましょう。60分で1時間なので、30分は0.5時間です。2時間分の 80km に、30分分の 20km をたしても 100km になります。",
  "math_g5_unit_001":"1Lで15km走るので、4Lでは 15 × 4＝60km 走れます。「1あたりの量×いくつ分」で、全体を求めます。ガソリンが2倍、3倍になれば、走れるきょりも2倍、3倍になります。4Lは1Lの4倍なので、きょりも4倍の60kmです。",
  "math_g5_volume_001":"水の体積は、底の面積 × 水の深さ で求めます。この水そうの底は 50 × 30 なので、50 × 30 × 20＝30000cm³ です。1L＝1000cm³ なので、30000 ÷ 1000＝30L です。水そうの高さ（40cm）は、水が入っている深さではないので使いません。",
  "math_g6_case_001":"3人を1列にならべるときは、先頭の人が3通り、2番目が残りの2人から2通り、最後が1通りです。3 × 2 × 1＝6通りです。書き出すと、ABC、ACB、BAC、BCA、CAB、CBA の6通りです。\n\nほかの 選択肢\n・「3{通|とお}り」…先頭の人の決め方の数だけ数えた数です。2番目、3番目のならべ方もあります。\n・「9{通|とお}り」…3 × 3 の答えです。同じ人を2回使えるとして計算した数です。ならぶ人は重ならないので、2番目は2通りになります。\n・「12{通|とお}り」…3 × 4 のように、4人のならべ方で数えた数です。3人のときは、先頭は3通り、次は2通り、最後は1通りです。",
  "math_g6_circle_001":"円の面積は、半径×半径×円周率 で求めます。5 × 5 × 3.14＝25 × 3.14＝78.5m² です。よくあるまちがいは、2つあります。1つは、5 × 2 × 3.14＝31.4 のように円周の式を使うことです。もう1つは、半径を2回かけずに 5 × 3.14＝15.7 としてしまうことです。「面積」は半径を2回かけます。",
  "math_g6_fraction_001":"分数を整数でわるときは、分母にその整数をかけます。2/3 ÷ 4＝2/(3×4)＝2/12 で、2でわって約分すると 1/6 です。2/3 × 4 のように、かけ算にしないようにしましょう。2/3kgを4人で分けるので、1人分は2/3kgより少なくなります。1/6kg は 2/3kg より少ないので、あっています。約分を忘れて 2/12 と答えるのも、よくあるまちがいです。",
  "math_g6_fraction_002":"1mで 3/4kg なので、2/3m の重さは 3/4 × 2/3 です。分数のかけ算は、分母どうし、分子どうしをかけて、3×2/4×3＝6/12。約分して 1/2kg です。先に約分すると、3と3、2と4が約分できて、1/2 × 1/1＝1/2 とかんたんに計算できます。2/3mは1mより短いので、重さも 3/4kg より軽くなります。",
  "math_g6_inverse_001":"まず道のりを求めます。道のり＝速さ×時間なので、60 × 2＝120km です。時間＝道のり÷速さなので、120 ÷ 40＝3時間です。速さが遅くなると、同じ道のりにかかる時間は長くなります。時速60kmから時速40kmに遅くなったので、2時間より長い3時間になります。60÷40 や 2×40÷60 のように、道のりを求めずに計算するのは、よくあるまちがいです。",
  "math_g6_proportion_001":"同じ太さのロープは、長さと重さが比例します。3mで 120g なので、1mの重さは 120 ÷ 3＝40g です。450g の長さは 450 ÷ 40＝11.25m です。たしかめると、40 × 11.25＝450 になります。450 × 40 のようにかけ算にすると、1mあたりの重さ（g）に、全体の重さ（g）をかけることになり、長さにはなりません。",
  "math_g6_ratio_001":"木材：石材＝3：2 です。木材が 3 から 15 になったので、15 ÷ 3＝5倍です。石材の2も5倍にして、2 × 5＝10個です。\n\nほかの 選択肢\n・「6{個|こ}」…15 × 2/5 の答えです。15を全体（木材と石材の合計）と考えてしまった数です。15は木材の数です。\n・「5{個|こ}」…15 ÷ 3 の答えで、比の1つ分の数です。石材は2つ分なので、さらに2をかけます。\n・「25{個|こ}」…木材15個と石材10個の合計です。問いは、石材だけの数です。",
  "math_g6_ratio_002":"姉と妹の比が 5：3 なので、全体は 5＋3＝8 です。姉は全体の 5/8 なので、120 × 5/8＝75cm です。120÷8＝15 が1つ分で、15 × 5＝75 と求めても同じです。妹は 15 × 3＝45cm で、75＋45＝120 になります。妹の長さの45cmと答えないように気をつけましょう。",
  "math_g6_scale_001":"縮尺1：25000は、地図上の1cmが実際は25000cmという意味です。4cmの実際の長さは 4 × 25000＝100000cm です。100cm＝1m、1000m＝1km なので、100000cm＝1000m＝1km です。\n\nほかの 選択肢\n・「100m」…100000cm を1000でわった数です。cmをmに直すときは100でわるので、100000cm＝1000m です。\n・「10km」…100000cm を10000でわった数です。cmをkmに直すときは100000でわるので、1kmになります。\n・「4km」…地図上の4cmの数を、そのまま実際の4kmとした数です。縮尺の25000をかけてから、単位を直します。",
  "math_g6_volume_001":"角柱の体積は、底面積×高さ で求めます。底面積が12cm²（すでに三角形の面積として求められているもの）、高さが5cmなので、12 × 5＝60cm³ です。底面が三角形でも、底面積が分かっていれば、さらに2でわったりしません。三角形の面積を求めるときの「÷2」を、二重にしてしまうのがよくあるまちがいです。",
  "math_g7_data_001":"中央値は、データを小さい順にならべたときの真ん中の値です。小さい順にならべると 3、5、6、7、9 で、5人の真ん中は3番目の6点です。\n\nほかの 選択肢\n・「5{点|てん}」…もとの順 3、7、5、9、6 の真ん中（3番目）の値です。小さい順にならべかえてから、真ん中を選びます。\n・「7{点|てん}」…小さい順にならべたときの4番目の値です。5人のときの真ん中は3番目です。\n・「9{点|てん}」…いちばん高い得点（最大値）です。中央値は真ん中の値で、最大の値ではありません。",
  "math_g7_equation_001":"1日にx個ずつ集めたとすると、7日間で 7x個ふえます。はじめが20個で、7日後に90個なので、20＋7x＝90 です。7x＝90－20＝70 なので、x＝10 です。たしかめると、20＋7×10＝90 になります。90÷7 のように、はじめの20個を引かずにわってしまうのは、よくあるまちがいです。",
  "math_g7_equation_002":"配る人数をx人とすると、缶詰の数は 3x＋8（3個ずつ配って8個あまる）、4x－5（4個ずつ配ると5個足りない）と2通りに表せます。缶詰の数は同じなので、3x＋8＝4x－5 の式ができます。x＝13 です。たしかめると、3×13＋8＝47、4×13－5＝47 で同じになります。",
  "math_g7_equation_003":"道のりをxmとすると、分速60mでは x/60 分、分速90mでは x/90 分かかります。差が10分なので、x/60－x/90＝10 です。60と90の最小公倍数の180を両辺にかけると、3x－2x＝1800 で、x＝1800 です。たしかめると、1800÷60＝30分、1800÷90＝20分で、差は10分になります。",
  "math_g7_equation_004":"弟をx歳とすると、兄は3x歳です。2人の年齢の和は 24歳 なので、x＋3x＝24 です。4x＝24 なので x＝6 です。たしかめると、兄は 3×6＝18歳 で、6＋18＝24 になります。24÷3＝8 のように、そのまま3でわってしまうと、兄と弟の合計が24歳であることを使えていません。",
  "math_g7_expression_001":"文字を使った式に、数を入れて値を求めることを「代入」といいます。5x＋100 の x に 60 を代入すると、5×60＋100＝300＋100＝400 です。先にかけ算をしてから、たし算をします。5×60＋100 を左からたして、(5×60)＋100 でなく 5×(60＋100) としないようにしましょう。",
  "math_g7_integer_001":"高い低いの差は、大きいほうから小さいほうをひきます。昼は3℃、朝は－8℃なので、3－(－8)＝3＋8＝11℃ です。数直線で、－8から3まで動くと、11目もり進みます。\n\nほかの 選択肢\n・「5℃」…8－3 の答えです。符号を考えず、数の大きさだけで差を出した数です。3と－8は0をはさんでいるので、差は 3＋8 です。\n・「−5℃」…3＋(－8) の答えです。差ではなく、和を求めてしまった数です。\n・「−11℃」…朝の気温から昼の気温をひいた数です。「昼は朝より高い」ので、昼から朝をひきます。",
  "math_g7_integer_002":"東へ進む向きを＋とすると、反対向きの西へ進むことを－で表します。だから、－5mは西へ5m進むことです。\n\nほかの 選択肢\n・「{東|ひがし}へ 5m {進|すす}む」…＋5mの意味です。－は反対の向きを表すので、東にはなりません。\n・「{北|きた}へ 5m {進|すす}む」…北は、東西の向きとは別の向きです。東を＋とするとき、－は東の反対向きです。\n・「{南|みなみ}へ 5m {進|すす}む」…南は、東西の向きとは別の向きです。東を＋とするとき、－は東の反対向きです。",
  "math_g7_proportion_001":"y が x に比例するとき、y＝ax と表せます。x＝4、y＝12 を代入すると、12＝4a なので a＝3 で、式は y＝3x です。x＝7 のとき、y＝3×7＝21 です。比例では、x が 4から7 になると 7/4倍 なので、12 × 7/4＝21 と求めることもできます。",
  "math_g7_sector_001":"おうぎ形の弧の長さは、円周×(中心角/360°)で求めます。円周は 2×6×3.14＝37.68cm で、中心角が60°なので 60/360＝1/6 です。37.68 ÷ 6＝6.28cm です。弧の長さは、円周の一部の長さです。面積の式（半径×半径×円周率）と、まちがえないようにしましょう。",
  "math_g8_angle_001":"n角形の内角の和は、180°×(n－2) です。五角形は n＝5 なので、180°×3＝540° です。三角形に分けると、五角形は3つの三角形に分けられるので、180°×3 と考えることもできます。\n\nほかの 選択肢\n・「360°」…四角形の内角の和です。五角形ではなく、四角形のときは 180°×2＝360° です。\n・「720°」…六角形の内角の和です。六角形のときは 180°×4＝720° です。\n・「900°」…七角形の内角の和です。七角形のときは 180°×5＝900° です。",
  "math_g8_angle_002":"多角形の外角の和は、何角形でも360°です。正多角形は外角がすべて等しいので、1つの外角は 360°÷(辺の数) です。辺の数＝360÷30＝12 で、正十二角形です。たしかめると、内角は 180°－30°＝150° で、内角の和は 150°×12＝1800°＝180°×(12－2) になります。",
  "math_g8_linear_001":"ストーブをつけてからx時間後の灯油の残りをyLとすると、y＝60－4x です。y＝20 を代入すると、20＝60－4x、4x＝40 で、x＝10 です。たしかめると、60－4×10＝20 になります。60÷4＝15 としてしまうと、灯油がなくなるまでの時間になります。残りが20Lになるまでの時間を求めます。",
  "math_g8_linear_002":"x の値を式に代入して、y を求めます。y＝2x＋3 に x＝4 を入れると、y＝2×4＋3＝8＋3＝11 です。先にかけ算をしてから、たし算をします。2×(4＋3) のように、先にたしてしまうとまちがいです。",
  "math_g8_linear_003":"x軸上の点は、y座標が0です。y＝－2x＋6 に y＝0 を入れると、0＝－2x＋6 なので 2x＝6、x＝3 です。\n\nほかの 選択肢\n・「6」…6は、x＝0 のときの y の値（切片）です。y軸と交わる点の y座標で、x軸との交点のx座標ではありません。\n・「−2」…－2は直線の傾き（xが1ふえたときのyの変化）です。交点の座標ではありません。\n・「−3」…符号を間違えた数です。0＝－2x＋6 で 2x＝6 になるので、x＝3 です。",
  "math_g8_probability_001":"2つのさいころの目の出方は 6×6＝36通りです。和が7になるのは (1,6)(2,5)(3,4)(4,3)(5,2)(6,1) の6通りなので、確率は 6/36＝1/6 です。\n\nほかの 選択肢\n・「1/12」…6通りを12通りと数えた数です。12は、和が7になる組み合わせの数ではありません。\n・「7/36」…7を分子にした数です。確率の分子は、和が7になる場合の数（6通り）です。\n・「1/3」…12/36 にあたる数です。和が7になるのは 6通りで、12通りではありません。",
  "math_g8_probability_002":"確率は、(ある事がらの起こる場合の数)÷(全部の場合の数) です。袋の中には全部で 3＋2＝5個あり、どれも同じ確率で出ます。赤玉は3個なので、確率は 3/5 です。2/5 は白玉が出る確率です。赤玉と白玉の確率をたすと、3/5＋2/5＝1 になります。",
  "math_g8_simultaneous_001":"パンをx個、おにぎりをy個とすると、個数の式 x＋y＝10 と、代金の式 100x＋150y＝1200 ができます。1つ目の式を100倍して 100x＋100y＝1000、2つ目の式からひくと、50y＝200 で y＝4 です。x＝6 です。たしかめると、100×6＋150×4＝600＋600＝1200 になります。",
  "math_g8_simultaneous_002":"十の位の数をx、一の位の数をyとすると、もとの数は 10x＋y、入れかえた数は 10y＋x です。和の式は x＋y＝11、入れかえると27大きくなる式は (10y＋x)－(10x＋y)＝27、つまり 9y－9x＝27 で y－x＝3 です。2つの式をたすと 2y＝14 で y＝7、x＝4 です。もとの数は 47 で、74－47＝27 になります。",
  "math_g8_simultaneous_003":"大人をx人、子どもをy人とすると、人数の式 x＋y＝8 と、入館料の式 500x＋300y＝3200 ができます。1つ目の式を300倍して 300x＋300y＝2400、2つ目の式からひくと、200x＝800 で x＝4 です。たしかめると、500×4＋300×4＝3200 になります。聞かれているのは大人の人数なので、子どもの人数と答えないようにしましょう。",
  "math_g9_circle_001":"同じ弧に対する円周角は、中心角の半分です。だから、中心角は円周角の2倍で、35°×2＝70° です。逆に、中心角が70°なら円周角は35°です。35°×2 ではなく、35°÷2 としないように気をつけましょう。",
  "math_g9_function_001":"y＝5x² に y＝45 を代入すると、45＝5x² なので x²＝9 です。x＝±3 ですが、時間は正の数なので x＝3秒です。たしかめると、5×3²＝5×9＝45 になります。x²＝9 の答えを 9÷2 や 9 としないようにしましょう。x は2乗する前の数なので、平方根を求めます。",
  "math_g9_function_002":"変化の割合＝(yの増加量)÷(xの増加量) です。x＝1 のとき y＝2、x＝3 のとき y＝18 なので、yの増加量は 16、xの増加量は 2 で、16÷2＝8 です。y＝ax² の変化の割合は、一定ではありません。\n\nほかの 選択肢\n・「4」…a×(xの増加量) のように計算した数のようです。y＝2x² の変化の割合は、(yの増加量)÷(xの増加量) で求めます。\n・「16」…yの増加量の16そのままです。xの増加量の2でわって、変化の割合にします。\n・「2」…xの増加量の2、または a の2です。変化の割合は (yの増加量)÷(xの増加量) で求めます。"
  };
  bank.forEach(function(q){if(EXPLANATIONS[q.id])q.explanation=EXPLANATIONS[q.id];});
})(window);
